window.APP_VIEWS={"home": "<!DOCTYPE html>\n<html lang=\"en\">\n<head><script>document.documentElement.classList.toggle(\"embedded\", window.self !== window.top);</script><base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n<title>Johann's Personal Space — Home</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F9F6F8;\n  --section-bg:#F2EDF1;\n  --card:#FFFFFF;\n  --border:#ECE3EA;\n  --pink:#E31C79;\n  --pink-deep:#B81463;\n  --pink-soft:#FCEAF3;\n  --plum:#3B2354;\n  --plum-dark:#2A1740;\n  --text:#1E1B22;\n  --muted:#746D78;\n  --muted2:#A39AA7;\n  --mint:#1F9E77;\n  --mint-soft:#EEF8F3;\n  --font-display:'Baloo 2','Segoe UI Rounded',sans-serif;\n  --font-body:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  min-height:100vh;\n  background:var(--bg);\n  color:var(--text);\n  font-family:var(--font-body);\n  display:flex;\n  justify-content:center;\n  align-items:flex-start;\n  padding:24px 14px;\n}\nbutton,input{font:inherit}\n.device{\n  width:390px;\n  max-width:100%;\n  background:#0F0B12;\n  border-radius:48px;\n  padding:12px;\n  box-shadow:0 40px 80px -30px rgba(30,10,40,.48);\n}\n.screen{\n  height:844px;\n  background:var(--bg);\n  border-radius:36px;\n  overflow:hidden;\n  position:relative;\n  display:flex;\n  flex-direction:column;\n}\n.statusbar{\n  height:34px;\n  flex:0 0 34px;\n  display:flex;\n  align-items:flex-end;\n  justify-content:space-between;\n  padding:0 26px 4px;\n  font-size:13px;\n  font-weight:600;\n  position:relative;\n}\n.dynamic-island{\n  position:absolute;\n  top:8px;\n  left:50%;\n  transform:translateX(-50%);\n  width:110px;\n  height:24px;\n  background:#0F0B12;\n  border-radius:16px;\n}\n\n/* fixed home board */\n.main{\n  flex:1;\n  min-height:0;\n  padding:10px 18px 14px;\n  display:flex;\n  flex-direction:column;\n  gap:14px;\n  overflow:hidden;\n}\n.header-row{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n}\n.app-title{\n  font-family:var(--font-display);\n  font-size:19px;\n  font-weight:700;\n  color:var(--plum);\n  margin:0;\n}\n.app-date{\n  margin:3px 0 0;\n  color:var(--muted);\n  font-size:12.5px;\n  font-weight:500;\n}\n.avatar-upload{\n  position:relative;\n  width:42px;\n  height:42px;\n  cursor:pointer;\n  flex-shrink:0;\n}\n.avatar-circle{\n  width:42px;\n  height:42px;\n  border-radius:50%;\n  background:var(--plum);\n  color:#fff;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  font-family:var(--font-display);\n  font-weight:700;\n  font-size:16px;\n  background-size:cover;\n  background-position:center;\n  border:2px solid #fff;\n  box-shadow:0 8px 18px -12px rgba(59,35,84,.46);\n}\n.avatar-cam{\n  position:absolute;\n  bottom:-2px;\n  right:-2px;\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  background:var(--pink);\n  border:2px solid var(--bg);\n  display:flex;\n  align-items:center;\n  justify-content:center;\n}\n.avatar-cam svg{width:10px;height:10px}\n\n/* greeting */\n.greeting{\n  font-family:var(--font-display);\n  font-size:25px;\n  line-height:1.08;\n  font-weight:700;\n  margin:0;\n}\n.greeting-sub{\n  margin:4px 0 0;\n  color:var(--muted);\n  font-size:13.5px;\n}\n\n/* motivation */\n.motivation{\n  border:1px solid #F0DCE7;\n  border-radius:22px;\n  background:\n    linear-gradient(180deg, rgba(252,234,243,.72), rgba(255,255,255,0) 62%),\n    #FFFFFF;\n  padding:15px 16px;\n  box-shadow:0 12px 28px -23px rgba(59,35,84,.32);\n}\n.motivation-head{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n  gap:12px;\n}\n.motivation-label{\n  color:var(--pink-deep);\n  font-size:10px;\n  font-weight:800;\n  letter-spacing:.09em;\n  margin-bottom:6px;\n}\n.motivation-text{\n  font-family:var(--font-display);\n  color:var(--plum-dark);\n  font-size:14px;\n  line-height:1.35;\n  font-weight:600;\n  max-width:265px;\n}\n.again-btn{\n  flex-shrink:0;\n  border:none;\n  background:#F8EEF4;\n  color:var(--pink-deep);\n  border-radius:999px;\n  width:34px;\n  height:34px;\n  cursor:pointer;\n  font-size:16px;\n  font-weight:700;\n}\n\n/* sections */\n.section-title{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  margin-bottom:8px;\n  color:var(--muted2);\n  font-size:10.5px;\n  font-weight:800;\n  letter-spacing:.08em;\n}\n.card{\n  background:var(--card);\n  border:1px solid var(--border);\n  border-radius:22px;\n  box-shadow:0 10px 24px -22px rgba(59,35,84,.28);\n}\n\n/* today */\n.today-card{\n  padding:14px 14px 12px;\n}\n.add-icon-btn{\n  width:28px;\n  height:28px;\n  border:none;\n  border-radius:50%;\n  background:var(--pink);\n  color:#fff;\n  font-size:17px;\n  font-weight:800;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  cursor:pointer;\n  box-shadow:0 8px 18px -10px rgba(227,28,121,.55);\n}\n.date-strip{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:5px;\n  background:var(--section-bg);\n  border-radius:999px;\n  padding:5px;\n  margin-bottom:10px;\n}\n.date-strip button{\n  border:none;\n  background:transparent;\n  color:var(--muted);\n  border-radius:999px;\n  padding:7px 4px;\n  font-size:11px;\n  font-weight:700;\n  cursor:pointer;\n}\n.date-strip button.active{\n  background:#fff;\n  color:var(--pink);\n  box-shadow:0 5px 14px -9px rgba(59,35,84,.28);\n}\n.task-row{\n  display:grid;\n  grid-template-columns:20px 58px 1fr 18px;\n  gap:8px;\n  align-items:center;\n  min-height:38px;\n  border-bottom:1px solid var(--border);\n}\n.task-row:last-child{border-bottom:none}\n.checkbox{\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  border:2px solid #E5DAE3;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  color:transparent;\n  font-size:9px;\n  font-weight:800;\n  cursor:pointer;\n}\n.checkbox.done{\n  background:var(--pink);\n  border-color:var(--pink);\n  color:#fff;\n}\n.task-time{\n  color:var(--muted);\n  font-size:10.8px;\n  font-weight:600;\n  font-variant-numeric:tabular-nums;\n}\n.task-title{\n  color:var(--text);\n  font-size:12.4px;\n  font-weight:650;\n  cursor:pointer;\n}\n.task-row.is-done .task-time,\n.task-row.is-done .task-title{\n  color:var(--muted2);\n  text-decoration:line-through;\n}\n.more-btn{\n  border:none;\n  background:none;\n  color:var(--muted2);\n  padding:0;\n  font-size:16px;\n  cursor:pointer;\n}\n.today-footer{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:10px;\n  margin-top:10px;\n  padding-top:10px;\n  border-top:1px solid var(--border);\n}\n.today-note{\n  color:var(--muted);\n  font-size:10.8px;\n  line-height:1.35;\n}\n.see-all{\n  border:none;\n  background:#F9EEF4;\n  color:var(--pink-deep);\n  border-radius:999px;\n  padding:7px 10px;\n  font-size:10px;\n  font-weight:800;\n  cursor:pointer;\n}\n\n/* health */\n.health-card{\n  padding:15px 14px 13px;\n  background:\n    linear-gradient(180deg, rgba(252,234,243,.45), rgba(255,255,255,0) 58%),\n    #FFFFFF;\n}\n.health-head{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  margin-bottom:12px;\n}\n.health-weight{\n  display:flex;\n  align-items:baseline;\n  gap:8px;\n}\n.health-weight .num{\n  font-family:var(--font-display);\n  font-size:24px;\n  line-height:1;\n  font-weight:800;\n  color:var(--plum);\n}\n.health-weight .delta{\n  color:var(--mint);\n  background:var(--mint-soft);\n  border-radius:999px;\n  padding:4px 7px;\n  font-size:9.5px;\n  font-weight:800;\n}\n.health-link{\n  border:none;\n  background:none;\n  color:var(--pink);\n  font-size:10px;\n  font-weight:800;\n  cursor:pointer;\n}\n.health-grid{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  gap:8px;\n  text-align:center;\n}\n.health-metric{\n  padding:9px 3px 7px;\n  border:1px solid #F1E8EE;\n  background:#FCFAFB;\n  border-radius:15px;\n}\n.health-icon{\n  width:22px;\n  height:22px;\n  margin:0 auto 5px;\n  color:var(--pink);\n}\n.health-value{\n  font-family:var(--font-display);\n  font-size:12.5px;\n  font-weight:700;\n  color:var(--text);\n}\n.health-value .unit{\n  font-size:8.5px;\n  color:var(--muted);\n  font-weight:600;\n}\n.health-sub{\n  margin-top:2px;\n  color:var(--muted);\n  font-size:8.8px;\n  font-weight:500;\n}\n.health-comment{\n  margin-top:10px;\n  padding-top:9px;\n  border-top:1px solid var(--border);\n  color:var(--muted);\n  font-size:10.8px;\n}\n\n/* bottom nav */\n.bottom-nav{\n  flex:0 0 62px;\n  height:62px;\n  background:#fff;\n  border-top:1px solid var(--border);\n  display:flex;\n  padding:7px 4px 9px;\n  box-shadow:0 -8px 22px -22px rgba(59,35,84,.35);\n}\n.nav-item{\n  flex:1;\n  border:none;\n  background:none;\n  color:var(--muted2);\n  display:flex;\n  flex-direction:column;\n  align-items:center;\n  gap:3px;\n  padding:3px 0;\n  cursor:pointer;\n}\n.nav-item svg{width:19px;height:19px}\n.nav-item span{font-size:9px;font-weight:600}\n.nav-item.active{color:var(--pink)}\n\n/* overlays */\n.overlay{\n  position:absolute;\n  inset:0;\n  background:rgba(30,20,35,.42);\n  display:flex;\n  align-items:flex-end;\n  opacity:0;\n  pointer-events:none;\n  transition:opacity .2s ease;\n  z-index:40;\n}\n.overlay.show{opacity:1;pointer-events:auto}\n.sheet{\n  width:100%;\n  max-height:75%;\n  overflow:auto;\n  background:#fff;\n  border-radius:24px 24px 0 0;\n  padding:12px 20px 25px;\n  transform:translateY(100%);\n  transition:transform .26s ease;\n  box-shadow:0 -18px 40px -30px rgba(59,35,84,.45);\n}\n.overlay.show .sheet{transform:translateY(0)}\n.sheet-handle{\n  width:36px;\n  height:4px;\n  background:var(--border);\n  border-radius:999px;\n  margin:0 auto 15px;\n}\n.sheet-title{\n  font-family:var(--font-display);\n  color:var(--plum);\n  font-size:20px;\n  font-weight:800;\n}\n.sheet-sub{\n  color:var(--muted);\n  font-size:11.5px;\n  margin:3px 0 12px;\n}\n.close-x{\n  position:absolute;\n  top:13px;\n  right:16px;\n  width:26px;\n  height:26px;\n  border:none;\n  border-radius:50%;\n  background:var(--section-bg);\n  color:var(--muted);\n  cursor:pointer;\n}\n.sheet-action{\n  width:100%;\n  text-align:left;\n  border:none;\n  background:none;\n  border-top:1px solid var(--border);\n  padding:12px 1px;\n  font-size:13px;\n  font-weight:650;\n  color:var(--text);\n  cursor:pointer;\n}\n.sheet-action:first-of-type{border-top:none}\n.sheet-action.danger{color:#D6413F}\n.field-label{\n  margin:12px 0 5px;\n  color:var(--muted);\n  font-size:10px;\n  font-weight:800;\n}\n.field-input{\n  width:100%;\n  border:1.5px solid var(--border);\n  background:#FBF8FA;\n  border-radius:12px;\n  padding:10px 11px;\n  outline:none;\n}\n.field-input:focus{border-color:var(--pink)}\n.submit-btn{\n  width:100%;\n  border:none;\n  background:var(--pink);\n  color:#fff;\n  border-radius:13px;\n  padding:11px;\n  font-size:11.5px;\n  font-weight:800;\n  margin-top:14px;\n  cursor:pointer;\n}\n.toast{\n  position:absolute;\n  left:50%;\n  bottom:72px;\n  transform:translate(-50%,10px);\n  background:var(--plum);\n  color:#fff;\n  border-radius:999px;\n  padding:8px 13px;\n  font-size:11px;\n  font-weight:700;\n  opacity:0;\n  transition:.2s;\n  z-index:60;\n  white-space:nowrap;\n  pointer-events:none;\n}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.completion-pop{\n  position:absolute;\n  left:50%;\n  top:50%;\n  transform:translate(-50%,-42%) scale(.96);\n  width:78%;\n  background:#fff;\n  border:1px solid #F0DCE7;\n  border-radius:20px;\n  padding:18px 16px;\n  text-align:center;\n  box-shadow:0 18px 42px -18px rgba(59,35,84,.36);\n  opacity:0;\n  pointer-events:none;\n  z-index:55;\n  transition:.22s;\n}\n.completion-pop.show{\n  opacity:1;\n  transform:translate(-50%,-50%) scale(1);\n}\n.completion-pop .emoji{font-size:28px;line-height:1;margin-bottom:7px}\n.completion-pop .title{\n  font-family:var(--font-display);\n  font-size:16px;\n  font-weight:800;\n  color:var(--plum);\n}\n.completion-pop .copy{\n  margin-top:4px;\n  color:var(--muted);\n  font-size:11px;\n  line-height:1.4;\n}\n\n@media(max-width:430px){\n  body{padding:0}\n  .device{width:100%;padding:0;border-radius:0}\n  .screen{height:100vh;border-radius:0}\n}\n</style>\n<style id=\"app-shell-embedded-overrides\">\nhtml.embedded, html.embedded body{ height:100%; padding:0 !important; margin:0 !important; align-items:stretch !important; justify-content:stretch !important; }\nhtml.embedded .device{ width:100% !important; max-width:100% !important; height:100dvh !important; background:transparent !important; padding:0 !important; border-radius:0 !important; box-shadow:none !important; }\nhtml.embedded .screen{ height:100dvh !important; border-radius:0 !important; padding-top:max(14px, env(safe-area-inset-top)) !important; }\nhtml.embedded .statusbar, html.embedded .status, html.embedded .dynamic-island, html.embedded .island{ display:none !important; }\nhtml.embedded .bottom-nav, html.embedded .bottom{ padding-bottom:max(9px, env(safe-area-inset-bottom)) !important; }\n</style></head>\n<body>\n<div class=\"device\">\n  <div class=\"screen\">\n    <div class=\"statusbar\">\n      <div class=\"dynamic-island\"></div>\n      <span>9:41</span>\n      <span>● ● ▰</span>\n    </div>\n\n    <main class=\"main\">\n      <div class=\"header-row\">\n        <div>\n          <p class=\"app-title\">Johann's Personal Space</p>\n          <p class=\"app-date\" id=\"fullDate\">Friday, September 4</p>\n        </div>\n        <div class=\"avatar-upload\" id=\"avatarUpload\">\n          <div class=\"avatar-circle\" id=\"avatarCircle\">J</div>\n          <div class=\"avatar-cam\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 8h3l1.5-2h7L17 8h3v11H4V8Z\" stroke=\"#fff\" stroke-width=\"2\" stroke-linejoin=\"round\"/><circle cx=\"12\" cy=\"13.5\" r=\"3\" stroke=\"#fff\" stroke-width=\"2\"/></svg>\n          </div>\n          <input type=\"file\" accept=\"image/*\" id=\"avatarInput\" style=\"display:none\">\n        </div>\n      </div>\n\n      <div>\n        <div class=\"greeting\">Ay, gising na. 😭</div>\n        <div class=\"greeting-sub\">Anong motivation mo today?</div>\n      </div>\n\n      <section class=\"motivation\">\n        <div class=\"motivation-head\">\n          <div>\n            <div class=\"motivation-label\">TODAY'S MOTIVATION</div>\n            <div class=\"motivation-text\" id=\"motivationText\"></div>\n          </div>\n          <button class=\"again-btn\" id=\"againBtn\">↻</button>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"section-title\">\n          <span>TODAY OVERVIEW</span>\n          <button class=\"add-icon-btn\" id=\"addIconBtn\">+</button>\n        </div>\n        <div class=\"card today-card\">\n          <div class=\"date-strip\" id=\"dateStrip\"></div>\n          <div id=\"taskList\"></div>\n          <div class=\"today-footer\">\n            <div class=\"today-note\" id=\"todayNote\"></div>\n            <button class=\"see-all\" id=\"seeAllTasks\">See all</button>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"section-title\">\n          <span>HEALTH CHECK</span>\n          <button class=\"health-link\" id=\"seeAllHealth\">See all →</button>\n        </div>\n        <div class=\"card health-card\">\n          <div class=\"health-head\">\n            <div class=\"health-weight\">\n              <span class=\"num\">70.4 kg</span>\n              <span class=\"delta\">↓ 0.6 kg this week</span>\n            </div>\n          </div>\n\n          <div class=\"health-grid\">\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"4\" y=\"7\" width=\"16\" height=\"13\" rx=\"2.5\" stroke=\"currentColor\" stroke-width=\"1.7\"/><path d=\"M9 7V5.5C9 4.1 10.3 3 12 3s3 1.1 3 2.5V7\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/><circle cx=\"12\" cy=\"13\" r=\"1.4\" fill=\"currentColor\"/></svg>\n              <div class=\"health-value\">70.4<span class=\"unit\"> kg</span></div>\n              <div class=\"health-sub\">Weight</div>\n            </div>\n\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 3c1 3-2 4-2 7a4 4 0 0 0 8 0c0-2-1-3-1.5-4 .3 2-1 3-1.5 2C15.5 6 14 4 12 3Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/><path d=\"M8 15a4 4 0 0 0 8 0\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg>\n              <div class=\"health-value\">820<span class=\"unit\"> /1450</span></div>\n              <div class=\"health-sub\">kcal</div>\n            </div>\n\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 3s6 6.5 6 11a6 6 0 0 1-12 0c0-4.5 6-11 6-11Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n              <div class=\"health-value\">4<span class=\"unit\"> / 8</span></div>\n              <div class=\"health-sub\">water</div>\n            </div>\n\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M3 17c1-3 3-3 5-4.5S12 8 13 5c.7 1.5 2.5 2 4 2 2 0 3.5 1.3 3.5 3S19.5 13 17 13H8c-2 0-4 1-5 4Z\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg>\n              <div class=\"health-value\">5,420</div>\n              <div class=\"health-sub\">steps</div>\n            </div>\n          </div>\n\n          <div class=\"health-comment\">Okayyy, may movement. 👀</div>\n        </div>\n      </section>\n    </main>\n\n    <nav class=\"bottom-nav\">\n      <button class=\"nav-item active\" data-nav=\"home\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 11.5 12 4l8 7.5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M6 10v9h12v-9\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/></svg>\n        <span>Home</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"today\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"4\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M8.5 12.5 11 15l4.5-5.5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n        <span>Tasks</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"health\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 20s-7-4.4-9.5-9C.7 7.4 3 4 6.5 4 9 4 11 6 12 7.3 13 6 15 4 17.5 4 21 4 23.3 7.4 21.5 11 19 15.6 12 20 12 20Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n        <span>Health</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"budget\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"13\" rx=\"2.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M3 10h18\" stroke=\"currentColor\" stroke-width=\"1.8\"/><circle cx=\"16.5\" cy=\"14.2\" r=\"1.1\" fill=\"currentColor\"/></svg>\n        <span>Budget</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"journal\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M5 4.5h9a2 2 0 0 1 2 2V20l-6.5-3L5 20V4.5Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n        <span>Journal</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"profile\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"8\" r=\"3.2\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M5 20c0-3.9 3.1-6 7-6s7 2.1 7 6\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>\n        <span>Profile</span>\n      </button>\n    </nav>\n\n    <!-- task detail -->\n    <div class=\"overlay\" id=\"taskOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeTaskSheet\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\" id=\"sheetTaskTitle\">Task</div>\n        <div class=\"sheet-sub\" id=\"sheetTaskTime\">Time · Today</div>\n        <button class=\"sheet-action\" id=\"actEdit\">Edit</button>\n        <button class=\"sheet-action\" id=\"actDuplicate\">Duplicate</button>\n        <button class=\"sheet-action danger\" id=\"actDelete\">Delete</button>\n      </div>\n    </div>\n\n    <!-- add task -->\n    <div class=\"overlay\" id=\"addOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeAddSheet\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\">Add to today</div>\n        <div class=\"sheet-sub\">Ano'ng kailangan natin gawin?</div>\n        <div class=\"field-label\">TASK</div>\n        <input class=\"field-input\" id=\"newTaskTitle\" placeholder=\"Pay electricity bill\">\n        <div class=\"field-label\">TIME · OPTIONAL</div>\n        <input class=\"field-input\" id=\"newTaskTime\" placeholder=\"7:00 PM\">\n        <button class=\"submit-btn\" id=\"submitAdd\">Add</button>\n      </div>\n    </div>\n\n    <!-- edit task -->\n    <div class=\"overlay\" id=\"editOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeEditSheet\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\">Edit task</div>\n        <div class=\"field-label\">TITLE</div>\n        <input class=\"field-input\" id=\"editTaskTitle\">\n        <div class=\"field-label\">TIME</div>\n        <input class=\"field-input\" id=\"editTaskTime\">\n        <button class=\"submit-btn\" id=\"saveEdit\">Save changes</button>\n      </div>\n    </div>\n\n    <!-- all tasks -->\n    <div class=\"overlay\" id=\"allTasksOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeAllTasks\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\">Today overview</div>\n        <div class=\"sheet-sub\">Everything for this day.</div>\n        <div id=\"allTasksList\"></div>\n        <button class=\"submit-btn\" id=\"addFromAll\">+ Add to today</button>\n      </div>\n    </div>\n\n    <div class=\"completion-pop\" id=\"completionPop\">\n      <div class=\"emoji\">✨</div>\n      <div class=\"title\">Ay wow. Tapos lahat?</div>\n      <div class=\"copy\">Productive legend yarn? You may now disappear peacefully. 😌</div>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n  </div>\n</div>\n\n<script src=\"./johanns-db.js\"></script>\n<script>\n(async function(){\n  await JDB.ready;\n\n  const defaultDays = {\n    thu:{label:'Thu 3',tasks:[\n      {id:'t1',time:'8:30 AM',title:'Morning run',done:true},\n      {id:'t2',time:'1:00 PM',title:'Client call',done:true},\n      {id:'t3',time:'5:00 PM',title:'Buy groceries',done:false},\n      {id:'t4',time:'9:00 PM',title:'Renew insurance',done:false}\n    ]},\n    fri:{label:'FRI 4',tasks:[\n      {id:'f1',time:'9:00 AM',title:'Team check-in',done:false},\n      {id:'f2',time:'11:30 AM',title:'Lunch',done:true},\n      {id:'f3',time:'2:30 PM',title:'Dentist',done:false},\n      {id:'f4',time:'6:00 PM',title:'30-minute walk',done:false}\n    ]},\n    sat:{label:'Sat 5',tasks:[\n      {id:'s1',time:'10:00 AM',title:'Laundry',done:false}\n    ]}\n  };\n\n  const days = {};\n  for(const key of Object.keys(defaultDays)){\n    const saved = await JDB.get('tasksByDay', 'tasks:'+key);\n    days[key] = { label: defaultDays[key].label, tasks: saved || defaultDays[key].tasks };\n  }\n  const saveDay = JDB.debounce((key)=> JDB.put('tasksByDay', 'tasks:'+key, days[key].tasks), 300);\n\n  const motivations = [\n    \"Hindi mo kailangan i-fix ang buong buhay today. Small wins muna. Main character ka pa rin kahit loading. ✨\",\n    \"Okay lang kung slow. Progress pa rin 'yan kahit hindi dramatic.\",\n    \"Isang bagay lang sa isang pagkakataon. Hindi tayo nagse-speedrun ng life today. 🌱\",\n    \"Not everything has to be productive. Minsan ang pahinga ay part ng plot. 🫶\"\n  ];\n\n  const visibleLimit = 3;\n  const celebratedDays = new Set();\n  let currentDay = 'fri';\n  let activeTask = null;\n  let motivationIndex = 0;\n\n  const dateStrip = document.getElementById('dateStrip');\n  const taskList = document.getElementById('taskList');\n  const todayNote = document.getElementById('todayNote');\n  const motivationText = document.getElementById('motivationText');\n  const allTasksList = document.getElementById('allTasksList');\n  const toast = document.getElementById('toast');\n  const completionPop = document.getElementById('completionPop');\n\n  function showToast(msg){\n    toast.textContent = msg;\n    toast.classList.add('show');\n    clearTimeout(window.__toast);\n    window.__toast = setTimeout(()=>toast.classList.remove('show'),1600);\n  }\n\n  function showCompletion(){\n    completionPop.classList.add('show');\n    clearTimeout(window.__complete);\n    window.__complete = setTimeout(()=>completionPop.classList.remove('show'),2200);\n  }\n\n  function open(id){ document.getElementById(id).classList.add('show'); }\n  function close(id){ document.getElementById(id).classList.remove('show'); }\n\n  document.querySelectorAll('.overlay').forEach(o=>{\n    o.onclick = e=>{ if(e.target===o) o.classList.remove('show'); };\n  });\n\n  function tasks(){ return days[currentDay].tasks; }\n\n  function renderDateStrip(){\n    dateStrip.innerHTML = '';\n    ['thu','fri','sat'].forEach(key=>{\n      const btn = document.createElement('button');\n      btn.textContent = days[key].label;\n      if(key===currentDay) btn.classList.add('active');\n      btn.onclick = ()=>{\n        currentDay = key;\n        renderDateStrip();\n        renderTasks();\n      };\n      dateStrip.appendChild(btn);\n    });\n  }\n\n  function renderTasks(){\n    const list = tasks();\n    taskList.innerHTML = '';\n\n    list.slice(0,visibleLimit).forEach(task=>{\n      const row = document.createElement('div');\n      row.className = 'task-row' + (task.done ? ' is-done' : '');\n      row.innerHTML = `\n        <div class=\"checkbox ${task.done ? 'done' : ''}\">${task.done ? '✓' : ''}</div>\n        <div class=\"task-time\">${task.time}</div>\n        <div class=\"task-title\">${task.title}</div>\n        <button class=\"more-btn\">⋯</button>\n      `;\n      row.querySelector('.checkbox').onclick = e=>{\n        e.stopPropagation();\n        task.done = !task.done;\n        saveDay(currentDay);\n        renderTasks();\n      };\n      row.querySelector('.task-title').onclick = ()=>openTask(task);\n      row.querySelector('.more-btn').onclick = e=>{ e.stopPropagation(); openTask(task); };\n      taskList.appendChild(row);\n    });\n\n    const done = list.filter(t=>t.done).length;\n    const allDone = list.length>0 && done===list.length;\n    const hidden = Math.max(0,list.length-visibleLimit);\n\n    if(allDone){\n      todayNote.textContent = \"Tapos na lahat. Suspiciously organized. 😌\";\n      if(!celebratedDays.has(currentDay)){\n        celebratedDays.add(currentDay);\n        setTimeout(showCompletion,120);\n      }\n    }else{\n      celebratedDays.delete(currentDay);\n      if(hidden>0) todayNote.textContent = `+ ${hidden} more waiting quietly.`;\n      else todayNote.textContent = \"One glance lang. Details when you need them.\";\n    }\n\n    renderAllTasks();\n  }\n\n  function renderAllTasks(){\n    allTasksList.innerHTML = '';\n    tasks().forEach(task=>{\n      const btn = document.createElement('button');\n      btn.className = 'sheet-action';\n      btn.textContent = `${task.done?'✓':'○'}  ${task.time} · ${task.title}`;\n      btn.onclick = ()=>{\n        close('allTasksOverlay');\n        setTimeout(()=>openTask(task),100);\n      };\n      allTasksList.appendChild(btn);\n    });\n  }\n\n  function openTask(task){\n    activeTask = task;\n    document.getElementById('sheetTaskTitle').textContent = task.title;\n    document.getElementById('sheetTaskTime').textContent = task.time + ' · Today';\n    open('taskOverlay');\n  }\n\n  function renderMotivation(){\n    motivationText.textContent = motivations[motivationIndex];\n  }\n\n  document.getElementById('againBtn').onclick = ()=>{\n    motivationIndex = (motivationIndex+1)%motivations.length;\n    renderMotivation();\n  };\n\n  document.getElementById('addIconBtn').onclick = ()=>{\n    document.getElementById('newTaskTitle').value='';\n    document.getElementById('newTaskTime').value='';\n    open('addOverlay');\n  };\n  document.getElementById('closeAddSheet').onclick = ()=>close('addOverlay');\n  document.getElementById('submitAdd').onclick = ()=>{\n    const title = document.getElementById('newTaskTitle').value.trim();\n    const time = document.getElementById('newTaskTime').value.trim() || '—';\n    if(!title){ showToast('Add a title first'); return; }\n    tasks().push({id:'new-'+Date.now(),time,title,done:false});\n    saveDay(currentDay);\n    close('addOverlay');\n    renderTasks();\n    showToast('Added to today');\n  };\n\n  document.getElementById('closeTaskSheet').onclick = ()=>close('taskOverlay');\n  document.getElementById('actDelete').onclick = ()=>{\n    const list = tasks();\n    const i = list.findIndex(t=>t.id===activeTask.id);\n    if(i>-1) list.splice(i,1);\n    saveDay(currentDay);\n    close('taskOverlay');\n    renderTasks();\n    showToast('Deleted');\n  };\n  document.getElementById('actDuplicate').onclick = ()=>{\n    tasks().push({id:'dup-'+Date.now(),time:activeTask.time,title:activeTask.title,done:false});\n    saveDay(currentDay);\n    close('taskOverlay');\n    renderTasks();\n    showToast('Duplicated');\n  };\n  document.getElementById('actEdit').onclick = ()=>{\n    close('taskOverlay');\n    document.getElementById('editTaskTitle').value = activeTask.title;\n    document.getElementById('editTaskTime').value = activeTask.time;\n    setTimeout(()=>open('editOverlay'),100);\n  };\n  document.getElementById('closeEditSheet').onclick = ()=>close('editOverlay');\n  document.getElementById('saveEdit').onclick = ()=>{\n    activeTask.title = document.getElementById('editTaskTitle').value || activeTask.title;\n    activeTask.time = document.getElementById('editTaskTime').value || activeTask.time;\n    saveDay(currentDay);\n    close('editOverlay');\n    renderTasks();\n    showToast('Saved');\n  };\n\n  document.getElementById('seeAllTasks').onclick = ()=>open('allTasksOverlay');\n  document.getElementById('closeAllTasks').onclick = ()=>close('allTasksOverlay');\n  document.getElementById('addFromAll').onclick = ()=>{\n    close('allTasksOverlay');\n    setTimeout(()=>open('addOverlay'),100);\n  };\n\n  document.getElementById('seeAllHealth').onclick = ()=>showToast('Full Health view — coming soon');\n\n  const NAV_TARGETS = {\n    today: 'johanns_tasks_soft_minimal_v2.html',\n    health: 'johanns_fitness_editorial_concept_v4_buttons.html',\n    budget: 'johanns_budget_minimal_spacious_auto_v2.html',\n    journal: 'johanns_journal_v1.html'\n  };\n  document.querySelectorAll('.nav-item').forEach(item=>{\n    item.onclick = ()=>{\n      const key = item.dataset.nav;\n      if(key==='home') return;\n      if(NAV_TARGETS[key]) window.location.href = NAV_TARGETS[key];\n      else showToast('Profile — coming soon');\n    };\n  });\n\n  const avatarUpload = document.getElementById('avatarUpload');\n  const avatarInput = document.getElementById('avatarInput');\n  const avatarCircle = document.getElementById('avatarCircle');\n  avatarUpload.onclick = ()=>avatarInput.click();\n  avatarInput.onchange = async e=>{\n    const file = e.target.files[0];\n    if(!file) return;\n    showToast('Compressing photo…');\n    const dataUrl = await JDB.compressImage(file, {maxDim:400, quality:0.8});\n    await JDB.put('profile','avatar', dataUrl);\n    avatarCircle.style.backgroundImage = `url(${dataUrl})`;\n    avatarCircle.textContent = '';\n    showToast('Profile photo updated');\n  };\n  const savedAvatar = await JDB.get('profile','avatar');\n  if(savedAvatar){ avatarCircle.style.backgroundImage = `url(${savedAvatar})`; avatarCircle.textContent=''; }\n\n  document.getElementById('fullDate').textContent = new Date().toLocaleDateString('en-US',{\n    weekday:'long',month:'long',day:'numeric'\n  });\n\n  renderDateStrip();\n  renderTasks();\n  renderMotivation();\n})();\n</script>\n<script src=\"./pwa-core.js\"></script></body>\n</html>\n", "tasks": "<!DOCTYPE html>\n<html lang=\"en\">\n<head><script>document.documentElement.classList.toggle(\"embedded\", window.self !== window.top);</script><base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n<title>Johann's Personal Space — Tasks</title>\n<style>\n:root{\n  --bg:#F5EEF3;\n  --card:#FFFFFF;\n  --border:#E7DCE5;\n  --pink:#E31C79;\n  --pink-deep:#B81463;\n  --pink-soft:#F8D2E4;\n  --plum:#3B2354;\n  --plum-2:#56336E;\n  --plum-dark:#2A1740;\n  --text:#1E1B22;\n  --muted:#6E6675;\n  --muted2:#9D95A3;\n  --cream:#FFF4E7;\n  --green:#1F9E77;\n  --red:#D6413F;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  min-height:100vh;\n  background:var(--bg);\n  font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  color:var(--text);\n  display:flex;justify-content:center;align-items:flex-start;\n  padding:24px 14px;\n}\nbutton,input{font:inherit}\n.device{\n  width:390px;\n  max-width:100%;\n  background:#0F0B12;\n  padding:11px;\n  border-radius:46px;\n  box-shadow:0 38px 78px -28px rgba(30,10,40,.46);\n}\n.screen{\n  height:844px;\n  background:var(--bg);\n  border-radius:35px;\n  overflow:hidden;\n  display:flex;\n  flex-direction:column;\n  position:relative;\n}\n.status{\n  height:33px;\n  flex:0 0 33px;\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-end;\n  padding:0 24px 4px;\n  position:relative;\n  font-size:13px;\n  font-weight:750;\n}\n.island{\n  position:absolute;\n  left:50%;\n  top:7px;\n  transform:translateX(-50%);\n  width:104px;\n  height:23px;\n  border-radius:16px;\n  background:#0F0B12;\n}\n.main{\n  flex:1;\n  min-height:0;\n  padding:10px 16px 10px;\n  display:grid;\n  grid-template-rows:auto auto 1fr auto auto;\n  gap:10px;\n  overflow:hidden;\n}\n.header{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n}\n.kicker{font-size:11.5px;color:var(--muted);margin-bottom:2px}\n.page-title{\n  margin:0;\n  color:var(--plum-dark);\n  font-size:25px;\n  line-height:1;\n  letter-spacing:-.03em;\n  font-weight:860;\n}\n.avatar{\n  width:40px;height:40px;border-radius:50%;\n  background:var(--plum);color:#fff;\n  display:grid;place-items:center;\n  font-weight:850;\n}\n.intro{\n  padding:11px 13px;\n  border-radius:18px;\n  background:var(--pink-soft);\n  border:1px solid #F3BDD7;\n}\n.intro h2{\n  margin:0 0 2px;\n  font-size:22px;\n  line-height:1.08;\n  letter-spacing:-.025em;\n  color:var(--plum-dark);\n}\n.intro p{\n  margin:0;\n  color:var(--muted);\n  font-size:13px;\n}\n\n/* TODAY HERO */\n.today{\n  background:#fff;\n  border:1px solid var(--border);\n  border-radius:22px;\n  overflow:hidden;\n  min-height:0;\n  display:flex;\n  flex-direction:column;\n}\n.today-band{\n  flex:0 0 auto;\n  background:var(--plum);\n  color:#fff;\n  padding:10px 13px;\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n}\n.today-band .label{\n  font-size:11px;\n  font-weight:850;\n  letter-spacing:.09em;\n}\n.plus{\n  width:28px;height:28px;border:none;border-radius:50%;\n  background:var(--pink);color:#fff;font-size:19px;line-height:1;\n  display:grid;place-items:center;font-weight:850;cursor:pointer;\n}\n.today-body{\n  padding:10px 12px 11px;\n  min-height:0;\n  display:flex;\n  flex-direction:column;\n}\n.days{\n  flex:0 0 auto;\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:5px;\n  background:#F0E8EE;\n  padding:4px;\n  border-radius:999px;\n  margin-bottom:7px;\n}\n.day{\n  border:none;background:transparent;\n  color:var(--muted);\n  border-radius:999px;\n  padding:7px 4px;\n  font-size:11.5px;\n  font-weight:750;\n  cursor:pointer;\n}\n.day.active{background:var(--pink);color:#fff}\n.task-list{\n  flex:1;\n  min-height:0;\n  overflow:hidden;\n}\n.task{\n  display:grid;\n  grid-template-columns:22px 61px 1fr 18px;\n  gap:7px;\n  align-items:start;\n  padding:7px 0;\n  border-bottom:1px solid var(--border);\n}\n.task:last-child{border-bottom:none}\n.check{\n  width:19px;height:19px;border-radius:50%;\n  border:2px solid var(--border);\n  background:#fff;color:#fff;\n  display:grid;place-items:center;\n  cursor:pointer;font-size:10px;font-weight:900;\n}\n.task.done .check{background:var(--pink);border-color:var(--pink)}\n.task-time{\n  font-size:11px;color:var(--muted);font-weight:700;\n  font-variant-numeric:tabular-nums;padding-top:2px;\n}\n.task-name{\n  font-size:12.7px;\n  line-height:1.2;\n  font-weight:700;\n  cursor:pointer;\n}\n.task-note{\n  font-size:9.3px;\n  color:var(--pink);\n  font-weight:800;\n  margin-top:2px;\n}\n.task.done .task-time,\n.task.done .task-name{\n  color:var(--muted2);\n  text-decoration:line-through;\n}\n.more{\n  border:none;background:none;color:var(--muted2);\n  padding:0;font-size:16px;cursor:pointer;\n}\n.today-footer{\n  flex:0 0 auto;\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-end;\n  gap:8px;\n  padding-top:8px;\n  margin-top:4px;\n  border-top:1px solid var(--border);\n}\n.today-footer-left{\n  font-size:11.5px;\n  color:var(--muted);\n  line-height:1.35;\n}\n.today-footer-left b{color:var(--plum-dark)}\n.see-all{\n  border:none;\n  background:var(--pink-soft);\n  color:var(--pink-deep);\n  border-radius:999px;\n  padding:7px 9px;\n  font-size:10.5px;\n  font-weight:850;\n  cursor:pointer;\n}\n\n/* BENTO */\n.bento{\n  display:grid;\n  grid-template-columns:1.25fr .9fr;\n  gap:9px;\n}\n.reminders{\n  border-radius:20px;\n  padding:12px;\n  background:var(--pink);\n  color:white;\n  min-height:135px;\n}\n.checkin{\n  border-radius:20px;\n  padding:12px;\n  background:var(--plum);\n  color:white;\n  min-height:135px;\n}\n.card-title{\n  font-size:10.5px;\n  font-weight:900;\n  letter-spacing:.08em;\n  margin-bottom:5px;\n}\n.reminders .card-title{color:#fff}\n.checkin .card-title{color:var(--pink-soft)}\n.card-copy{\n  font-size:11px;\n  line-height:1.35;\n  margin:0 0 9px;\n}\n.reminders .card-copy{color:#FFEAF4}\n.checkin .card-copy{color:#E9DFF0}\n.reminder{\n  border-top:1px solid rgba(255,255,255,.28);\n  padding:7px 0;\n}\n.reminder:first-of-type{border-top:none;padding-top:0}\n.reminder-time{font-size:9.5px;font-weight:850;opacity:.82}\n.reminder-name{font-size:12px;font-weight:800;margin-top:1px}\n.reminders .text-link{\n  border:none;background:none;color:#fff;\n  padding:5px 0 0;font-size:10px;font-weight:850;cursor:pointer;\n}\n.mood-grid{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:6px;\n}\n.mood{\n  border:1px solid rgba(255,255,255,.2);\n  background:rgba(255,255,255,.12);\n  color:#fff;\n  border-radius:12px;\n  padding:7px 3px;\n  display:flex;\n  flex-direction:column;\n  align-items:center;\n  gap:2px;\n  cursor:pointer;\n}\n.mood .emoji{font-size:18px;line-height:1}\n.mood .mood-label{font-size:9.5px;font-weight:750}\n.mood.active{\n  background:var(--pink);\n  border-color:var(--pink);\n}\n.mood-response{\n  margin-top:7px;\n  font-size:9.7px;\n  line-height:1.3;\n  color:#EDE3F1;\n}\n\n/* COMING UP */\n.coming{\n  background:var(--card);\n  border:1px solid var(--border);\n  border-radius:20px;\n  overflow:hidden;\n}\n.coming-band{\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  background:var(--plum-dark);\n  color:#fff;\n  padding:9px 12px;\n}\n.coming-band .label{\n  font-size:10.5px;\n  font-weight:900;\n  letter-spacing:.08em;\n}\n.coming-band button{\n  border:none;background:none;color:var(--pink-soft);\n  font-size:10px;font-weight:850;cursor:pointer;\n}\n.coming-copy{\n  margin:0;\n  padding:8px 12px 0;\n  font-size:10.7px;\n  color:var(--muted);\n}\n.coming-grid{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:8px;\n  padding:8px 12px 11px;\n}\n.date-card{\n  border-radius:15px;\n  padding:10px;\n  cursor:pointer;\n}\n.date-card.pink{\n  background:var(--pink-soft);\n  color:var(--plum-dark);\n}\n.date-card.plum{\n  background:var(--plum-2);\n  color:#fff;\n}\n.date-top{\n  font-size:9.5px;\n  font-weight:900;\n  letter-spacing:.08em;\n  opacity:.8;\n}\n.date-main{\n  font-size:16px;\n  line-height:1;\n  font-weight:900;\n  margin:2px 0 7px;\n}\n.event{\n  font-size:10px;\n  line-height:1.25;\n  margin-top:5px;\n}\n.event b{font-weight:850}\n\n/* bottom nav */\n.bottom{\n  flex:0 0 62px;\n  height:62px;\n  background:#fff;\n  border-top:1px solid var(--border);\n  display:grid;\n  grid-template-columns:repeat(6,1fr);\n  padding:7px 4px 9px;\n}\n.nav{\n  border:none;background:none;\n  color:var(--muted2);\n  display:flex;flex-direction:column;align-items:center;gap:3px;\n  font-size:9px;font-weight:750;cursor:pointer;\n}\n.nav-dot{\n  width:18px;height:18px;border-radius:6px;\n  border:1.7px solid currentColor;\n}\n.nav.active{color:var(--pink)}\n.nav.active .nav-dot{\n  background:var(--pink);\n  border-color:var(--pink);\n}\n\n/* overlays */\n.overlay{\n  position:absolute;inset:0;\n  background:rgba(27,17,32,.42);\n  display:none;align-items:flex-end;\n  z-index:30;\n}\n.overlay.show{display:flex}\n.sheet{\n  width:100%;\n  background:#fff;\n  border-radius:24px 24px 0 0;\n  padding:12px 18px 23px;\n  max-height:72%;\n  overflow:auto;\n}\n.handle{\n  width:36px;height:4px;border-radius:999px;\n  background:var(--border);\n  margin:0 auto 15px;\n}\n.sheet h3{margin:0 0 10px;color:var(--plum-dark)}\n.field{margin:10px 0}\n.field label{\n  display:block;\n  font-size:10.5px;\n  font-weight:850;\n  color:var(--muted);\n  margin-bottom:5px;\n}\n.field input{\n  width:100%;\n  border:1.5px solid var(--border);\n  background:var(--bg);\n  color:var(--text);\n  border-radius:12px;\n  padding:10px 11px;\n  outline:none;\n}\n.field input:focus{border-color:var(--pink)}\n.primary{\n  width:100%;\n  border:none;\n  background:var(--pink);\n  color:#fff;\n  padding:11px;\n  border-radius:12px;\n  font-weight:850;\n  cursor:pointer;\n  margin-top:7px;\n}\n.secondary{\n  width:100%;\n  border:none;background:none;\n  color:var(--muted);\n  padding:9px;\n  cursor:pointer;\n}\n.action{\n  width:100%;\n  border:none;background:none;\n  text-align:left;\n  border-top:1px solid var(--border);\n  padding:12px 1px;\n  font-weight:700;\n  cursor:pointer;\n}\n.action.danger{color:var(--red)}\n.toast{\n  position:absolute;\n  left:50%;\n  bottom:72px;\n  transform:translate(-50%,10px);\n  background:var(--plum-dark);\n  color:#fff;\n  border-radius:999px;\n  padding:8px 13px;\n  font-size:11px;\n  font-weight:750;\n  opacity:0;\n  pointer-events:none;\n  transition:.2s;\n  z-index:50;\n  white-space:nowrap;\n}\n.toast.show{\n  opacity:1;\n  transform:translate(-50%,0);\n}\n.placeholder{\n  flex:1;\n  display:grid;\n  place-items:center;\n  text-align:center;\n  padding:30px;\n}\n.placeholder h2{margin:0 0 5px;color:var(--plum-dark)}\n.placeholder p{margin:0;color:var(--muted);font-size:13px}\n\n@media(max-width:430px){\n  body{padding:0}\n  .device{width:100%;padding:0;border-radius:0}\n  .screen{height:100vh;border-radius:0}\n}\n</style>\n\n<style id=\"tasks-soft-minimal-pass\">\n:root{\n  --bg:#F9F6F8;\n  --card:#FFFFFF;\n  --border:#ECE3EA;\n  --pink:#E31C79;\n  --pink-deep:#B81463;\n  --pink-soft:#FCEAF3;\n  --plum:#3B2354;\n  --plum-2:#6A557A;\n  --plum-dark:#2A1740;\n  --text:#1E1B22;\n  --muted:#746D78;\n  --muted2:#A39AA7;\n  --cream:#FFF9F1;\n}\n\n/* Softer app canvas */\n.main{\n  padding:11px 17px 11px;\n  gap:12px;\n}\n\n/* Header */\n.kicker{\n  color:var(--muted);\n}\n.page-title{\n  color:var(--plum);\n}\n.avatar{\n  background:var(--plum);\n  border:2px solid #fff;\n  box-shadow:0 7px 18px -12px rgba(59,35,84,.42);\n}\n\n/* Greeting: remove the heavy pink block */\n.intro{\n  padding:3px 1px 1px;\n  border:0;\n  background:transparent;\n}\n.intro h2{\n  color:var(--text);\n  font-size:23px;\n}\n.intro p{\n  margin-top:4px;\n  line-height:1.35;\n}\n\n/* TODAY'S OVERVIEW: white card with soft tint instead of solid plum header */\n.today{\n  border-color:#EEE5EB;\n  box-shadow:0 12px 28px -22px rgba(59,35,84,.36);\n  background:\n    radial-gradient(circle at 98% 0%, rgba(227,28,121,.055), transparent 31%),\n    #FFFFFF;\n}\n.today-band{\n  background:transparent;\n  color:var(--plum);\n  padding:13px 14px 7px;\n}\n.today-band .label{\n  color:var(--muted2);\n  font-size:10px;\n}\n.plus{\n  background:var(--pink);\n  box-shadow:0 8px 18px -11px rgba(227,28,121,.62);\n}\n.today-body{\n  padding:6px 13px 13px;\n}\n.days{\n  background:#F2EDF1;\n  padding:5px;\n  margin-bottom:9px;\n}\n.day{\n  padding:7px 4px;\n}\n.day.active{\n  background:#FFFFFF;\n  color:var(--pink);\n  box-shadow:0 5px 14px -9px rgba(59,35,84,.30);\n}\n.task{\n  padding:8px 0;\n}\n.check{\n  border-color:#E7DCE5;\n}\n.task.done .check{\n  background:var(--pink);\n  border-color:var(--pink);\n}\n.task-note{\n  color:var(--pink-deep);\n}\n.today-footer{\n  padding-top:9px;\n}\n.see-all{\n  background:#F9EEF4;\n  color:var(--pink-deep);\n  padding:7px 10px;\n}\n\n/* Bento cards: keep them distinct without solid color slabs */\n.bento{\n  gap:11px;\n}\n\n.reminders,\n.checkin{\n  color:var(--text);\n  border:1px solid #EEE5EB;\n  box-shadow:0 10px 24px -21px rgba(59,35,84,.32);\n  padding:14px;\n  min-height:135px;\n}\n\n.reminders{\n  background:\n    linear-gradient(180deg, rgba(252,234,243,.70), rgba(255,255,255,0) 55%),\n    #FFFFFF;\n}\n\n.checkin{\n  background:\n    linear-gradient(180deg, rgba(243,238,246,.85), rgba(255,255,255,0) 58%),\n    #FFFFFF;\n}\n\n.reminders .card-title,\n.checkin .card-title{\n  color:var(--plum);\n}\n.reminders .card-copy,\n.checkin .card-copy{\n  color:var(--muted);\n  line-height:1.4;\n}\n.reminder{\n  border-top:1px solid var(--border);\n  padding:8px 0;\n}\n.reminder-time{\n  color:var(--muted2);\n  opacity:1;\n}\n.reminder-name{\n  color:var(--text);\n}\n.reminders .text-link{\n  color:var(--pink);\n  padding-top:7px;\n}\n\n/* Mood buttons now look soft and tactile */\n.mood{\n  border:1px solid #E8DEE7;\n  background:#FBF8FA;\n  color:var(--text);\n  box-shadow:0 6px 14px -13px rgba(59,35,84,.28);\n}\n.mood:hover{\n  background:#F8F1F5;\n}\n.mood.active{\n  background:var(--pink-soft);\n  border-color:#F1CADD;\n  color:var(--pink-deep);\n}\n.mood-response{\n  color:var(--muted);\n  margin-top:8px;\n}\n\n/* Coming Up: remove dark header and solid purple date card */\n.coming{\n  border-color:#EEE5EB;\n  box-shadow:0 10px 24px -21px rgba(59,35,84,.30);\n  background:#FFFFFF;\n}\n.coming-band{\n  background:transparent;\n  color:var(--plum);\n  padding:12px 13px 5px;\n}\n.coming-band .label{\n  color:var(--muted2);\n  font-size:10px;\n}\n.coming-band button{\n  color:var(--pink);\n}\n.coming-copy{\n  padding:4px 13px 0;\n  color:var(--muted);\n}\n.coming-grid{\n  gap:10px;\n  padding:9px 13px 12px;\n}\n.date-card{\n  border:1px solid #EEE4EA;\n  box-shadow:0 7px 16px -15px rgba(59,35,84,.25);\n  padding:11px;\n}\n.date-card.pink{\n  background:#FDF0F6;\n  color:var(--plum-dark);\n}\n.date-card.plum{\n  background:#F4EFF7;\n  color:var(--plum-dark);\n}\n.date-top{\n  color:var(--pink-deep);\n  opacity:.82;\n}\n.event{\n  color:var(--muted);\n}\n.event b{\n  color:var(--text);\n}\n\n/* Bottom nav */\n.bottom{\n  border-top-color:#EEE6EB;\n  box-shadow:0 -8px 22px -22px rgba(59,35,84,.35);\n}\n\n/* Sheets */\n.sheet{\n  box-shadow:0 -18px 40px -30px rgba(59,35,84,.45);\n}\n.field input{\n  background:#FBF8FA;\n}\n.primary{\n  background:var(--pink);\n  box-shadow:0 8px 18px -12px rgba(227,28,121,.55);\n}\n</style>\n\n\n<style id=\"tasks-completion-popup-pass\">\n  .today-footer{\n    justify-content:flex-end;\n    align-items:center;\n    min-height:38px;\n  }\n\n  .today-footer-left{\n    display:none !important;\n  }\n\n  .completion-pop{\n    position:absolute;\n    left:50%;\n    top:50%;\n    transform:translate(-50%,-42%) scale(.96);\n    width:78%;\n    background:#FFFFFF;\n    color:var(--plum-dark);\n    border:1px solid #F0DCE7;\n    border-radius:20px;\n    padding:18px 16px;\n    text-align:center;\n    box-shadow:0 18px 42px -18px rgba(59,35,84,.36);\n    opacity:0;\n    pointer-events:none;\n    z-index:55;\n    transition:opacity .2s ease, transform .22s ease;\n  }\n\n  .completion-pop.show{\n    opacity:1;\n    transform:translate(-50%,-50%) scale(1);\n  }\n\n  .completion-pop .emoji{\n    font-size:28px;\n    line-height:1;\n    margin-bottom:7px;\n  }\n\n  .completion-pop .title{\n    font-weight:850;\n    font-size:15px;\n    color:var(--plum);\n  }\n\n  .completion-pop .copy{\n    margin-top:4px;\n    font-size:11px;\n    line-height:1.4;\n    color:var(--muted);\n  }\n</style>\n\n<style id=\"app-shell-embedded-overrides\">\nhtml.embedded, html.embedded body{ height:100%; padding:0 !important; margin:0 !important; align-items:stretch !important; justify-content:stretch !important; }\nhtml.embedded .device{ width:100% !important; max-width:100% !important; height:100dvh !important; background:transparent !important; padding:0 !important; border-radius:0 !important; box-shadow:none !important; }\nhtml.embedded .screen{ height:100dvh !important; border-radius:0 !important; padding-top:max(14px, env(safe-area-inset-top)) !important; }\nhtml.embedded .statusbar, html.embedded .status, html.embedded .dynamic-island, html.embedded .island{ display:none !important; }\nhtml.embedded .bottom-nav, html.embedded .bottom{ padding-bottom:max(9px, env(safe-area-inset-bottom)) !important; }\n</style></head>\n<body>\n\n<div class=\"device\">\n  <div class=\"screen\">\n\n    <div class=\"status\">\n      <div class=\"island\"></div>\n      <span>9:41</span>\n      <span>● ● ▰</span>\n    </div>\n\n    <main id=\"tasksPage\" class=\"main\">\n      <div class=\"header\">\n        <div>\n          <div class=\"kicker\">Johann’s Personal Space</div>\n          <h1 class=\"page-title\">Tasks</h1>\n        </div>\n        <div class=\"avatar\">J</div>\n      </div>\n\n      <div class=\"intro\">\n        <h2>Yoohoo, dito ang tingin. 👀</h2>\n        <p>Ano bang ganap natin today?</p>\n      </div>\n\n      <section class=\"today\">\n        <div class=\"today-band\">\n          <div class=\"label\">TODAY’S OVERVIEW</div>\n          <button class=\"plus\" id=\"openAdd\">+</button>\n        </div>\n\n        <div class=\"today-body\">\n          <div class=\"days\">\n            <button class=\"day\" data-day=\"thu\">Thu 3</button>\n            <button class=\"day active\" data-day=\"fri\">FRI 4</button>\n            <button class=\"day\" data-day=\"sat\">Sat 5</button>\n          </div>\n\n          <div class=\"task-list\" id=\"taskList\"></div>\n\n          <div class=\"today-footer\">\n            <div class=\"today-footer-left\" id=\"summary\"></div>\n            <button class=\"see-all\" id=\"seeAllTasks\">See all</button>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"bento\">\n        <article class=\"reminders\">\n          <div class=\"card-title\">🔔 REMINDERS</div>\n          <p class=\"card-copy\">Para hindi maging “ay oo nga pala.” 😭</p>\n\n          <div id=\"reminderPreview\"></div>\n\n          <button class=\"text-link\" id=\"openReminders\">See all →</button>\n        </article>\n\n        <article class=\"checkin\">\n          <div class=\"card-title\">QUICK CHECK-IN</div>\n          <p class=\"card-copy\">May energy pa ba tayo?</p>\n\n          <div class=\"mood-grid\">\n            <button class=\"mood\" data-mood=\"okay\">\n              <span class=\"emoji\">😌</span>\n              <span class=\"mood-label\">Okay</span>\n            </button>\n\n            <button class=\"mood\" data-mood=\"meh\">\n              <span class=\"emoji\">😐</span>\n              <span class=\"mood-label\">Meh</span>\n            </button>\n\n            <button class=\"mood\" data-mood=\"konti\">\n              <span class=\"emoji\">🥲</span>\n              <span class=\"mood-label\">Konti</span>\n            </button>\n\n            <button class=\"mood\" data-mood=\"nope\">\n              <span class=\"emoji\">🫠</span>\n              <span class=\"mood-label\">Nope</span>\n            </button>\n          </div>\n\n          <div class=\"mood-response\" id=\"moodResponse\">Pick one. Walang judgment dito.</div>\n        </article>\n      </section>\n\n      <section class=\"coming\">\n        <div class=\"coming-band\">\n          <div class=\"label\">COMING UP</div>\n          <button id=\"calendarBtn\">View calendar →</button>\n        </div>\n\n        <p class=\"coming-copy\">Future Johann made plans, apparently.</p>\n\n        <div class=\"coming-grid\">\n          <article class=\"date-card pink\" data-open-day=\"sat\">\n            <div class=\"date-top\">SAT</div>\n            <div class=\"date-main\">SEP 5</div>\n            <div class=\"event\"><b>10:00 AM</b> · Grocery run</div>\n            <div class=\"event\"><b>4:00 PM</b> · Family dinner</div>\n          </article>\n\n          <article class=\"date-card plum\" data-open-day=\"mon\">\n            <div class=\"date-top\">MON</div>\n            <div class=\"date-main\">SEP 7</div>\n            <div class=\"event\"><b>9:00 AM</b> · Submit report</div>\n            <div class=\"event\"><b>3:00 PM</b> · Dentist</div>\n          </article>\n        </div>\n      </section>\n    </main>\n\n    <main id=\"placeholder\" class=\"placeholder\" style=\"display:none\">\n      <div>\n        <h2 id=\"placeholderTitle\">Home</h2>\n        <p>Placeholder — Tasks is the fully designed non-scroll screen.</p>\n      </div>\n    </main>\n\n    <nav class=\"bottom\">\n      <button class=\"nav\" data-nav=\"Home\"><span class=\"nav-dot\"></span>Home</button>\n      <button class=\"nav active\" data-nav=\"Tasks\"><span class=\"nav-dot\"></span>Tasks</button>\n      <button class=\"nav\" data-nav=\"Health\"><span class=\"nav-dot\"></span>Health</button>\n      <button class=\"nav\" data-nav=\"Budget\"><span class=\"nav-dot\"></span>Budget</button>\n      <button class=\"nav\" data-nav=\"Journal\"><span class=\"nav-dot\"></span>Journal</button>\n      <button class=\"nav\" data-nav=\"Profile\"><span class=\"nav-dot\"></span>Profile</button>\n    </nav>\n\n    <!-- Add task -->\n    <div class=\"overlay\" id=\"addOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Add to today</h3>\n\n        <div class=\"field\">\n          <label>ANO’NG KAILANGAN NATIN GAWIN?</label>\n          <input id=\"newTask\" placeholder=\"e.g. Pay electricity bill\">\n        </div>\n\n        <div class=\"field\">\n          <label>TIME · OPTIONAL</label>\n          <input id=\"newTime\" type=\"time\">\n        </div>\n\n        <button class=\"primary\" id=\"saveNew\">Add</button>\n        <button class=\"secondary\" id=\"closeAdd\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Task detail -->\n    <div class=\"overlay\" id=\"taskOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3 id=\"taskSheetTitle\">Task</h3>\n        <button class=\"action\" id=\"toggleDone\">Mark done</button>\n        <button class=\"action\" id=\"editTaskAction\">Edit</button>\n        <button class=\"action\" id=\"moveTaskAction\">Move to another day</button>\n        <button class=\"action\" id=\"duplicateTaskAction\">Duplicate</button>\n        <button class=\"action danger\" id=\"deleteTaskAction\">Delete</button>\n        <button class=\"secondary\" id=\"closeTask\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- See all tasks -->\n    <div class=\"overlay\" id=\"allTasksOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Everything today</h3>\n        <div id=\"allTasksList\"></div>\n        <button class=\"primary\" id=\"addFromAll\">+ Add to today</button>\n        <button class=\"secondary\" id=\"closeAllTasks\">Close</button>\n      </div>\n    </div>\n\n    <!-- Reminders -->\n    <div class=\"overlay\" id=\"reminderOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Reminders</h3>\n        <div id=\"reminderFullList\"></div>\n        <button class=\"primary\" id=\"addReminder\">+ Add reminder</button>\n        <button class=\"secondary\" id=\"closeReminders\">Close</button>\n      </div>\n    </div>\n\n    <!-- Reminder add/edit form -->\n    <div class=\"overlay\" id=\"reminderFormOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3 id=\"reminderFormTitle\">Add reminder</h3>\n        <div class=\"field\">\n          <label>ANO'NG IPAALALA?</label>\n          <input id=\"reminderNameInput\" placeholder=\"e.g. Call dentist\">\n        </div>\n        <div class=\"field\">\n          <label>TIME</label>\n          <input id=\"reminderTimeInput\" type=\"time\">\n        </div>\n        <button class=\"primary\" id=\"saveReminder\">Save</button>\n        <button class=\"secondary\" id=\"deleteReminder\" style=\"color:#D6413F\">Delete</button>\n        <button class=\"secondary\" id=\"cancelReminderForm\">Cancel</button>\n      </div>\n    </div>\n\n\n    <div class=\"completion-pop\" id=\"completionPop\">\n      <div class=\"emoji\">✨</div>\n      <div class=\"title\">Ay wow. Tapos lahat?</div>\n      <div class=\"copy\">Productive legend yarn? You may now disappear peacefully. 😌</div>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n  </div>\n</div>\n\n<script src=\"./johanns-db.js\"></script>\n<script>\n(async () => {\n  await JDB.ready;\n\n  const defaultTasks = {\n    thu:[\n      {time:\"6:00 AM\", name:\"Wake up\", done:true, note:\"usual\"},\n      {time:\"8:30 AM\", name:\"Morning run\", done:true},\n      {time:\"1:00 PM\", name:\"Client call\", done:false}\n    ],\n    fri:[\n      {time:\"6:00 AM\", name:\"Wake up\", done:true, note:\"usual\"},\n      {time:\"7:00 AM\", name:\"Breakfast\", done:true},\n      {time:\"9:00 AM\", name:\"Team check-in\", done:false},\n      {time:\"2:30 PM\", name:\"Dentist\", done:false},\n      {time:\"6:00 PM\", name:\"30-minute walk\", done:false},\n      {time:\"—\", name:\"Buy groceries\", done:false, note:\"← from yesterday\"}\n    ],\n    sat:[\n      {time:\"10:00 AM\", name:\"Grocery run\", done:false},\n      {time:\"4:00 PM\", name:\"Family dinner\", done:false}\n    ]\n  };\n\n  const tasks = {};\n  for(const key of Object.keys(defaultTasks)){\n    const saved = await JDB.get('tasksByDay', 'tasks:'+key);\n    tasks[key] = saved || defaultTasks[key];\n  }\n  const saveDay = JDB.debounce((key)=> JDB.put('tasksByDay', 'tasks:'+key, tasks[key]), 300);\n\n  let currentDay = \"fri\";\n  let activeIndex = null;\n  const visibleLimit = 4;\n  const celebratedDays = new Set();\n\n  const taskList = document.getElementById(\"taskList\");\n  const summary = document.getElementById(\"summary\");\n  const toast = document.getElementById(\"toast\");\n\n  function showToast(msg){\n    toast.textContent = msg;\n    toast.classList.add(\"show\");\n    clearTimeout(window.__toast);\n    window.__toast = setTimeout(()=>toast.classList.remove(\"show\"),1600);\n  }\n\n  function showCompletionPop(){\n    const pop = document.getElementById(\"completionPop\");\n    pop.classList.add(\"show\");\n    clearTimeout(window.__completionPop);\n    window.__completionPop = setTimeout(()=>pop.classList.remove(\"show\"),2300);\n  }\n\n  function render(){\n    const list = tasks[currentDay];\n    taskList.innerHTML = \"\";\n\n    list.slice(0,visibleLimit).forEach((task,index)=>{\n      const row = document.createElement(\"div\");\n      row.className = \"task\" + (task.done ? \" done\" : \"\");\n      row.innerHTML = `\n        <button class=\"check\">${task.done ? \"✓\" : \"\"}</button>\n        <div class=\"task-time\">${task.time}</div>\n        <div>\n          <div class=\"task-name\">${task.name}</div>\n          ${task.note ? `<div class=\"task-note\">${task.note}</div>` : \"\"}\n        </div>\n        <button class=\"more\">⋯</button>\n      `;\n\n      row.querySelector(\".check\").onclick = () => {\n        task.done = !task.done;\n        saveDay(currentDay);\n        render();\n      };\n\n      const openTask = () => {\n        activeIndex = index;\n        document.getElementById(\"taskSheetTitle\").textContent = task.name;\n        document.getElementById(\"toggleDone\").textContent = task.done ? \"Mark not done\" : \"Mark done\";\n        document.getElementById(\"taskOverlay\").classList.add(\"show\");\n      };\n\n      row.querySelector(\".task-name\").onclick = openTask;\n      row.querySelector(\".more\").onclick = openTask;\n      taskList.appendChild(row);\n    });\n\n    const done = list.filter(t=>t.done).length;\n    const allDone = list.length > 0 && done === list.length;\n\n    // No persistent \"X done, Y to go\" copy on the card.\n    summary.innerHTML = \"\";\n\n    // Celebrate only when this day's entire list becomes completed.\n    if(allDone && !celebratedDays.has(currentDay)){\n      celebratedDays.add(currentDay);\n      setTimeout(showCompletionPop, 120);\n    }\n\n    // If a task is unchecked later, allow the celebration to happen again\n    // when the list is completed next time.\n    if(!allDone){\n      celebratedDays.delete(currentDay);\n    }\n  }\n\n  document.querySelectorAll(\".day\").forEach(btn=>{\n    btn.onclick = ()=>{\n      document.querySelectorAll(\".day\").forEach(b=>b.classList.remove(\"active\"));\n      btn.classList.add(\"active\");\n      currentDay = btn.dataset.day;\n      render();\n    };\n  });\n\n  // Add task\n  const addOverlay = document.getElementById(\"addOverlay\");\n  document.getElementById(\"openAdd\").onclick = ()=>addOverlay.classList.add(\"show\");\n  document.getElementById(\"closeAdd\").onclick = ()=>addOverlay.classList.remove(\"show\");\n  addOverlay.onclick = e => { if(e.target===addOverlay) addOverlay.classList.remove(\"show\"); };\n\n  function displayTime(raw){\n    if(!raw) return \"—\";\n    let [h,m]=raw.split(\":\").map(Number);\n    const suffix=h>=12?\"PM\":\"AM\";\n    h=h%12||12;\n    return `${h}:${String(m).padStart(2,\"0\")} ${suffix}`;\n  }\n\n  document.getElementById(\"saveNew\").onclick = ()=>{\n    const name = document.getElementById(\"newTask\").value.trim();\n    const time = displayTime(document.getElementById(\"newTime\").value);\n    if(!name){ showToast(\"Yoohoo, lagyan natin ng task. 😭\"); return; }\n\n    tasks[currentDay].push({time,name,done:false});\n    saveDay(currentDay);\n    document.getElementById(\"newTask\").value=\"\";\n    document.getElementById(\"newTime\").value=\"\";\n    addOverlay.classList.remove(\"show\");\n    render();\n    showToast(\"Added. Very organized of you.\");\n  };\n\n  // Task sheet\n  const taskOverlay = document.getElementById(\"taskOverlay\");\n  document.getElementById(\"closeTask\").onclick = ()=>taskOverlay.classList.remove(\"show\");\n  taskOverlay.onclick = e => { if(e.target===taskOverlay) taskOverlay.classList.remove(\"show\"); };\n\n  document.getElementById(\"toggleDone\").onclick = ()=>{\n    const t = tasks[currentDay][activeIndex];\n    t.done = !t.done;\n    saveDay(currentDay);\n    taskOverlay.classList.remove(\"show\");\n    render();\n  };\n\n  document.getElementById(\"duplicateTaskAction\").onclick = ()=>{\n    const t = tasks[currentDay][activeIndex];\n    tasks[currentDay].splice(activeIndex+1,0,{...t,done:false,note:undefined});\n    saveDay(currentDay);\n    taskOverlay.classList.remove(\"show\");\n    render();\n    showToast(\"Duplicated.\");\n  };\n\n  document.getElementById(\"deleteTaskAction\").onclick = ()=>{\n    tasks[currentDay].splice(activeIndex,1);\n    saveDay(currentDay);\n    taskOverlay.classList.remove(\"show\");\n    render();\n    showToast(\"Gone.\");\n  };\n\n  document.getElementById(\"editTaskAction\").onclick = ()=>{\n    const t = tasks[currentDay][activeIndex];\n    taskOverlay.classList.remove(\"show\");\n    document.getElementById(\"taskSheetTitle\").textContent = \"Edit: \" + t.name;\n    const newName = prompt(\"Task name:\", t.name);\n    if(newName && newName.trim()){\n      t.name = newName.trim();\n      saveDay(currentDay);\n      render();\n      showToast(\"Saved.\");\n    }\n  };\n\n  document.getElementById(\"moveTaskAction\").onclick = ()=>{\n    taskOverlay.classList.remove(\"show\");\n    showToast(\"Move-to-day picker goes here.\");\n  };\n\n  // See all\n  const allOverlay = document.getElementById(\"allTasksOverlay\");\n  function renderAll(){\n    const all = document.getElementById(\"allTasksList\");\n    all.innerHTML = \"\";\n    tasks[currentDay].forEach(t=>{\n      const row=document.createElement(\"button\");\n      row.className=\"action\";\n      row.textContent=`${t.done?\"✓\":\"○\"}  ${t.time} · ${t.name}`;\n      row.onclick=()=>showToast(t.name);\n      all.appendChild(row);\n    });\n  }\n  document.getElementById(\"seeAllTasks\").onclick=()=>{\n    renderAll();\n    allOverlay.classList.add(\"show\");\n  };\n  document.getElementById(\"closeAllTasks\").onclick=()=>allOverlay.classList.remove(\"show\");\n  document.getElementById(\"addFromAll\").onclick=()=>{\n    allOverlay.classList.remove(\"show\");\n    setTimeout(()=>addOverlay.classList.add(\"show\"),120);\n  };\n  allOverlay.onclick=e=>{if(e.target===allOverlay)allOverlay.classList.remove(\"show\")};\n\n  // Mood\n  const responses={\n    okay:\"Ay okay. May battery pa. 👀\",\n    meh:\"Sakto lang. Pili tayo ng battles.\",\n    konti:\"Gets. Essential tasks muna.\",\n    nope:\"Copy. Minimum viable human today.\"\n  };\n  document.querySelectorAll(\".mood\").forEach(btn=>{\n    btn.onclick=()=>{\n      document.querySelectorAll(\".mood\").forEach(b=>b.classList.remove(\"active\"));\n      btn.classList.add(\"active\");\n      document.getElementById(\"moodResponse\").textContent=responses[btn.dataset.mood];\n    };\n  });\n\n  // Reminders — real add/edit/delete, persisted in IndexedDB\n  const reminderOverlay=document.getElementById(\"reminderOverlay\");\n  const reminderFormOverlay=document.getElementById(\"reminderFormOverlay\");\n  let activeReminderKey=null;\n\n  const defaultReminders=[\n    {key:\"call-dentist\", name:\"Call dentist\", time:\"14:00\"},\n    {key:\"take-vitamins\", name:\"Take vitamins\", time:\"17:30\"}\n  ];\n\n  async function seedRemindersIfEmpty(){\n    const existing = await JDB.getAll(\"reminders\");\n    if(existing.length===0){\n      for(const r of defaultReminders){\n        await JDB.put(\"reminders\", r.key, {name:r.name, time:r.time});\n      }\n    }\n  }\n\n  function displayTime12(t){\n    if(!t) return \"—\";\n    let [h,m]=t.split(\":\").map(Number);\n    const suffix=h>=12?\"PM\":\"AM\";\n    h=h%12||12;\n    return `${h}:${String(m).padStart(2,\"0\")} ${suffix}`;\n  }\n\n  async function getReminders(){\n    const all = await JDB.getAll(\"reminders\");\n    return all.map(r=>({key:r.key, ...r.value})).sort((a,b)=>(a.time||\"\").localeCompare(b.time||\"\"));\n  }\n\n  async function renderReminders(){\n    const reminders = await getReminders();\n\n    const preview = document.getElementById(\"reminderPreview\");\n    preview.innerHTML = \"\";\n    if(reminders.length===0){\n      preview.innerHTML = `<div class=\"reminder\"><div class=\"reminder-name\">Wala pang reminder. Add one? 👀</div></div>`;\n    } else {\n      reminders.slice(0,2).forEach(r=>{\n        const row=document.createElement(\"div\");\n        row.className=\"reminder\";\n        row.innerHTML = `<div class=\"reminder-time\">${displayTime12(r.time)}</div><div class=\"reminder-name\">${r.name}</div>`;\n        preview.appendChild(row);\n      });\n    }\n\n    const full = document.getElementById(\"reminderFullList\");\n    full.innerHTML = \"\";\n    reminders.forEach(r=>{\n      const btn=document.createElement(\"button\");\n      btn.className=\"action\";\n      btn.textContent=`${displayTime12(r.time)} · ${r.name}`;\n      btn.onclick=()=>openReminderForm(r);\n      full.appendChild(btn);\n    });\n  }\n\n  function openReminderForm(reminder){\n    activeReminderKey = reminder ? reminder.key : null;\n    document.getElementById(\"reminderFormTitle\").textContent = reminder ? \"Edit reminder\" : \"Add reminder\";\n    document.getElementById(\"reminderNameInput\").value = reminder ? reminder.name : \"\";\n    document.getElementById(\"reminderTimeInput\").value = reminder ? reminder.time : \"\";\n    document.getElementById(\"deleteReminder\").style.display = reminder ? \"\" : \"none\";\n    reminderFormOverlay.classList.add(\"show\");\n  }\n\n  document.getElementById(\"openReminders\").onclick=async ()=>{ await renderReminders(); reminderOverlay.classList.add(\"show\"); };\n  document.getElementById(\"closeReminders\").onclick=()=>reminderOverlay.classList.remove(\"show\");\n  reminderOverlay.onclick=e=>{if(e.target===reminderOverlay)reminderOverlay.classList.remove(\"show\")};\n\n  document.getElementById(\"addReminder\").onclick=()=>{\n    reminderOverlay.classList.remove(\"show\");\n    setTimeout(()=>openReminderForm(null),150);\n  };\n  document.getElementById(\"cancelReminderForm\").onclick=()=>reminderFormOverlay.classList.remove(\"show\");\n  reminderFormOverlay.onclick=e=>{if(e.target===reminderFormOverlay)reminderFormOverlay.classList.remove(\"show\")};\n\n  document.getElementById(\"saveReminder\").onclick=async ()=>{\n    const name = document.getElementById(\"reminderNameInput\").value.trim();\n    const time = document.getElementById(\"reminderTimeInput\").value;\n    if(!name){ showToast(\"Pangalan muna ng reminder. 👀\"); return; }\n    const key = activeReminderKey || name.toLowerCase().replace(/[^a-z0-9]+/g,\"-\") + \"-\" + Date.now();\n    await JDB.put(\"reminders\", key, {name, time});\n    reminderFormOverlay.classList.remove(\"show\");\n    await renderReminders();\n    showToast(\"Saved.\");\n  };\n  document.getElementById(\"deleteReminder\").onclick=async ()=>{\n    if(!activeReminderKey) return;\n    await JDB.delete(\"reminders\", activeReminderKey);\n    reminderFormOverlay.classList.remove(\"show\");\n    await renderReminders();\n    showToast(\"Reminder removed.\");\n  };\n\n  // Coming up\n  document.querySelectorAll(\".date-card\").forEach(card=>{\n    card.onclick=()=>{\n      const key=card.dataset.openDay;\n      if(key===\"sat\"){\n        currentDay=\"sat\";\n        document.querySelectorAll(\".day\").forEach(b=>b.classList.toggle(\"active\",b.dataset.day===\"sat\"));\n        render();\n        showToast(\"Saturday opened.\");\n      }else{\n        showToast(\"That day opens in calendar.\");\n      }\n    };\n  });\n  document.getElementById(\"calendarBtn\").onclick=()=>showToast(\"Full calendar view next.\");\n\n  // Nav — real cross-file navigation\n  const NAV_TARGETS = {\n    Home: \"johanns_home_ux_first_v3.html\",\n    Health: \"johanns_fitness_editorial_concept_v4_buttons.html\",\n    Budget: \"johanns_budget_minimal_spacious_auto_v2.html\",\n    Journal: \"johanns_journal_v1.html\"\n  };\n  document.querySelectorAll(\".nav\").forEach(btn=>{\n    btn.onclick=()=>{\n      if(btn.dataset.nav===\"Tasks\") return;\n      if(NAV_TARGETS[btn.dataset.nav]) window.location.href = NAV_TARGETS[btn.dataset.nav];\n      else showToast(\"Profile — coming soon\");\n    };\n  });\n\n  // Shared profile avatar\n  const avatarEl = document.querySelector(\".avatar\");\n  if(avatarEl){\n    const savedAvatar = await JDB.get(\"profile\",\"avatar\");\n    if(savedAvatar){\n      avatarEl.style.backgroundImage = `url(${savedAvatar})`;\n      avatarEl.style.backgroundSize = \"cover\";\n      avatarEl.style.backgroundPosition = \"center\";\n      avatarEl.textContent = \"\";\n    }\n  }\n\n  await seedRemindersIfEmpty();\n  await renderReminders();\n  render();\n})();\n</script>\n<script src=\"./pwa-core.js\"></script></body>\n</html>\n", "health": "\n<!DOCTYPE html>\n<html lang=\"en\">\n<head><script>document.documentElement.classList.toggle(\"embedded\", window.self !== window.top);</script><base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0, viewport-fit=cover\">\n<title>Johann's Personal Space — Health</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F9F6F8;\n  --surface:#FFFFFF;\n  --surface-soft:#FCF9FB;\n  --border:#ECE3EA;\n  --pink:#E31C79;\n  --pink-deep:#B81463;\n  --pink-soft:#FCEAF3;\n  --plum:#3B2354;\n  --plum-dark:#2A1740;\n  --muted:#746D78;\n  --muted2:#A69EAA;\n  --green:#1F9E77;\n  --green-soft:#EEF8F4;\n  --font-display:'Baloo 2','Segoe UI Rounded',sans-serif;\n  --font-body:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  min-height:100vh;\n  display:flex;\n  justify-content:center;\n  align-items:flex-start;\n  padding:24px 14px;\n  color:#1E1B22;\n  font-family:var(--font-body);\n  background:\n    radial-gradient(circle at 17% 10%,rgba(227,28,121,.07),transparent 24%),\n    radial-gradient(circle at 80% 92%,rgba(59,35,84,.055),transparent 28%),\n    var(--bg);\n}\nbutton,input,select{font:inherit}\nbutton{cursor:pointer}\n.device{\n  width:390px;\n  max-width:100%;\n  padding:12px;\n  background:#0F0B12;\n  border-radius:48px;\n  box-shadow:0 38px 80px -30px rgba(30,10,40,.45);\n}\n.screen{\n  height:844px;\n  border-radius:36px;\n  overflow:hidden;\n  display:flex;\n  flex-direction:column;\n  position:relative;\n  background:\n    radial-gradient(circle at 95% 5%,rgba(227,28,121,.06),transparent 25%),\n    linear-gradient(180deg,#FCF9FB 0%,#F8F4F7 100%);\n}\n.statusbar{\n  height:34px;\n  flex:0 0 34px;\n  padding:0 26px 4px;\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-end;\n  font-size:13px;\n  font-weight:650;\n  position:relative;\n}\n.island{\n  position:absolute;\n  top:8px;left:50%;transform:translateX(-50%);\n  width:110px;height:24px;border-radius:16px;background:#0F0B12;\n}\n.main{\n  flex:1;\n  min-height:0;\n  padding:10px 18px 14px;\n  display:flex;\n  flex-direction:column;\n  overflow:hidden;\n}\n.header{\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-start;\n  margin-bottom:10px;\n}\n.brand{\n  margin:0;\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:17px;\n  font-weight:700;\n}\n.title{\n  margin:0;\n  color:var(--plum-dark);\n  font-family:var(--font-display);\n  font-size:27px;\n  line-height:1;\n  font-weight:800;\n}\n.avatar{\n  width:40px;height:40px;border-radius:50%;\n  display:grid;place-items:center;\n  background:var(--plum);color:#fff;\n  font-family:var(--font-display);font-weight:800;\n  border:2px solid #fff;\n}\n.tabs{\n  display:flex;\n  gap:18px;\n  align-items:flex-end;\n  border-bottom:1px solid var(--border);\n  margin-bottom:14px;\n}\n.tab{\n  position:relative;\n  border:none;\n  background:none;\n  color:var(--muted2);\n  padding:0 0 9px;\n  font-size:10.5px;\n  letter-spacing:.05em;\n  font-weight:800;\n}\n.tab.active{color:var(--plum)}\n.tab.active::after{\n  content:\"\";\n  position:absolute;\n  left:0;right:0;bottom:-1px;\n  height:2px;border-radius:999px;background:var(--pink);\n}\n.panel{display:none;flex:1;min-height:0;overflow:hidden}\n.panel.active{display:flex;flex-direction:column}\n\n/* editorial helpers */\n.kicker{\n  color:var(--muted2);\n  font-size:9.5px;\n  letter-spacing:.1em;\n  font-weight:850;\n}\n.soft-link{\n  border:none;background:none;color:var(--pink);\n  padding:0;font-size:9.8px;font-weight:800;\n}\n.rule{height:1px;background:var(--border)}\n.full-card{\n  background:var(--surface);\n  border:1px solid var(--border);\n  border-radius:24px;\n  box-shadow:0 14px 30px -26px rgba(59,35,84,.25);\n}\n\n/* TODAY */\n.today-panel{gap:13px}\n.cal-hero{\n  min-height:188px;\n  padding:16px 17px 15px;\n  position:relative;\n  overflow:hidden;\n  background:\n    radial-gradient(circle at 105% -10%,rgba(227,28,121,.11),transparent 36%),\n    linear-gradient(180deg,#fff 0%,#FFFBFD 100%);\n}\n.cal-hero::after{\n  content:\"\";\n  position:absolute;\n  width:120px;height:120px;\n  border-radius:50%;\n  right:-55px;bottom:-58px;\n  background:rgba(227,28,121,.055);\n}\n.cal-top{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:10px;\n}\n.goal-btn{\n  border:none;\n  background:#F8EEF4;\n  color:var(--pink-deep);\n  border-radius:999px;\n  padding:6px 9px;\n  font-size:9px;\n  font-weight:800;\n}\n.cal-main{\n  display:flex;\n  align-items:flex-end;\n  justify-content:space-between;\n  gap:14px;\n  margin-top:8px;\n}\n.cal-number{\n  font-family:var(--font-display);\n  color:var(--plum);\n  font-weight:800;\n  font-size:44px;\n  line-height:.92;\n}\n.cal-of{\n  margin-top:3px;color:var(--muted);font-size:10px;\n}\n.ring{\n  width:83px;height:83px;border-radius:50%;\n  position:relative;\n  display:grid;place-items:center;\n  background:conic-gradient(var(--pink) 0 56%, #F1E9EF 56% 100%);\n}\n.ring::before{\n  content:\"\";\n  position:absolute;\n  inset:9px;\n  border-radius:50%;\n  background:#fff;\n}\n.ring-inner{\n  position:relative;\n  z-index:1;\n  text-align:center;\n}\n.ring-inner b{\n  display:block;\n  font-family:var(--font-display);\n  font-size:17px;\n  color:var(--plum);\n}\n.ring-inner span{display:block;color:var(--muted);font-size:8px}\n.cal-note{\n  margin-top:10px;\n  color:var(--muted);\n  font-size:10.8px;\n}\n.cal-actions{\n  display:flex;\n  gap:8px;\n  margin-top:11px;\n}\n.primary-action{\n  border:none;\n  background:var(--pink);\n  color:#fff;\n  border-radius:12px;\n  padding:9px 11px;\n  font-size:10px;\n  font-weight:850;\n}\n.secondary-action{\n  border:none;\n  background:#F8EEF4;\n  color:var(--pink-deep);\n  border-radius:12px;\n  padding:9px 11px;\n  font-size:10px;\n  font-weight:850;\n}\n\n.body-line{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  padding:2px 2px 0;\n}\n.body-primary{\n  display:flex;\n  align-items:baseline;\n  gap:7px;\n}\n.body-primary strong{\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:23px;\n}\n.body-primary span{\n  color:var(--green);\n  font-size:9.5px;\n  font-weight:800;\n}\n.body-meta{\n  display:flex;\n  gap:8px;\n}\n.meta-pill{\n  background:#F6F1F5;\n  border-radius:999px;\n  padding:6px 8px;\n  font-size:8.8px;\n  color:var(--muted);\n}\n.meta-pill b{color:var(--plum)}\n\n.food-section{\n  padding:0 2px;\n}\n.food-head{\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  margin-bottom:8px;\n}\n.food-list{\n  background:var(--surface);\n  border:1px solid var(--border);\n  border-radius:20px;\n  overflow:hidden;\n}\n.food-row{\n  display:grid;\n  grid-template-columns:1fr auto;\n  gap:10px;\n  padding:10px 12px;\n  border-top:1px solid var(--border);\n}\n.food-row:first-child{border-top:none}\n.food-row b{\n  display:block;\n  color:var(--plum);\n  font-size:10.5px;\n}\n.food-row span{\n  color:var(--muted);\n  font-size:8.8px;\n}\n.food-kcal{\n  color:var(--muted);\n  font-size:9.5px;\n  align-self:center;\n}\n\n.workout-strip{\n  padding:13px 14px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:12px;\n  background:\n    linear-gradient(90deg,rgba(252,234,243,.72),rgba(255,255,255,.92) 62%),\n    #fff;\n}\n.workout-copy{min-width:0}\n.workout-copy strong{\n  display:block;\n  margin-top:2px;\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:16px;\n  line-height:1.1;\n}\n.workout-copy span{\n  display:block;\n  margin-top:3px;\n  color:var(--muted);\n  font-size:8.8px;\n}\n.start{\n  flex-shrink:0;\n  border:none;\n  background:var(--plum);\n  color:#fff;\n  border-radius:12px;\n  padding:9px 10px;\n  font-size:9.5px;\n  font-weight:850;\n}\n.daily-line{\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  padding:2px 2px 0;\n}\n.daily-item{\n  display:flex;\n  align-items:center;\n  gap:6px;\n  color:var(--muted);\n  font-size:9.4px;\n}\n.daily-item b{color:var(--plum);font-size:10.5px}\n\n/* FITNESS */\n.fitness-panel{gap:13px}\n.next-hero{\n  padding:16px 17px 15px;\n  background:\n    radial-gradient(circle at 100% 0%,rgba(227,28,121,.08),transparent 36%),\n    #fff;\n}\n.next-line{\n  display:flex;justify-content:space-between;align-items:flex-start;gap:12px;\n}\n.next-name{\n  margin-top:5px;\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:26px;\n  line-height:1;\n  font-weight:800;\n}\n.next-sub{margin-top:4px;color:var(--muted);font-size:9.5px}\n.streak-pill{\n  background:var(--pink-soft);\n  color:var(--pink-deep);\n  border-radius:999px;\n  padding:6px 8px;\n  font-size:8.5px;\n  font-weight:850;\n}\n.exercise-list{\n  margin-top:13px;\n  border-top:1px solid var(--border);\n}\n.exercise-line{\n  display:flex;\n  justify-content:space-between;\n  gap:10px;\n  padding:8px 0;\n  border-top:1px solid var(--border);\n}\n.exercise-line:first-child{border-top:none}\n.exercise-line b{\n  color:var(--text);\n  font-size:9.6px;\n}\n.exercise-line span{\n  color:var(--muted);\n  font-size:8.7px;\n}\n.hero-actions{\n  display:flex;\n  gap:8px;\n  margin-top:10px;\n}\n.flex1{flex:1}\n.rotation-line{\n  padding:0 2px;\n}\n.rotation-items{\n  display:flex;\n  gap:10px;\n  margin-top:8px;\n}\n.rotation-item{\n  flex:1;\n  min-width:0;\n}\n.rotation-item .letter{\n  color:var(--pink-deep);\n  font-size:9px;\n  font-weight:900;\n}\n.rotation-item strong{\n  display:block;\n  margin-top:2px;\n  color:var(--plum);\n  font-size:9.6px;\n  line-height:1.2;\n}\n.rotation-item span{\n  display:block;margin-top:2px;\n  color:var(--muted);\n  font-size:8.2px;\n}\n.week-strip{\n  padding:13px 14px;\n}\n.week-head{\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n}\n.week-days{\n  display:grid;\n  grid-template-columns:repeat(7,1fr);\n  gap:5px;\n  margin-top:10px;\n}\n.day{\n  text-align:center;\n}\n.day b{\n  display:block;\n  font-size:7.8px;\n  color:var(--muted2);\n  margin-bottom:4px;\n}\n.day span{\n  width:28px;height:28px;\n  margin:0 auto;\n  display:grid;place-items:center;\n  border-radius:9px;\n  font-size:8.7px;\n  color:var(--muted);\n  background:#F5F1F4;\n}\n.day.done span{\n  background:var(--pink);\n  color:#fff;\n  font-weight:900;\n}\n.day.next span{\n  background:#fff;\n  border:1.5px solid #F0B9D3;\n  color:var(--pink-deep);\n  font-weight:850;\n}\n.history-strip{\n  padding:0 2px;\n}\n.history-row{\n  display:flex;\n  justify-content:space-between;\n  gap:12px;\n  padding:8px 0;\n  border-top:1px solid var(--border);\n}\n.history-row:first-of-type{border-top:none}\n.history-row b{\n  display:block;\n  color:var(--plum);\n  font-size:9.8px;\n}\n.history-row span{\n  color:var(--muted);\n  font-size:8.5px;\n}\n\n/* PROGRESS */\n.progress-panel{gap:13px}\n.progress-hero{\n  padding:16px 17px 15px;\n}\n.progress-head{\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-end;\n}\n.progress-weight{\n  margin-top:4px;\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:40px;\n  line-height:1;\n  font-weight:800;\n}\n.progress-change{\n  text-align:right;\n  color:var(--green);\n  font-size:9.5px;\n  font-weight:800;\n}\n.chart-wrap{\n  margin-top:14px;\n  height:150px;\n  position:relative;\n}\n.chart-svg{width:100%;height:100%}\n.grid-line{stroke:#EEE7EC;stroke-width:1}\n.weight-line{\n  fill:none;\n  stroke:var(--pink);\n  stroke-width:3;\n  stroke-linecap:round;\n  stroke-linejoin:round;\n}\n.weight-dot{fill:#fff;stroke:var(--pink);stroke-width:2.5}\n.chart-text{\n  fill:var(--muted2);\n  font-family:var(--font-body);\n  font-size:8px;\n}\n.progress-summary{\n  display:flex;\n  justify-content:space-between;\n  gap:12px;\n  padding:0 2px;\n}\n.sum{\n  min-width:0;\n}\n.sum b{\n  display:block;\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:18px;\n}\n.sum span{\n  display:block;\n  color:var(--muted);\n  font-size:8.3px;\n}\n.bmi-strip{\n  padding:13px 14px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:12px;\n}\n.bmi-strip strong{\n  display:block;\n  color:var(--plum);\n  font-family:var(--font-display);\n  font-size:18px;\n}\n.bmi-strip span{\n  color:var(--muted);\n  font-size:8.8px;\n}\n.log-row{\n  display:flex;\n  gap:8px;\n}\n.log-row button{flex:1}\n\n/* bottom nav */\n.bottom-nav{\n  flex:0 0 62px;height:62px;\n  display:grid;\n  grid-template-columns:repeat(6,1fr);\n  padding:7px 4px 9px;\n  background:rgba(255,255,255,.95);\n  backdrop-filter:blur(8px);\n  border-top:1px solid var(--border);\n}\n.nav{\n  border:none;background:none;\n  display:flex;flex-direction:column;align-items:center;gap:3px;\n  color:var(--muted2);\n  font-size:8.7px;font-weight:700;\n}\n.nav-icon{\n  width:18px;height:18px;border-radius:6px;border:1.6px solid currentColor;\n}\n.nav.active{color:var(--pink)}\n.nav.active .nav-icon{background:var(--pink);border-color:var(--pink)}\n\n/* overlays */\n.overlay{\n  position:absolute;inset:0;\n  background:rgba(30,20,35,.42);\n  display:flex;align-items:flex-end;\n  opacity:0;pointer-events:none;\n  transition:.2s;\n  z-index:50;\n}\n.overlay.show{opacity:1;pointer-events:auto}\n.sheet{\n  width:100%;\n  max-height:76%;\n  overflow:auto;\n  background:#fff;\n  border-radius:24px 24px 0 0;\n  padding:12px 19px 24px;\n  transform:translateY(100%);\n  transition:.26s;\n}\n.overlay.show .sheet{transform:translateY(0)}\n.handle{\n  width:36px;height:4px;border-radius:999px;\n  background:var(--border);margin:0 auto 15px;\n}\n.sheet h3{\n  margin:0;color:var(--plum);\n  font-family:var(--font-display);\n  font-size:22px;\n}\n.sheet-sub{\n  margin:3px 0 13px;color:var(--muted);\n  font-size:11px;line-height:1.4;\n}\n.field{margin:10px 0}\n.field label{\n  display:block;\n  color:var(--muted);\n  font-size:9.5px;font-weight:850;\n  margin-bottom:5px;\n}\n.field input,.field select{\n  width:100%;\n  border:1.5px solid var(--border);\n  background:#FBF8FA;\n  border-radius:12px;\n  padding:10px 11px;\n  outline:none;\n}\n.field input:focus,.field select:focus{border-color:var(--pink)}\n.sheet-primary{\n  width:100%;border:none;\n  background:var(--pink);color:#fff;\n  border-radius:12px;\n  padding:11px;\n  font-size:10.5px;font-weight:850;\n  margin-top:7px;\n}\n.sheet-secondary{\n  width:100%;border:none;background:none;color:var(--muted);\n  padding:9px;font-size:10px;\n}\n.sheet-action{\n  width:100%;border:none;background:none;text-align:left;\n  border-top:1px solid var(--border);\n  padding:12px 1px;\n  font-size:11.5px;font-weight:700;color:var(--text);\n}\n.sheet-action:first-of-type{border-top:none}\n.edit-exercise{\n  display:grid;\n  grid-template-columns:1fr auto;\n  gap:10px;\n  padding:9px 0;\n  border-top:1px solid var(--border);\n}\n.edit-exercise:first-of-type{border-top:none}\n.edit-exercise b{display:block;font-size:10.5px;color:var(--plum)}\n.edit-exercise span{font-size:8.5px;color:var(--muted)}\n.edit-exercise button{\n  border:none;background:#F8EEF4;color:var(--pink-deep);\n  border-radius:999px;padding:5px 7px;font-size:8.5px;font-weight:800;\n}\n.toast{\n  position:absolute;\n  left:50%;bottom:72px;\n  transform:translate(-50%,10px);\n  background:var(--plum);color:#fff;\n  border-radius:999px;padding:8px 13px;\n  font-size:10px;font-weight:750;\n  opacity:0;pointer-events:none;\n  transition:.2s;z-index:60;white-space:nowrap;\n}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.placeholder{\n  flex:1;display:grid;place-items:center;text-align:center;padding:30px;color:var(--muted);\n}\n.placeholder h2{margin:0;color:var(--plum);font-family:var(--font-display)}\n@media(max-width:430px){\n  body{padding:0}\n  .device{width:100%;padding:0;border-radius:0}\n  .screen{height:100vh;border-radius:0}\n}\n</style>\n\n<style id=\"fitness-polish-v3\">\n  /* Keep typography consistent with Home / Budget */\n  body,\n  button,\n  input,\n  select{\n    font-family:var(--font-body);\n  }\n\n  .brand,\n  .title,\n  .cal-number,\n  .body-primary strong,\n  .workout-copy strong,\n  .next-name,\n  .progress-weight,\n  .weight-summary-line b,\n  .bmi-strip strong{\n    font-family:var(--font-display);\n  }\n\n  /* More breathing room without making the fixed screen feel empty */\n  .main{\n    padding:11px 18px 15px;\n  }\n\n  .header{\n    margin-bottom:12px;\n  }\n\n  .tabs{\n    gap:22px;\n    margin-bottom:16px;\n  }\n\n  .today-panel,\n  .fitness-panel,\n  .progress-panel{\n    gap:15px;\n  }\n\n  /* Softer corners: consistent, not pill-everything */\n  .full-card{\n    border-radius:21px;\n  }\n\n  .cal-hero,\n  .next-hero,\n  .progress-hero{\n    padding:18px;\n  }\n\n  .food-list{\n    border-radius:19px;\n  }\n\n  .workout-strip,\n  .week-strip,\n  .bmi-strip{\n    padding:15px 16px;\n  }\n\n  /* Make the Today hierarchy feel less crowded */\n  .cal-hero{\n    min-height:178px;\n  }\n\n  .cal-main{\n    margin-top:10px;\n  }\n\n  .cal-actions{\n    margin-top:13px;\n  }\n\n  .body-line{\n    padding:2px 4px;\n  }\n\n  .food-head{\n    margin-bottom:10px;\n  }\n\n  .food-row{\n    padding:11px 13px;\n  }\n\n  .daily-line{\n    padding:1px 4px 0;\n  }\n\n  /* Fitness spacing */\n  .exercise-list{\n    margin-top:14px;\n  }\n\n  .exercise-line{\n    padding:9px 0;\n  }\n\n  .rotation-items{\n    gap:14px;\n  }\n\n  .week-days{\n    margin-top:12px;\n  }\n\n  /* PROGRESS: no giant graph */\n  .progress-hero-calm{\n    min-height:auto;\n    background:\n      radial-gradient(circle at 102% -8%, rgba(227,28,121,.10), transparent 36%),\n      linear-gradient(180deg,#FFFFFF 0%,#FFFBFD 100%);\n  }\n\n  .weight-focus-row{\n    display:flex;\n    align-items:flex-end;\n    justify-content:space-between;\n    gap:14px;\n    margin-top:7px;\n  }\n\n  .progress-weight{\n    font-size:38px;\n    line-height:.95;\n  }\n\n  .progress-subcopy{\n    margin-top:5px;\n    color:var(--muted);\n    font-size:9px;\n  }\n\n  .weight-summary-line{\n    margin-top:18px;\n    padding-top:15px;\n    border-top:1px solid var(--border);\n    display:grid;\n    grid-template-columns:1fr auto 1fr;\n    align-items:center;\n    gap:12px;\n  }\n\n  .weight-summary-line div:not(.journey-arrow):last-child{\n    text-align:right;\n  }\n\n  .weight-summary-line span{\n    display:block;\n    color:var(--muted2);\n    font-size:8.7px;\n    margin-bottom:3px;\n  }\n\n  .weight-summary-line b{\n    color:var(--plum);\n    font-size:17px;\n  }\n\n  .journey-arrow{\n    color:var(--pink);\n    font-size:17px;\n  }\n\n  .progress-history-block{\n    padding:0 3px;\n  }\n\n  .progress-section-copy{\n    margin-top:4px;\n    max-width:230px;\n    color:var(--muted);\n    font-size:9px;\n    line-height:1.35;\n  }\n\n  .weight-list{\n    background:#FFFFFF;\n    border:1px solid var(--border);\n    border-radius:19px;\n    overflow:hidden;\n  }\n\n  .weight-row{\n    display:flex;\n    justify-content:space-between;\n    align-items:center;\n    gap:12px;\n    padding:12px 13px;\n    border-top:1px solid var(--border);\n  }\n\n  .weight-row:first-child{\n    border-top:none;\n  }\n\n  .weight-row b{\n    display:block;\n    color:var(--plum);\n    font-size:10.5px;\n  }\n\n  .weight-row span{\n    display:block;\n    margin-top:2px;\n    color:var(--muted);\n    font-size:8.5px;\n  }\n\n  .weight-row strong{\n    color:var(--plum);\n    font-family:var(--font-display);\n    font-size:14px;\n  }\n\n  .bmi-strip-roomy{\n    align-items:flex-start;\n  }\n\n  .bmi-note{\n    max-width:175px;\n    text-align:right;\n  }\n\n  .bmi-note small{\n    display:block;\n    margin-top:3px;\n    color:var(--muted2);\n    font-size:8px;\n    line-height:1.35;\n  }\n\n  .log-row{\n    margin-top:auto;\n  }\n\n  .log-row .primary-action,\n  .log-row .secondary-action{\n    padding:11px 12px;\n  }\n</style>\n\n\n<style id=\"fitness-button-system-v4\">\n  /* ----------------------------------------------------\n     BUTTON / TAP TARGET SYSTEM\n     Keep the visual style light, but make every action\n     feel intentional and easy to tap.\n  ---------------------------------------------------- */\n\n  button{\n    -webkit-tap-highlight-color:transparent;\n    transition:\n      transform .14s ease,\n      background .14s ease,\n      border-color .14s ease,\n      box-shadow .14s ease,\n      color .14s ease,\n      opacity .14s ease;\n  }\n\n  button:active{\n    transform:scale(.97);\n  }\n\n  button:focus-visible{\n    outline:2px solid rgba(227,28,121,.28);\n    outline-offset:2px;\n  }\n\n  /* Top sub-navigation:\n     generous tap target without making it look like pills. */\n  .tab{\n    min-height:38px;\n    display:flex;\n    align-items:center;\n    justify-content:center;\n    padding:2px 3px 10px;\n    font-size:10px;\n  }\n\n  /* Small text actions should still be tappable. */\n  .soft-link{\n    min-height:30px;\n    display:inline-flex;\n    align-items:center;\n    justify-content:center;\n    padding:5px 2px;\n    border-radius:8px;\n  }\n\n  .soft-link:hover{\n    color:var(--pink-deep);\n    background:rgba(252,234,243,.52);\n  }\n\n  /* Goal is an action, not a status pill. */\n  .goal-btn{\n    min-height:32px;\n    border:1px solid #F1D9E5;\n    border-radius:10px;\n    padding:7px 10px;\n    background:#FFF9FC;\n    box-shadow:0 5px 14px -13px rgba(227,28,121,.34);\n  }\n\n  /* Main CTAs — shared shape + height */\n  .primary-action,\n  .secondary-action,\n  .start{\n    min-height:40px;\n    border-radius:13px;\n    padding:10px 13px;\n    display:inline-flex;\n    align-items:center;\n    justify-content:center;\n    line-height:1;\n  }\n\n  .primary-action{\n    box-shadow:0 8px 18px -13px rgba(227,28,121,.46);\n  }\n\n  .primary-action:hover{\n    background:#CF176D;\n  }\n\n  .secondary-action{\n    border:1px solid #F0DFE8;\n    background:#FFF9FC;\n  }\n\n  .secondary-action:hover{\n    background:#FBEAF3;\n  }\n\n  /* Today's workout button was visually too small before. */\n  .start{\n    min-width:72px;\n    background:var(--plum);\n    box-shadow:0 8px 18px -13px rgba(59,35,84,.45);\n  }\n\n  .start:hover{\n    background:var(--plum-dark);\n  }\n\n  /* Calorie hero actions should feel balanced. */\n  .cal-actions{\n    display:grid;\n    grid-template-columns:1fr 1fr;\n    gap:9px;\n  }\n\n  .cal-actions .primary-action,\n  .cal-actions .secondary-action{\n    width:100%;\n  }\n\n  /* Fitness hero: primary gets more space, edit stays secondary. */\n  .hero-actions{\n    grid-template-columns:minmax(0,1.5fr) minmax(105px,.8fr);\n    display:grid;\n    gap:9px;\n  }\n\n  .hero-actions .primary-action,\n  .hero-actions .secondary-action{\n    width:100%;\n  }\n\n  /* Bottom Progress actions */\n  .log-row{\n    grid-template-columns:1.2fr 1fr;\n    display:grid;\n    gap:9px;\n  }\n\n  .log-row button{\n    width:100%;\n    min-height:42px;\n  }\n\n  /* Sheets: full-width actions should look like real controls */\n  .sheet-primary{\n    min-height:42px;\n    border-radius:13px;\n    box-shadow:0 8px 18px -13px rgba(227,28,121,.44);\n  }\n\n  .sheet-secondary{\n    min-height:38px;\n    margin-top:3px;\n    border-radius:10px;\n  }\n\n  .sheet-secondary:hover{\n    background:#F8F4F7;\n  }\n\n  .sheet-action{\n    min-height:43px;\n    display:block;\n    padding:12px 3px;\n  }\n\n  .sheet-action:hover{\n    background:#FCF9FB;\n  }\n\n  /* Routine delete/remove action: don't make destructive actions\n     look like a cheerful pink chip. */\n  .edit-exercise button{\n    min-height:30px;\n    padding:6px 8px;\n    border-radius:9px;\n    background:#FFF7F7;\n    border:1px solid #F4DEDE;\n    color:#C94A48;\n  }\n\n  /* Water add is small in appearance but still a real tap target. */\n  #waterPlus{\n    min-height:32px;\n    padding:5px 8px;\n    border:1px solid #F1DDE7;\n    background:#FFF9FC;\n  }\n\n  /* Bottom navigation: entire area is tappable, not only icon/text. */\n  .nav{\n    min-height:46px;\n    border-radius:12px;\n    padding:3px 0;\n  }\n\n  .nav:hover{\n    background:#FCF8FA;\n  }\n\n  .nav.active{\n    background:rgba(252,234,243,.52);\n  }\n\n  /* Keep status-like elements as pills. These are not buttons. */\n  .streak-pill,\n  .meta-pill{\n    border-radius:999px;\n  }\n\n  /* Tiny spacing corrections around action rows */\n  .workout-strip{\n    gap:14px;\n  }\n\n  .food-head{\n    min-height:30px;\n    align-items:center;\n  }\n\n  .week-head{\n    min-height:32px;\n  }\n\n  /* Slightly more room between content and bottom action area */\n  .progress-panel .log-row{\n    margin-top:auto;\n    padding-top:2px;\n  }\n</style>\n\n<style id=\"app-shell-embedded-overrides\">\nhtml.embedded, html.embedded body{ height:100%; padding:0 !important; margin:0 !important; align-items:stretch !important; justify-content:stretch !important; }\nhtml.embedded .device{ width:100% !important; max-width:100% !important; height:100dvh !important; background:transparent !important; padding:0 !important; border-radius:0 !important; box-shadow:none !important; }\nhtml.embedded .screen{ height:100dvh !important; border-radius:0 !important; padding-top:max(14px, env(safe-area-inset-top)) !important; }\nhtml.embedded .statusbar, html.embedded .status, html.embedded .dynamic-island, html.embedded .island{ display:none !important; }\nhtml.embedded .bottom-nav, html.embedded .bottom{ padding-bottom:max(9px, env(safe-area-inset-bottom)) !important; }\n</style></head>\n<body>\n<div class=\"device\">\n  <div class=\"screen\">\n    <div class=\"statusbar\">\n      <div class=\"island\"></div>\n      <span>9:41</span>\n      <span>● ● ▰</span>\n    </div>\n\n    <main class=\"main\" id=\"fitnessPage\">\n      <div class=\"header\">\n        <div>\n          <p class=\"brand\">Johann's Personal Space</p>\n          <h1 class=\"title\">Fitness</h1>\n        </div>\n        <div class=\"avatar\">J</div>\n      </div>\n\n      <div class=\"tabs\">\n        <button class=\"tab active\" data-panel=\"today\">TODAY</button>\n        <button class=\"tab\" data-panel=\"fitness\">FITNESS</button>\n        <button class=\"tab\" data-panel=\"progress\">PROGRESS</button>\n      </div>\n\n      <!-- TODAY -->\n      <section class=\"panel active today-panel\" id=\"panel-today\">\n        <article class=\"full-card cal-hero\">\n          <div class=\"cal-top\">\n            <div class=\"kicker\">CALORIES TODAY</div>\n            <button class=\"goal-btn\" id=\"goalBtn\">Goal 1,450</button>\n          </div>\n\n          <div class=\"cal-main\">\n            <div>\n              <div class=\"cal-number\" id=\"calConsumed\">820</div>\n              <div class=\"cal-of\">of <span id=\"calGoal\">1,450</span> kcal</div>\n            </div>\n            <div class=\"ring\" id=\"calRing\">\n              <div class=\"ring-inner\">\n                <b id=\"calLeft\">630</b>\n                <span>left</span>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"cal-note\" id=\"calNote\">Okayyy. May room pa. 👀</div>\n\n          <div class=\"cal-actions\">\n            <button class=\"primary-action\" id=\"addFoodBtn\">+ Add food</button>\n            <button class=\"secondary-action\" id=\"foodLogBtn\">Food log</button>\n          </div>\n        </article>\n\n        <div class=\"body-line\">\n          <div class=\"body-primary\">\n            <strong id=\"todayWeight\">70.4 kg</strong>\n            <span id=\"todayDelta\">↓ 1.7 kg</span>\n          </div>\n          <div class=\"body-meta\">\n            <div class=\"meta-pill\">BMI <b id=\"todayBMI\">24.6</b></div>\n            <div class=\"meta-pill\">169 cm</div>\n          </div>\n        </div>\n\n        <section class=\"food-section\">\n          <div class=\"food-head\">\n            <div class=\"kicker\">WHAT I ATE TODAY</div>\n            <button class=\"soft-link\" id=\"foodLogLink\">View all →</button>\n          </div>\n          <div class=\"food-list\">\n            <div class=\"food-row\"><div><b>Breakfast</b><span>2 Eggs + Toast</span></div><div class=\"food-kcal\">310 kcal</div></div>\n            <div class=\"food-row\"><div><b>Lunch</b><span>Chicken rice bowl</span></div><div class=\"food-kcal\">420 kcal</div></div>\n            <div class=\"food-row\"><div><b>Snack</b><span>Banana</span></div><div class=\"food-kcal\">90 kcal</div></div>\n            <div class=\"food-row\"><div><b>Dinner</b><span>Nothing logged yet</span></div><div class=\"food-kcal\">—</div></div>\n          </div>\n        </section>\n\n        <article class=\"full-card workout-strip\">\n          <div class=\"workout-copy\">\n            <div class=\"kicker\">TODAY'S WORKOUT</div>\n            <strong>Workout A · Glutes + Hamstrings</strong>\n            <span>5 exercises · ~40 min · strength only</span>\n          </div>\n          <button class=\"start\" id=\"todayStart\">Start →</button>\n        </article>\n\n        <div class=\"daily-line\">\n          <div class=\"daily-item\">👟 <b>5,420</b> steps</div>\n          <div class=\"daily-item\">💧 <b id=\"waterCount\">4 / 8</b> water</div>\n          <button class=\"soft-link\" id=\"waterPlus\">+ glass</button>\n        </div>\n      </section>\n\n      <!-- FITNESS -->\n      <section class=\"panel fitness-panel\" id=\"panel-fitness\">\n        <article class=\"full-card next-hero\">\n          <div class=\"next-line\">\n            <div>\n              <div class=\"kicker\">UP NEXT</div>\n              <div class=\"next-name\">Workout A</div>\n              <div class=\"next-sub\">Glutes + Hamstrings · every other day</div>\n            </div>\n            <div class=\"streak-pill\">🔥 3 streak</div>\n          </div>\n\n          <div class=\"exercise-list\">\n            <div class=\"exercise-line\"><b>Romanian Deadlift</b><span>3 × 8–12</span></div>\n            <div class=\"exercise-line\"><b>Weighted Glute Bridge</b><span>4 × 10–15</span></div>\n            <div class=\"exercise-line\"><b>Goblet Squat</b><span>3 × 8–12</span></div>\n            <div class=\"exercise-line\"><b>Sumo Squat</b><span>3 × 10–12</span></div>\n            <div class=\"exercise-line\"><b>Frog Pumps</b><span>2 × 15–25</span></div>\n          </div>\n\n          <div class=\"hero-actions\">\n            <button class=\"primary-action flex1\" id=\"startWorkoutBtn\">Start workout</button>\n            <button class=\"secondary-action\" id=\"editRoutineBtn\">Edit routine</button>\n          </div>\n        </article>\n\n        <section class=\"rotation-line\">\n          <div class=\"food-head\">\n            <div class=\"kicker\">YOUR ROTATION</div>\n            <button class=\"soft-link\" id=\"manageBtn\">Manage →</button>\n          </div>\n          <div class=\"rotation-items\">\n            <div class=\"rotation-item\"><div class=\"letter\">A · NEXT</div><strong>Glutes + Hamstrings</strong><span>5 exercises</span></div>\n            <div class=\"rotation-item\"><div class=\"letter\">B</div><strong>Upper + Core</strong><span>7 exercises</span></div>\n            <div class=\"rotation-item\"><div class=\"letter\">C</div><strong>Glutes + Legs</strong><span>5 exercises</span></div>\n          </div>\n        </section>\n\n        <article class=\"full-card week-strip\">\n          <div class=\"week-head\">\n            <div>\n              <div class=\"kicker\">THIS WEEK</div>\n              <div style=\"font-family:var(--font-display);font-size:15px;color:var(--plum);font-weight:800;margin-top:2px\">Workout tracker</div>\n            </div>\n            <button class=\"soft-link\" id=\"calendarBtn\">Calendar →</button>\n          </div>\n\n          <div class=\"week-days\">\n            <div class=\"day done\"><b>MON</b><span>1</span></div>\n            <div class=\"day\"><b>TUE</b><span>2</span></div>\n            <div class=\"day done\"><b>WED</b><span>3</span></div>\n            <div class=\"day\"><b>THU</b><span>4</span></div>\n            <div class=\"day done\"><b>FRI</b><span>5</span></div>\n            <div class=\"day\"><b>SAT</b><span>6</span></div>\n            <div class=\"day next\"><b>SUN</b><span>7</span></div>\n          </div>\n        </article>\n\n        <section class=\"history-strip\">\n          <div class=\"food-head\">\n            <div class=\"kicker\">RECENT WORKOUTS</div>\n            <button class=\"soft-link\" id=\"historyBtn\">History →</button>\n          </div>\n          <div class=\"history-row\"><div><b>Sep 5 · Workout C</b><span>Glutes + Legs</span></div><span>46 min 🔥</span></div>\n          <div class=\"history-row\"><div><b>Sep 3 · Workout B</b><span>Upper + Core</span></div><span>39 min 🔥</span></div>\n        </section>\n      </section>\n\n\n<!-- PROGRESS -->\n<section class=\"panel progress-panel\" id=\"panel-progress\">\n  <article class=\"full-card progress-hero progress-hero-calm\">\n    <div class=\"kicker\">YOUR WEIGHT JOURNEY</div>\n\n    <div class=\"weight-focus-row\">\n      <div>\n        <div class=\"progress-weight\" id=\"progressWeight\">70.4 kg</div>\n        <div class=\"progress-subcopy\">Current weight</div>\n      </div>\n      <div class=\"progress-change\" id=\"progressChange\">↓ 1.7 kg<br>since Aug 1</div>\n    </div>\n\n    <div class=\"weight-summary-line\">\n      <div>\n        <span>Started</span>\n        <b id=\"startWeight\">72.1 kg</b>\n      </div>\n      <div class=\"journey-arrow\">→</div>\n      <div>\n        <span>Now</span>\n        <b id=\"currentWeight\">70.4 kg</b>\n      </div>\n    </div>\n  </article>\n\n  <section class=\"progress-history-block\">\n    <div class=\"food-head\">\n      <div>\n        <div class=\"kicker\">RECENT WEIGH-INS</div>\n        <div class=\"progress-section-copy\">A few checkpoints. Hindi kailangan bantayan every hour. 😌</div>\n      </div>\n      <button class=\"soft-link\" id=\"weightHistoryBtn\">History →</button>\n    </div>\n\n    <div class=\"weight-list\">\n      <div class=\"weight-row\">\n        <div><b>Sep 4</b><span>Latest</span></div>\n        <strong>70.4 kg</strong>\n      </div>\n      <div class=\"weight-row\">\n        <div><b>Sep 1</b><span>3 days earlier</span></div>\n        <strong>70.7 kg</strong>\n      </div>\n      <div class=\"weight-row\">\n        <div><b>Aug 24</b><span>Previous check-in</span></div>\n        <strong>71.0 kg</strong>\n      </div>\n    </div>\n  </section>\n\n  <article class=\"full-card bmi-strip bmi-strip-roomy\">\n    <div>\n      <span>Current BMI</span>\n      <strong id=\"progressBMI\">24.6</strong>\n    </div>\n    <div class=\"bmi-note\">\n      <span>Reference only</span>\n      <small>Updates automatically from height + latest weight.</small>\n    </div>\n  </article>\n\n  <div class=\"log-row\">\n    <button class=\"primary-action\" id=\"logWeightBtn\">+ Log weight</button>\n    <button class=\"secondary-action\" id=\"weightHistoryBtnBottom\">Weight history</button>\n  </div>\n</section>\n    </main>\n\n    <main class=\"placeholder\" id=\"placeholder\" style=\"display:none\">\n      <div><h2 id=\"placeholderTitle\">Home</h2><p>Placeholder — Fitness is the active prototype.</p></div>\n    </main>\n\n    <nav class=\"bottom-nav\">\n      <button class=\"nav\" data-nav=\"Home\"><span class=\"nav-icon\"></span>Home</button>\n      <button class=\"nav\" data-nav=\"Tasks\"><span class=\"nav-icon\"></span>Tasks</button>\n      <button class=\"nav active\" data-nav=\"Fitness\"><span class=\"nav-icon\"></span>Fitness</button>\n      <button class=\"nav\" data-nav=\"Budget\"><span class=\"nav-icon\"></span>Budget</button>\n      <button class=\"nav\" data-nav=\"Journal\"><span class=\"nav-icon\"></span>Journal</button>\n      <button class=\"nav\" data-nav=\"Profile\"><span class=\"nav-icon\"></span>Profile</button>\n    </nav>\n\n    <!-- Add food -->\n    <div class=\"overlay\" id=\"foodOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Add food</h3>\n        <div class=\"sheet-sub\">Quick calories only. Keep it easy.</div>\n        <div class=\"field\"><label>FOOD</label><input id=\"foodName\" placeholder=\"Chicken rice bowl\"></div>\n        <div class=\"field\"><label>CALORIES</label><input id=\"foodCalories\" type=\"number\" placeholder=\"520\"></div>\n        <div class=\"field\"><label>MEAL</label>\n          <select id=\"foodMeal\">\n            <option>Breakfast</option><option selected>Lunch</option><option>Dinner</option><option>Snack</option>\n          </select>\n        </div>\n        <button class=\"sheet-primary\" id=\"saveFood\">Add food</button>\n        <button class=\"sheet-secondary close-sheet\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Food log -->\n    <div class=\"overlay\" id=\"foodLogOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Food log</h3>\n        <div class=\"sheet-sub\" id=\"foodLogSummary\">820 / 1,450 kcal</div>\n        <div id=\"foodLogList\"></div>\n        <button class=\"sheet-primary\" id=\"addFoodFromLog\">+ Add food</button>\n        <button class=\"sheet-secondary close-sheet\">Close</button>\n      </div>\n    </div>\n\n    <!-- Goal -->\n    <div class=\"overlay\" id=\"goalOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Calorie goal</h3>\n        <div class=\"sheet-sub\">Editable whenever you want.</div>\n        <div class=\"field\"><label>DAILY GOAL</label><input id=\"goalInput\" type=\"number\" value=\"1450\"></div>\n        <button class=\"sheet-primary\" id=\"saveGoal\">Save goal</button>\n        <button class=\"sheet-secondary close-sheet\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Routine -->\n    <div class=\"overlay\" id=\"routineOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Edit Workout A</h3>\n        <div class=\"sheet-sub\">Rename, delete, or add exercises.</div>\n        <div class=\"field\"><label>WORKOUT NAME</label><input value=\"Glutes + Hamstrings\"></div>\n        <div id=\"routineList\"></div>\n        <button class=\"sheet-primary\" id=\"addExerciseBtn\">+ Add exercise</button>\n        <button class=\"sheet-secondary close-sheet\">Done</button>\n      </div>\n    </div>\n\n    <!-- Add exercise -->\n    <div class=\"overlay\" id=\"exerciseOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Add exercise</h3>\n        <div class=\"field\"><label>EXERCISE</label><input id=\"exerciseName\" placeholder=\"Donkey Kick\"></div>\n        <div class=\"field\"><label>SETS</label><input id=\"exerciseSets\" type=\"number\" value=\"3\"></div>\n        <div class=\"field\"><label>REPS</label><input id=\"exerciseReps\" value=\"10–15\"></div>\n        <button class=\"sheet-primary\" id=\"saveExercise\">Add exercise</button>\n        <button class=\"sheet-secondary close-sheet\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Workout mode -->\n    <div class=\"overlay\" id=\"workoutOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Workout A</h3>\n        <div class=\"sheet-sub\">Glutes + Hamstrings · no jumping</div>\n        <div id=\"workoutList\"></div>\n        <button class=\"sheet-primary\" id=\"finishWorkout\">Finish workout 🔥</button>\n        <button class=\"sheet-secondary close-sheet\">Exit for now</button>\n      </div>\n    </div>\n\n    <!-- Calendar -->\n    <div class=\"overlay\" id=\"calendarOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>September tracker</h3>\n        <div class=\"sheet-sub\">Rest days do not break your streak.</div>\n        <button class=\"sheet-action\">🔥 Sep 1 · Workout A</button>\n        <button class=\"sheet-action\">🔥 Sep 3 · Workout B</button>\n        <button class=\"sheet-action\">🔥 Sep 5 · Workout C</button>\n        <button class=\"sheet-action\">○ Sep 7 · Workout A · scheduled</button>\n        <button class=\"sheet-secondary close-sheet\">Close</button>\n      </div>\n    </div>\n\n    <!-- Weight -->\n    <div class=\"overlay\" id=\"weightOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Log weight</h3>\n        <div class=\"field\"><label>WEIGHT · KG</label><input id=\"weightInput\" type=\"number\" step=\"0.1\" value=\"70.4\"></div>\n        <div class=\"field\"><label>DATE</label><input id=\"weightDate\" type=\"date\" value=\"2026-09-04\"></div>\n        <button class=\"sheet-primary\" id=\"saveWeight\">Save weight</button>\n        <button class=\"sheet-secondary close-sheet\">Cancel</button>\n      </div>\n    </div>\n\n    <div class=\"overlay\" id=\"weightHistoryOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Weight history</h3>\n        <div class=\"sheet-sub\">Recent weigh-ins.</div>\n        <div id=\"weightHistoryList\"></div>\n        <button class=\"sheet-secondary close-sheet\">Close</button>\n      </div>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n  </div>\n</div>\n\n<script src=\"./johanns-db.js\"></script>\n<script>\n(async () => {\n  await JDB.ready;\n\n  const heightCm = 169;\n\n  const defaultState = {\n    calorieGoal: 1450,\n    water: 4,\n    foods: [\n      {id:1,name:\"2 Eggs + Toast\",calories:310,meal:\"Breakfast\"},\n      {id:2,name:\"Chicken rice bowl\",calories:420,meal:\"Lunch\"},\n      {id:3,name:\"Banana\",calories:90,meal:\"Snack\"}\n    ],\n    weights: [\n      {date:\"2026-08-01\",weight:72.1},\n      {date:\"2026-08-08\",weight:71.8},\n      {date:\"2026-08-16\",weight:71.5},\n      {date:\"2026-08-24\",weight:71.0},\n      {date:\"2026-09-01\",weight:70.7},\n      {date:\"2026-09-04\",weight:70.4}\n    ],\n    routineA: [\n      {name:\"Romanian Deadlift\",sets:3,reps:\"8–12\"},\n      {name:\"Weighted Glute Bridge\",sets:4,reps:\"10–15\"},\n      {name:\"Goblet Squat\",sets:3,reps:\"8–12\"},\n      {name:\"Sumo Squat\",sets:3,reps:\"10–12\"},\n      {name:\"Frog Pumps\",sets:2,reps:\"15–25\"}\n    ]\n  };\n  const saved = await JDB.get(\"health\", \"state\").catch(()=>null);\n  const state = saved || defaultState;\n\n  let calorieGoal = state.calorieGoal;\n  let water = state.water;\n  let foods = state.foods;\n  let weights = state.weights;\n  let routineA = state.routineA;\n\n  const saveState = JDB.debounce(()=> JDB.put(\"health\", \"state\", {\n    calorieGoal, water, foods, weights, routineA\n  }), 300);\n\n  const overlays=[...document.querySelectorAll(\".overlay\")];\n  const toast=document.getElementById(\"toast\");\n  const open=id=>document.getElementById(id).classList.add(\"show\");\n  const closeAll=()=>overlays.forEach(o=>o.classList.remove(\"show\"));\n  const fmt=n=>Number(n).toLocaleString(\"en-US\");\n\n  overlays.forEach(o=>o.onclick=e=>{if(e.target===o)o.classList.remove(\"show\")});\n  document.querySelectorAll(\".close-sheet\").forEach(b=>b.onclick=closeAll);\n\n  function showToast(msg){\n    toast.textContent=msg;\n    toast.classList.add(\"show\");\n    clearTimeout(window.__toast);\n    window.__toast=setTimeout(()=>toast.classList.remove(\"show\"),1700);\n  }\n\n  document.querySelectorAll(\".tab\").forEach(btn=>{\n    btn.onclick=()=>{\n      document.querySelectorAll(\".tab\").forEach(b=>b.classList.remove(\"active\"));\n      document.querySelectorAll(\".panel\").forEach(p=>p.classList.remove(\"active\"));\n      btn.classList.add(\"active\");\n      document.getElementById(\"panel-\"+btn.dataset.panel).classList.add(\"active\");\n    };\n  });\n\n  const currentWeight=()=>weights[weights.length-1].weight;\n  const bmi=()=>currentWeight()/Math.pow(heightCm/100,2);\n  const calories=()=>foods.reduce((s,f)=>s+f.calories,0);\n\n  function renderToday(){\n    const c=calories();\n    const left=calorieGoal-c;\n    const pct=Math.max(0,Math.min(100,c/calorieGoal*100));\n    document.getElementById(\"calConsumed\").textContent=fmt(c);\n    document.getElementById(\"calGoal\").textContent=fmt(calorieGoal);\n    document.getElementById(\"goalBtn\").textContent=\"Goal \"+fmt(calorieGoal);\n    document.getElementById(\"calLeft\").textContent=fmt(Math.abs(left));\n    document.getElementById(\"calNote\").textContent=\n      left>400?\"Okayyy. May room pa. 👀\":\n      left>=0?\"Medyo close tayo, boss.\":\"Over today. No drama — just logged.\";\n    document.getElementById(\"calRing\").style.background=\n      `conic-gradient(var(--pink) 0 ${pct}%, #F1E9EF ${pct}% 100%)`;\n\n    const cw=currentWeight();\n    const delta=cw-weights[0].weight;\n    document.getElementById(\"todayWeight\").textContent=cw.toFixed(1)+\" kg\";\n    document.getElementById(\"todayDelta\").textContent=(delta<=0?\"↓ \":\"↑ \")+Math.abs(delta).toFixed(1)+\" kg\";\n    document.getElementById(\"todayBMI\").textContent=bmi().toFixed(1);\n    document.getElementById(\"waterCount\").textContent=water+\" / 8\";\n  }\n\n  function renderFoodLog(){\n    const box=document.getElementById(\"foodLogList\");\n    box.innerHTML=\"\";\n    foods.forEach(f=>{\n      const b=document.createElement(\"button\");\n      b.className=\"sheet-action\";\n      b.innerHTML=`${f.name} <span style=\"float:right;color:var(--muted)\">${f.calories} kcal</span><br><span style=\"font-size:8.7px;color:var(--muted2)\">${f.meal}</span>`;\n      b.onclick=()=>{\n        foods=foods.filter(x=>x.id!==f.id);\n        saveState();\n        renderToday();renderFoodLog();\n        showToast(\"Removed from today's log.\");\n      };\n      box.appendChild(b);\n    });\n    document.getElementById(\"foodLogSummary\").textContent=`${fmt(calories())} / ${fmt(calorieGoal)} kcal`;\n  }\n\n  document.getElementById(\"addFoodBtn\").onclick=()=>open(\"foodOverlay\");\n  document.getElementById(\"foodLogBtn\").onclick=()=>{renderFoodLog();open(\"foodLogOverlay\")};\n  document.getElementById(\"foodLogLink\").onclick=()=>{renderFoodLog();open(\"foodLogOverlay\")};\n  document.getElementById(\"addFoodFromLog\").onclick=()=>{closeAll();setTimeout(()=>open(\"foodOverlay\"),100)};\n  document.getElementById(\"saveFood\").onclick=()=>{\n    const name=document.getElementById(\"foodName\").value.trim();\n    const cal=Number(document.getElementById(\"foodCalories\").value);\n    const meal=document.getElementById(\"foodMeal\").value;\n    if(!name||!cal){showToast(\"Food + calories muna. 👀\");return;}\n    foods.push({id:Date.now(),name,calories:cal,meal});\n    saveState();\n    renderToday();closeAll();showToast(\"Logged. 🫡\");\n  };\n\n  document.getElementById(\"goalBtn\").onclick=()=>{\n    document.getElementById(\"goalInput\").value=calorieGoal;\n    open(\"goalOverlay\");\n  };\n  document.getElementById(\"saveGoal\").onclick=()=>{\n    const n=Number(document.getElementById(\"goalInput\").value);\n    if(!n)return;\n    calorieGoal=n;saveState();renderToday();closeAll();showToast(\"Goal updated.\");\n  };\n\n  document.getElementById(\"waterPlus\").onclick=()=>{\n    water=Math.min(20,water+1);\n    saveState();\n    renderToday();\n  };\n\n  function renderRoutine(){\n    const box=document.getElementById(\"routineList\");\n    box.innerHTML=\"\";\n    routineA.forEach((ex,i)=>{\n      const row=document.createElement(\"div\");\n      row.className=\"edit-exercise\";\n      row.innerHTML=`<div><b>${ex.name}</b><span>${ex.sets} sets · ${ex.reps}</span></div><button>Remove</button>`;\n      row.querySelector(\"button\").onclick=()=>{routineA.splice(i,1);saveState();renderRoutine()};\n      box.appendChild(row);\n    });\n  }\n  document.getElementById(\"editRoutineBtn\").onclick=()=>{renderRoutine();open(\"routineOverlay\")};\n  document.getElementById(\"manageBtn\").onclick=()=>{renderRoutine();open(\"routineOverlay\")};\n  document.getElementById(\"addExerciseBtn\").onclick=()=>{closeAll();setTimeout(()=>open(\"exerciseOverlay\"),100)};\n  document.getElementById(\"saveExercise\").onclick=()=>{\n    const name=document.getElementById(\"exerciseName\").value.trim();\n    const sets=Number(document.getElementById(\"exerciseSets\").value);\n    const reps=document.getElementById(\"exerciseReps\").value.trim();\n    if(!name||!sets||!reps)return;\n    routineA.push({name,sets,reps});\n    saveState();\n    closeAll();setTimeout(()=>{renderRoutine();open(\"routineOverlay\")},100);\n  };\n\n  function openWorkout(){\n    const box=document.getElementById(\"workoutList\");\n    box.innerHTML=\"\";\n    routineA.forEach((ex,i)=>{\n      const b=document.createElement(\"button\");\n      b.className=\"sheet-action\";\n      b.innerHTML=`${i+1}. ${ex.name} <span style=\"float:right;color:var(--muted)\">${ex.sets} × ${ex.reps}</span>`;\n      box.appendChild(b);\n    });\n    open(\"workoutOverlay\");\n  }\n  document.getElementById(\"todayStart\").onclick=openWorkout;\n  document.getElementById(\"startWorkoutBtn\").onclick=openWorkout;\n  document.getElementById(\"finishWorkout\").onclick=()=>{closeAll();showToast(\"🔥 Workout logged.\")};\n  document.getElementById(\"calendarBtn\").onclick=()=>open(\"calendarOverlay\");\n  document.getElementById(\"historyBtn\").onclick=()=>open(\"calendarOverlay\");\n\n  function renderProgress(){\n    const start=weights[0].weight;\n    const cur=currentWeight();\n    const delta=cur-start;\n    document.getElementById(\"progressWeight\").textContent=cur.toFixed(1)+\" kg\";\n    document.getElementById(\"progressChange\").innerHTML=(delta<=0?\"↓ \":\"↑ \")+Math.abs(delta).toFixed(1)+\" kg<br>since Aug 1\";\n    document.getElementById(\"startWeight\").textContent=start.toFixed(1)+\" kg\";\n    document.getElementById(\"currentWeight\").textContent=cur.toFixed(1)+\" kg\";\n    document.getElementById(\"progressBMI\").textContent=bmi().toFixed(1);\n  }\n  function renderWeightHistory(){\n    const box=document.getElementById(\"weightHistoryList\");\n    box.innerHTML=\"\";\n    [...weights].reverse().forEach(w=>{\n      const b=document.createElement(\"button\");\n      b.className=\"sheet-action\";\n      const d=new Date(w.date+\"T00:00:00\");\n      b.innerHTML=`${d.toLocaleDateString(\"en-US\",{month:\"short\",day:\"numeric\"})}<span style=\"float:right\">${w.weight.toFixed(1)} kg</span>`;\n      box.appendChild(b);\n    });\n  }\n  document.getElementById(\"logWeightBtn\").onclick=()=>open(\"weightOverlay\");\n  document.getElementById(\"weightHistoryBtn\").onclick=()=>{renderWeightHistory();open(\"weightHistoryOverlay\")};\n  document.getElementById(\"weightHistoryBtnBottom\").onclick=()=>{renderWeightHistory();open(\"weightHistoryOverlay\")};\n  document.getElementById(\"saveWeight\").onclick=()=>{\n    const w=Number(document.getElementById(\"weightInput\").value);\n    const d=document.getElementById(\"weightDate\").value;\n    if(!w||!d)return;\n    weights.push({date:d,weight:w});\n    weights.sort((a,b)=>a.date.localeCompare(b.date));\n    saveState();\n    renderToday();renderProgress();closeAll();showToast(\"Weight logged.\");\n  };\n\n  // Nav — real cross-file navigation\n  const NAV_TARGETS = {\n    Home: \"johanns_home_ux_first_v3.html\",\n    Tasks: \"johanns_tasks_soft_minimal_v2.html\",\n    Budget: \"johanns_budget_minimal_spacious_auto_v2.html\",\n    Journal: \"johanns_journal_v1.html\"\n  };\n  document.querySelectorAll(\".nav\").forEach(btn=>{\n    btn.onclick=()=>{\n      if(btn.dataset.nav===\"Fitness\") return;\n      if(NAV_TARGETS[btn.dataset.nav]) window.location.href = NAV_TARGETS[btn.dataset.nav];\n      else showToast(\"Profile — coming soon\");\n    };\n  });\n\n  // Shared profile avatar\n  const avatarEl = document.querySelector(\".avatar\");\n  if(avatarEl){\n    const savedAvatar = await JDB.get(\"profile\",\"avatar\");\n    if(savedAvatar){\n      avatarEl.style.backgroundImage = `url(${savedAvatar})`;\n      avatarEl.style.backgroundSize = \"cover\";\n      avatarEl.style.backgroundPosition = \"center\";\n      avatarEl.textContent = \"\";\n    }\n  }\n\n  renderToday();\n  renderProgress();\n})();\n</script>\n<script src=\"./pwa-core.js\"></script></body>\n</html>\n", "budget": "<!DOCTYPE html>\n<html lang=\"en\">\n<head><script>document.documentElement.classList.toggle(\"embedded\", window.self !== window.top);</script><base href=\"./\">\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\" />\n<title>Johann's Personal Space — Budget</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F7F4F6;\n  --card:#FFFFFF;\n  --border:#E9E1E7;\n  --pink:#E31C79;\n  --pink-soft:#FBE8F1;\n  --plum:#3B2354;\n  --plum-soft:#F0EAF4;\n  --text:#1E1B22;\n  --muted:#716976;\n  --muted2:#A198A6;\n  --cream:#FFF8EE;\n  --green:#1F9E77;\n  --red:#D6413F;\n  --font-display:'Baloo 2','Segoe UI Rounded',sans-serif;\n  --font-body:'Inter',-apple-system,sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  min-height:100vh;\n  background:var(--bg);\n  font-family:var(--font-body);\n  color:var(--text);\n  display:flex;\n  justify-content:center;\n  align-items:flex-start;\n  padding:24px 14px;\n}\nbutton,input{font:inherit}\n.device{\n  width:390px;max-width:100%;\n  padding:12px;background:#0F0B12;\n  border-radius:48px;\n  box-shadow:0 40px 80px -30px rgba(30,10,40,.46);\n}\n.screen{\n  height:844px;\n  background:var(--bg);\n  border-radius:36px;\n  overflow:hidden;\n  display:flex;\n  flex-direction:column;\n  position:relative;\n}\n.statusbar{\n  height:34px;flex:0 0 34px;\n  display:flex;justify-content:space-between;align-items:flex-end;\n  padding:0 26px 4px;\n  font-size:13px;font-weight:600;\n  position:relative;\n}\n.island{\n  position:absolute;left:50%;top:8px;transform:translateX(-50%);\n  width:110px;height:24px;border-radius:16px;background:#0F0B12;\n}\n.main{\n  flex:1;min-height:0;\n  padding:8px 18px 12px;\n  display:grid;\n  grid-template-rows:auto auto auto auto 1fr auto;\n  gap:12px;\n  overflow:hidden;\n}\n\n/* header */\n.header{\n  display:flex;justify-content:space-between;align-items:flex-start;\n}\n.app-title{\n  margin:0;\n  font-family:var(--font-display);\n  color:var(--plum);\n  font-size:18px;font-weight:700;\n}\n.page-title{\n  margin:1px 0 0;\n  font-family:var(--font-display);\n  color:var(--plum);\n  font-size:27px;font-weight:800;line-height:1;\n}\n.avatar{\n  width:40px;height:40px;border-radius:50%;\n  display:grid;place-items:center;\n  color:#fff;background:var(--plum);\n  font-family:var(--font-display);font-weight:700;\n  border:2px solid white;\n}\n.greeting h2{\n  margin:0;\n  font-family:var(--font-display);\n  font-size:22px;line-height:1.08;font-weight:700;\n}\n.greeting p{\n  margin:2px 0 0;\n  font-size:12px;color:var(--muted);\n}\n.month-strip{\n  display:grid;grid-template-columns:repeat(3,1fr);\n  gap:6px;\n  background:#EFE9ED;\n  border-radius:999px;\n  padding:4px;\n}\n.month-btn{\n  border:none;background:transparent;\n  padding:7px 5px;border-radius:999px;\n  color:var(--muted);\n  font-size:10px;font-weight:750;cursor:pointer;\n}\n.month-btn.active{\n  background:white;color:var(--plum);\n  box-shadow:0 3px 10px rgba(59,35,84,.08);\n}\n\n/* hero */\n.hero{\n  background:white;\n  border:1px solid var(--border);\n  border-radius:22px;\n  padding:15px;\n}\n.hero-top{\n  display:flex;justify-content:space-between;align-items:center;\n}\n.eyebrow{\n  color:var(--muted2);\n  font-size:10px;font-weight:850;letter-spacing:.09em;\n}\n.edit-btn{\n  border:none;background:var(--plum-soft);\n  color:var(--plum);\n  padding:6px 9px;border-radius:999px;\n  font-size:10px;font-weight:800;cursor:pointer;\n}\n.amount-row{\n  display:flex;align-items:flex-end;justify-content:space-between;gap:10px;\n  margin-top:5px;\n}\n.hero-amount{\n  font-family:var(--font-display);\n  color:var(--plum);\n  font-size:36px;line-height:1;font-weight:800;\n}\n.quick-plus{\n  width:34px;height:34px;border:none;border-radius:50%;\n  background:var(--pink);color:white;\n  font-size:21px;font-weight:850;\n  display:grid;place-items:center;cursor:pointer;\n}\n.hero-copy{\n  margin-top:4px;\n  font-size:11.5px;line-height:1.35;color:var(--muted);\n}\n.hero-stats{\n  display:grid;grid-template-columns:repeat(3,1fr);\n  gap:8px;margin-top:12px;\n}\n.stat{\n  padding-top:8px;border-top:1px solid var(--border);\n}\n.stat span{\n  display:block;font-size:8.7px;color:var(--muted2);margin-bottom:2px;\n}\n.stat b{\n  font-size:11px;color:var(--text);\n}\n\n/* bento */\n.bento{\n  display:grid;grid-template-columns:1.18fr .82fr;gap:10px;\n}\n.bento-card{\n  background:white;border:1px solid var(--border);\n  border-radius:20px;padding:13px;\n}\n.card-title{\n  display:flex;align-items:center;gap:5px;\n  font-size:10px;font-weight:900;letter-spacing:.07em;color:var(--plum);\n  margin-bottom:5px;\n}\n.card-copy{\n  margin:0 0 10px;\n  font-size:10.5px;line-height:1.35;color:var(--muted);\n}\n.bill{\n  padding:8px 0;border-top:1px solid var(--border);\n  cursor:pointer;\n}\n.bill:first-of-type{border-top:none;padding-top:0}\n.bill-date{font-size:8.7px;color:var(--muted2);font-weight:850}\n.bill-line{\n  display:flex;justify-content:space-between;gap:6px;\n  margin-top:2px;font-size:11.2px;font-weight:750;\n}\n.text-link{\n  border:none;background:none;color:var(--pink);\n  padding:6px 0 0;\n  font-size:9.6px;font-weight:850;cursor:pointer;\n}\n.spend-now{\n  font-family:var(--font-display);\n  font-size:25px;font-weight:800;color:var(--plum);\n  line-height:1;margin-top:4px;\n}\n.spend-label{\n  font-size:9px;color:var(--muted2);margin-top:2px;\n}\n.spend-week{\n  margin-top:13px;padding-top:10px;border-top:1px solid var(--border);\n}\n.spend-week b{display:block;font-size:12px}\n.spend-week span{font-size:9px;color:var(--muted2)}\n\n/* categories */\n.categories{\n  background:white;border:1px solid var(--border);\n  border-radius:20px;padding:13px;\n  min-height:0;\n}\n.categories-head{\n  display:flex;justify-content:space-between;align-items:flex-start;\n  margin-bottom:9px;\n}\n.categories-head p{\n  margin:2px 0 0;color:var(--muted);font-size:10px;\n}\n.cat-grid{\n  display:grid;grid-template-columns:repeat(3,1fr);gap:8px;\n}\n.cat{\n  border:1px solid var(--border);\n  background:#FCFAFB;\n  border-radius:16px;\n  padding:10px 8px;\n  text-align:left;cursor:pointer;\n}\n.cat:nth-child(1){background:var(--pink-soft)}\n.cat:nth-child(2){background:var(--cream)}\n.cat:nth-child(3){background:var(--plum-soft)}\n.cat-emoji{font-size:17px;line-height:1}\n.cat-name{\n  margin-top:4px;font-size:10px;font-weight:850;color:var(--plum);\n}\n.cat-spend{\n  margin-top:6px;\n  font-family:var(--font-display);\n  font-size:15px;font-weight:800;color:var(--plum);line-height:1;\n}\n.cat-left{\n  margin-top:3px;font-size:8.8px;color:var(--muted);\n}\n\n/* footer actions */\n.actions-row{\n  display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;\n}\n.add-transaction{\n  border:none;background:var(--plum);color:white;\n  border-radius:13px;padding:10px 12px;\n  font-size:11px;font-weight:850;cursor:pointer;\n}\n.view-all{\n  border:none;background:none;color:var(--pink);\n  font-size:10.5px;font-weight:850;cursor:pointer;\n}\n\n/* nav */\n.bottom-nav{\n  flex:0 0 62px;height:62px;\n  background:white;border-top:1px solid var(--border);\n  display:grid;grid-template-columns:repeat(6,1fr);\n  padding:7px 4px 9px;\n}\n.nav-item{\n  border:none;background:none;color:var(--muted2);\n  display:flex;flex-direction:column;align-items:center;gap:3px;\n  font-size:9px;font-weight:700;cursor:pointer;\n}\n.nav-icon{\n  width:18px;height:18px;border:1.7px solid currentColor;border-radius:6px;\n}\n.nav-item.active{color:var(--pink)}\n.nav-item.active .nav-icon{\n  background:var(--pink);border-color:var(--pink);\n}\n\n/* overlays */\n.overlay{\n  position:absolute;inset:0;\n  background:rgba(30,20,35,.42);\n  display:none;align-items:flex-end;z-index:30;\n}\n.overlay.show{display:flex}\n.sheet{\n  width:100%;\n  max-height:76%;\n  overflow:auto;\n  background:white;\n  border-radius:24px 24px 0 0;\n  padding:12px 19px 24px;\n}\n.handle{\n  width:36px;height:4px;border-radius:999px;background:var(--border);\n  margin:0 auto 15px;\n}\n.sheet h3{\n  margin:0;\n  font-family:var(--font-display);\n  font-size:22px;color:var(--plum);\n}\n.sheet-sub{\n  margin:3px 0 13px;\n  color:var(--muted);font-size:11.5px;line-height:1.35;\n}\n.field{margin:11px 0}\n.field label{\n  display:block;margin-bottom:5px;\n  font-size:10px;font-weight:850;color:var(--muted);\n}\n.field input{\n  width:100%;\n  border:1.5px solid var(--border);\n  background:var(--bg);\n  border-radius:12px;padding:10px 11px;\n  outline:none;\n}\n.field input:focus{border-color:var(--pink)}\n.chips{display:flex;gap:6px;flex-wrap:wrap}\n.chip{\n  border:1px solid var(--border);background:var(--bg);\n  border-radius:999px;padding:7px 9px;\n  font-size:10px;font-weight:750;cursor:pointer;\n}\n.chip.active{background:var(--plum);color:white;border-color:var(--plum)}\n.action-grid{\n  display:grid;grid-template-columns:repeat(3,1fr);gap:8px;\n}\n.action-card{\n  border:1px solid var(--border);background:var(--bg);\n  border-radius:16px;padding:12px 5px;text-align:center;cursor:pointer;\n}\n.action-card .emoji{font-size:24px}\n.action-card b{display:block;margin-top:5px;font-size:10.5px}\n.primary{\n  width:100%;border:none;background:var(--pink);color:white;\n  border-radius:12px;padding:11px;\n  font-weight:850;cursor:pointer;margin-top:7px;\n}\n.secondary{\n  width:100%;border:none;background:none;color:var(--muted);\n  padding:9px;cursor:pointer;\n}\n.sheet-action{\n  width:100%;border:none;background:none;text-align:left;\n  border-top:1px solid var(--border);\n  padding:12px 1px;\n  font-size:13px;font-weight:700;cursor:pointer;\n}\n.breakdown{\n  background:var(--plum-soft);\n  border-radius:18px;padding:13px;margin:10px 0 12px;\n}\n.breakdown-big{\n  font-family:var(--font-display);\n  font-size:29px;font-weight:800;color:var(--plum);\n}\n.break-row{\n  display:flex;justify-content:space-between;\n  border-top:1px solid rgba(59,35,84,.10);\n  padding-top:7px;margin-top:7px;\n  font-size:11px;\n}\n.auto-note{\n  background:#F3F7F5;\n  color:#52655C;\n  border-radius:13px;\n  padding:9px 10px;\n  font-size:10.5px;line-height:1.35;\n  margin:10px 0;\n}\n.toast{\n  position:absolute;left:50%;bottom:72px;\n  transform:translate(-50%,10px);\n  background:var(--plum);color:white;\n  padding:8px 13px;border-radius:999px;\n  font-size:11px;font-weight:750;\n  opacity:0;pointer-events:none;transition:.2s;z-index:50;white-space:nowrap;\n}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.placeholder{\n  flex:1;display:grid;place-items:center;text-align:center;\n  padding:30px;color:var(--muted);\n}\n.placeholder h2{margin:0 0 5px;color:var(--plum)}\n\n@media(max-width:430px){\n  body{padding:0}\n  .device{width:100%;padding:0;border-radius:0}\n  .screen{height:100vh;border-radius:0}\n}\n</style>\n<style id=\"app-shell-embedded-overrides\">\nhtml.embedded, html.embedded body{ height:100%; padding:0 !important; margin:0 !important; align-items:stretch !important; justify-content:stretch !important; }\nhtml.embedded .device{ width:100% !important; max-width:100% !important; height:100dvh !important; background:transparent !important; padding:0 !important; border-radius:0 !important; box-shadow:none !important; }\nhtml.embedded .screen{ height:100dvh !important; border-radius:0 !important; padding-top:max(14px, env(safe-area-inset-top)) !important; }\nhtml.embedded .statusbar, html.embedded .status, html.embedded .dynamic-island, html.embedded .island{ display:none !important; }\nhtml.embedded .bottom-nav, html.embedded .bottom{ padding-bottom:max(9px, env(safe-area-inset-bottom)) !important; }\n</style></head>\n<body>\n<div class=\"device\">\n  <div class=\"screen\">\n    <div class=\"statusbar\">\n      <div class=\"island\"></div>\n      <span>9:41</span>\n      <span>● ● ▰</span>\n    </div>\n\n    <main class=\"main\" id=\"budgetPage\">\n      <div class=\"header\">\n        <div>\n          <p class=\"app-title\">Johann's Personal Space</p>\n          <h1 class=\"page-title\">Budget</h1>\n        </div>\n        <div class=\"avatar\">J</div>\n      </div>\n\n      <div class=\"greeting\">\n        <h2>Okay… saan napunta? 👀</h2>\n        <p>September · keeping tabs, not judging.</p>\n      </div>\n\n      <div class=\"month-strip\">\n        <button class=\"month-btn\" data-month=\"aug\">AUG</button>\n        <button class=\"month-btn active\" data-month=\"sep\">SEPTEMBER</button>\n        <button class=\"month-btn\" data-month=\"oct\">OCT</button>\n      </div>\n\n      <section class=\"hero\" id=\"moneyHero\">\n        <div class=\"hero-top\">\n          <div class=\"eyebrow\">MONEY LEFT</div>\n          <button class=\"edit-btn\" id=\"editBudgetBtn\">Edit ✎</button>\n        </div>\n\n        <div class=\"amount-row\">\n          <div>\n            <div class=\"hero-amount\" id=\"moneyLeft\">₱18,450</div>\n            <div class=\"hero-copy\" id=\"heroCopy\">Okayyy. Kaya pa naman. Behave lang tayo. 👀</div>\n          </div>\n          <button class=\"quick-plus\" id=\"quickAddBtn\">+</button>\n        </div>\n\n        <div class=\"hero-stats\">\n          <div class=\"stat\"><span>Income</span><b id=\"incomeStat\">₱52,000</b></div>\n          <div class=\"stat\"><span>Spent</span><b id=\"spentStat\">₱21,550</b></div>\n          <div class=\"stat\"><span>Bills left</span><b id=\"billsStat\">₱12,000</b></div>\n        </div>\n      </section>\n\n      <section class=\"bento\">\n        <article class=\"bento-card\">\n          <div class=\"card-title\">🧾 BILLS</div>\n          <p class=\"card-copy\">Mga bagay na hindi pwedeng i-ghost.</p>\n\n          <div id=\"billList\"></div>\n\n          <button class=\"text-link\" id=\"seeBills\">See all →</button>\n        </article>\n\n        <article class=\"bento-card\" id=\"spendingCard\">\n          <div class=\"card-title\">SPENDING 💸</div>\n          <p class=\"card-copy\">So… saan nga napunta?</p>\n\n          <div class=\"spend-now\" id=\"todaySpend\">₱1,240</div>\n          <div class=\"spend-label\">today</div>\n\n          <div class=\"spend-week\">\n            <b id=\"weekSpend\">₱5,680</b>\n            <span>this week</span>\n          </div>\n\n          <button class=\"text-link\" id=\"spendingDetails\">Details →</button>\n        </article>\n      </section>\n\n      <section class=\"categories\">\n        <div class=\"categories-head\">\n          <div>\n            <div class=\"eyebrow\">WHERE IT WENT</div>\n            <p>Top categories this month.</p>\n          </div>\n          <button class=\"text-link\" id=\"allCategories\">All →</button>\n        </div>\n\n        <div class=\"cat-grid\">\n          <button class=\"cat\" data-category=\"Food\">\n            <div class=\"cat-emoji\">🍜</div>\n            <div class=\"cat-name\">Food</div>\n            <div class=\"cat-spend\" id=\"foodSpend\">₱6.4k</div>\n            <div class=\"cat-left\" id=\"foodLeft\">₱1.6k left</div>\n          </button>\n\n          <button class=\"cat\" data-category=\"Transport\">\n            <div class=\"cat-emoji\">🚗</div>\n            <div class=\"cat-name\">Go</div>\n            <div class=\"cat-spend\" id=\"transportSpend\">₱2.1k</div>\n            <div class=\"cat-left\" id=\"transportLeft\">₱1.9k left</div>\n          </button>\n\n          <button class=\"cat\" data-category=\"Wants\">\n            <div class=\"cat-emoji\">🛍️</div>\n            <div class=\"cat-name\">Wants</div>\n            <div class=\"cat-spend\" id=\"wantsSpend\">₱3.8k</div>\n            <div class=\"cat-left\" id=\"wantsLeft\">₱1.2k left</div>\n          </button>\n        </div>\n      </section>\n\n      <div class=\"actions-row\">\n        <button class=\"add-transaction\" id=\"quickAddBottom\">+ Add transaction</button>\n        <button class=\"view-all\" id=\"viewTransactions\">View all →</button>\n      </div>\n    </main>\n\n    <main id=\"placeholder\" class=\"placeholder\" style=\"display:none\">\n      <div>\n        <h2 id=\"placeholderTitle\">Home</h2>\n        <p>Placeholder — Budget is the active prototype.</p>\n      </div>\n    </main>\n\n    <nav class=\"bottom-nav\">\n      <button class=\"nav-item\" data-nav=\"Home\"><span class=\"nav-icon\"></span>Home</button>\n      <button class=\"nav-item\" data-nav=\"Tasks\"><span class=\"nav-icon\"></span>Tasks</button>\n      <button class=\"nav-item\" data-nav=\"Health\"><span class=\"nav-icon\"></span>Health</button>\n      <button class=\"nav-item active\" data-nav=\"Budget\"><span class=\"nav-icon\"></span>Budget</button>\n      <button class=\"nav-item\" data-nav=\"Journal\"><span class=\"nav-icon\"></span>Journal</button>\n      <button class=\"nav-item\" data-nav=\"Profile\"><span class=\"nav-icon\"></span>Profile</button>\n    </nav>\n\n    <!-- Quick add -->\n    <div class=\"overlay\" id=\"quickOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Quick add</h3>\n        <div class=\"sheet-sub\">So… what happened?</div>\n        <div class=\"action-grid\">\n          <button class=\"action-card\" data-add=\"spent\"><div class=\"emoji\">💸</div><b>I spent</b></button>\n          <button class=\"action-card\" data-add=\"income\"><div class=\"emoji\">💰</div><b>Money in</b></button>\n          <button class=\"action-card\" data-add=\"bill\"><div class=\"emoji\">🧾</div><b>New bill</b></button>\n        </div>\n        <button class=\"secondary\" id=\"closeQuick\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Expense -->\n    <div class=\"overlay\" id=\"expenseOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>How much?</h3>\n        <div class=\"sheet-sub\">Quick lang. Hindi tayo nag-a-accounting exam.</div>\n        <div class=\"field\">\n          <label>AMOUNT</label>\n          <input type=\"number\" id=\"expenseAmount\" placeholder=\"350\">\n        </div>\n        <div class=\"field\">\n          <label>WHAT WAS IT FOR?</label>\n          <div class=\"chips\" id=\"expenseCats\">\n            <button class=\"chip active\" data-cat=\"Food\">🍜 Food</button>\n            <button class=\"chip\" data-cat=\"Transport\">🚗 Transport</button>\n            <button class=\"chip\" data-cat=\"Wants\">🛍️ Wants</button>\n            <button class=\"chip\" data-cat=\"Other\">••• Other</button>\n          </div>\n        </div>\n        <div class=\"field\">\n          <label>NOTE · OPTIONAL</label>\n          <input id=\"expenseNote\" placeholder=\"Lunch\">\n        </div>\n        <button class=\"primary\" id=\"saveExpense\">Add expense</button>\n        <button class=\"secondary close-detail\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Income -->\n    <div class=\"overlay\" id=\"incomeOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Money in 💰</h3>\n        <div class=\"sheet-sub\">We love to see it.</div>\n        <div class=\"field\">\n          <label>AMOUNT</label>\n          <input type=\"number\" id=\"incomeAmount\" placeholder=\"12000\">\n        </div>\n        <button class=\"primary\" id=\"saveIncome\">Add money</button>\n        <button class=\"secondary close-detail\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Bill -->\n    <div class=\"overlay\" id=\"billOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>New bill 🧾</h3>\n        <div class=\"sheet-sub\">Future Johann would like advance notice.</div>\n        <div class=\"field\">\n          <label>BILL</label>\n          <input id=\"billName\" placeholder=\"Internet\">\n        </div>\n        <div class=\"field\">\n          <label>AMOUNT</label>\n          <input type=\"number\" id=\"billAmount\" placeholder=\"1699\">\n        </div>\n        <div class=\"field\">\n          <label>DUE DATE</label>\n          <input type=\"date\" id=\"billDueDate\">\n        </div>\n        <div class=\"field\">\n          <label>REMINDER · OPTIONAL</label>\n          <input id=\"billReminder\" placeholder=\"e.g. 2 days before\">\n        </div>\n        <button class=\"primary\" id=\"saveBill\">Add bill</button>\n        <button class=\"secondary close-detail\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Edit budget -->\n    <div class=\"overlay\" id=\"editBudgetOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Edit September</h3>\n        <div class=\"sheet-sub\">Change the plan here. Everything else adjusts automatically.</div>\n\n        <div class=\"field\">\n          <label>MONTHLY INCOME</label>\n          <input type=\"number\" id=\"editIncome\">\n        </div>\n\n        <div class=\"field\">\n          <label>PLANNED / UNPAID BILLS</label>\n          <input type=\"number\" id=\"editBills\">\n        </div>\n\n        <div class=\"auto-note\">\n          ✨ Money Left recalculates automatically when you add income, log spending, add a bill, or mark a bill as paid.\n        </div>\n\n        <button class=\"primary\" id=\"saveBudgetEdit\">Save changes</button>\n        <button class=\"secondary\" id=\"closeBudgetEdit\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Money detail -->\n    <div class=\"overlay\" id=\"moneyOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>September money</h3>\n        <div class=\"sheet-sub\">The math is mathing. Mostly. 👀</div>\n\n        <div class=\"breakdown\">\n          <div class=\"breakdown-big\" id=\"sheetMoneyLeft\">₱18,450 left</div>\n          <div class=\"break-row\"><span>Income</span><b id=\"sheetIncome\">₱52,000</b></div>\n          <div class=\"break-row\"><span>Spent</span><b id=\"sheetSpent\">₱21,550</b></div>\n          <div class=\"break-row\"><span>Upcoming bills</span><b id=\"sheetBills\">₱12,000</b></div>\n        </div>\n\n        <div class=\"auto-note\">Totals update automatically from your transactions and bill status.</div>\n        <button class=\"sheet-action\" id=\"editFromBreakdown\">Edit monthly plan</button>\n        <button class=\"secondary\" id=\"closeMoney\">Close</button>\n      </div>\n    </div>\n\n    <!-- Bill detail -->\n    <div class=\"overlay\" id=\"billDetailOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3 id=\"billDetailTitle\">Internet</h3>\n        <div class=\"sheet-sub\" id=\"billDetailMeta\">₱1,699 · Due September 8</div>\n        <button class=\"sheet-action\" id=\"markPaid\">Mark as paid</button>\n        <button class=\"sheet-action\" id=\"editBillAction\">Edit bill ✎</button>\n        <button class=\"sheet-action danger\" id=\"deleteBillAction\" style=\"color:var(--red)\">Delete bill</button>\n        <button class=\"secondary\" id=\"closeBillDetail\">Close</button>\n      </div>\n    </div>\n\n    <!-- Edit bill -->\n    <div class=\"overlay\" id=\"editBillOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Edit bill ✎</h3>\n        <div class=\"sheet-sub\">Type whatever you want here — name, amount, due date, reminder.</div>\n\n        <div class=\"field\">\n          <label>BILL NAME</label>\n          <input id=\"editBillName\" placeholder=\"Internet\">\n        </div>\n\n        <div class=\"field\">\n          <label>AMOUNT</label>\n          <input type=\"number\" id=\"editBillAmount\" placeholder=\"1699\">\n        </div>\n\n        <div class=\"field\">\n          <label>DUE DATE</label>\n          <input type=\"date\" id=\"editBillDueDate\">\n        </div>\n\n        <div class=\"field\">\n          <label>REMINDER · OPTIONAL</label>\n          <input id=\"editBillReminder\" placeholder=\"e.g. 2 days before\">\n        </div>\n\n        <button class=\"primary\" id=\"saveBillEdit\">Save changes</button>\n        <button class=\"secondary\" id=\"cancelBillEdit\">Cancel</button>\n      </div>\n    </div>\n\n    <!-- Full bills -->\n    <div class=\"overlay\" id=\"allBillsOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>All bills 🧾</h3>\n        <div class=\"sheet-sub\">Unfortunately, adulthood has subscriptions.</div>\n        <div id=\"allBillsList\"></div>\n        <button class=\"primary\" id=\"addBillFromList\">+ Add bill</button>\n        <button class=\"secondary\" id=\"closeAllBills\">Close</button>\n      </div>\n    </div>\n\n    <!-- Category -->\n    <div class=\"overlay\" id=\"categoryOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3 id=\"catTitle\">🍜 Food</h3>\n        <div class=\"sheet-sub\" id=\"catCopy\">Apparently, pagkain is a personality trait.</div>\n\n        <div class=\"breakdown\">\n          <div class=\"breakdown-big\" id=\"catSpendDetail\">₱6,420</div>\n          <div class=\"break-row\"><span>Monthly budget</span><b id=\"catBudgetDetail\">₱8,000</b></div>\n          <div class=\"break-row\"><span>Left</span><b id=\"catLeftDetail\">₱1,580</b></div>\n        </div>\n\n        <button class=\"sheet-action\">Recent transactions →</button>\n        <button class=\"sheet-action\">Edit category budget</button>\n        <button class=\"secondary\" id=\"closeCategory\">Close</button>\n      </div>\n    </div>\n\n    <!-- Transactions -->\n    <div class=\"overlay\" id=\"transactionsOverlay\">\n      <div class=\"sheet\">\n        <div class=\"handle\"></div>\n        <h3>Transactions</h3>\n        <div class=\"sheet-sub\">Reviewing the evidence, I see. 👀</div>\n        <button class=\"sheet-action\">🍜 Lunch · ₱350</button>\n        <button class=\"sheet-action\">🚗 Grab · ₱280</button>\n        <button class=\"sheet-action\">🛍️ Shirt · ₱1,299</button>\n        <button class=\"sheet-action\">🍜 Groceries · ₱780</button>\n        <button class=\"secondary\" id=\"closeTransactions\">Close</button>\n      </div>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n  </div>\n</div>\n\n<script src=\"./johanns-db.js\"></script>\n<script>\n(async () => {\n  await JDB.ready;\n\n  const defaultState = {\n    income: 52000,\n    spent: 21550,\n    bills: [\n      {id:\"b1\", name:\"Internet\", amount:1699, due:\"2026-09-08\", reminder:\"2 days before\", paid:false},\n      {id:\"b2\", name:\"Electricity\", amount:3200, due:\"2026-09-12\", reminder:\"1 day before\", paid:false},\n      {id:\"b3\", name:\"Phone plan\", amount:999, due:\"2026-09-18\", reminder:\"2 days before\", paid:false},\n      {id:\"b4\", name:\"Streaming\", amount:549, due:\"2026-09-22\", reminder:\"\", paid:false}\n    ],\n    extraReservedBills: 5553,\n    catBudgets: {Food:8000, Transport:4000, Wants:5000},\n    catSpent: {Food:6420, Transport:2150, Wants:3860}\n  };\n  const saved = await JDB.get(\"budget\", \"state\");\n  const state = saved || defaultState;\n\n  let income = state.income;\n  let spent = state.spent;\n  let bills = state.bills;\n  let extraReservedBills = state.extraReservedBills;\n  let activeBillId = null;\n  const catBudgets = state.catBudgets;\n  const catSpent = state.catSpent;\n\n  const saveState = JDB.debounce(()=> JDB.put(\"budget\", \"state\", {\n    income, spent, bills, extraReservedBills, catBudgets, catSpent\n  }), 300);\n\n  const peso = n => \"₱\" + Math.round(n).toLocaleString(\"en-PH\");\n  const compact = n => n >= 1000 ? \"₱\" + (n/1000).toFixed(1).replace(\".0\",\"\") + \"k\" : peso(n);\n\n  const toast = document.getElementById(\"toast\");\n  const overlays = [...document.querySelectorAll(\".overlay\")];\n\n  function showToast(msg){\n    toast.textContent = msg;\n    toast.classList.add(\"show\");\n    clearTimeout(window.__toast);\n    window.__toast = setTimeout(()=>toast.classList.remove(\"show\"),1700);\n  }\n\n  function open(id){ document.getElementById(id).classList.add(\"show\"); }\n  function closeAll(){ overlays.forEach(o=>o.classList.remove(\"show\")); }\n  overlays.forEach(o=>o.onclick=e=>{ if(e.target===o) o.classList.remove(\"show\"); });\n\n  function totalUnpaidBills(){\n    return bills.filter(b=>!b.paid).reduce((sum,b)=>sum+b.amount,0) + extraReservedBills;\n  }\n\n  function formatDue(due){\n    if(!due) return \"NO DATE\";\n    const d = new Date(due + \"T00:00:00\");\n    return d.toLocaleDateString(\"en-US\",{month:\"short\",day:\"numeric\"}).toUpperCase();\n  }\n\n  function formatDueLong(due){\n    if(!due) return \"No due date\";\n    const d = new Date(due + \"T00:00:00\");\n    return \"Due \" + d.toLocaleDateString(\"en-US\",{month:\"long\",day:\"numeric\"});\n  }\n\n  function updateAll(){\n    const billsLeft = totalUnpaidBills();\n    const left = income - spent - billsLeft;\n\n    document.getElementById(\"moneyLeft\").textContent = peso(left);\n    document.getElementById(\"incomeStat\").textContent = peso(income);\n    document.getElementById(\"spentStat\").textContent = peso(spent);\n    document.getElementById(\"billsStat\").textContent = peso(billsLeft);\n\n    document.getElementById(\"sheetMoneyLeft\").textContent = peso(left) + \" left\";\n    document.getElementById(\"sheetIncome\").textContent = peso(income);\n    document.getElementById(\"sheetSpent\").textContent = peso(spent);\n    document.getElementById(\"sheetBills\").textContent = peso(billsLeft);\n\n    const copy = left > 20000\n      ? \"Okayyy. Financially stable-ish. 😌\"\n      : left > 10000\n      ? \"Okayyy. Kaya pa naman. Behave lang tayo. 👀\"\n      : left > 3000\n      ? \"Medyo careful tayo from here, boss.\"\n      : left >= 0\n      ? \"Wallet says: tama na muna. 😭\"\n      : \"Okay. We have a situation.\";\n    document.getElementById(\"heroCopy\").textContent = copy;\n\n    document.getElementById(\"foodSpend\").textContent = compact(catSpent.Food);\n    document.getElementById(\"foodLeft\").textContent = compact(catBudgets.Food-catSpent.Food) + \" left\";\n    document.getElementById(\"transportSpend\").textContent = compact(catSpent.Transport);\n    document.getElementById(\"transportLeft\").textContent = compact(catBudgets.Transport-catSpent.Transport) + \" left\";\n    document.getElementById(\"wantsSpend\").textContent = compact(catSpent.Wants);\n    document.getElementById(\"wantsLeft\").textContent = compact(catBudgets.Wants-catSpent.Wants) + \" left\";\n\n    renderBills();\n  }\n\n  function renderBills(){\n    const box = document.getElementById(\"billList\");\n    box.innerHTML = \"\";\n\n    const upcoming = bills\n      .filter(b=>!b.paid)\n      .sort((a,b)=>(a.due||\"9999\").localeCompare(b.due||\"9999\"));\n\n    upcoming.slice(0,2).forEach(b=>{\n      const row = document.createElement(\"div\");\n      row.className = \"bill\";\n      row.innerHTML = `\n        <div class=\"bill-date\">${formatDue(b.due)}</div>\n        <div class=\"bill-line\"><span>${b.name}</span><span>${peso(b.amount)}</span></div>\n      `;\n      row.onclick = ()=>openBillDetail(b.id);\n      box.appendChild(row);\n    });\n\n    if(upcoming.length===0){\n      box.innerHTML = `<div style=\"font-size:10.5px;color:var(--muted);padding:5px 0 7px\">Nothing coming up. Suspiciously peaceful. 😌</div>`;\n    }else if(upcoming.length>2){\n      const more = document.createElement(\"div\");\n      more.style.cssText = \"font-size:9px;color:var(--muted2);margin-top:3px\";\n      more.textContent = `+ ${upcoming.length-2} more`;\n      box.appendChild(more);\n    }\n\n    renderAllBills();\n  }\n\n  function renderAllBills(){\n    const list = document.getElementById(\"allBillsList\");\n    if(!list) return;\n    list.innerHTML = \"\";\n\n    bills\n      .slice()\n      .sort((a,b)=>(a.due||\"9999\").localeCompare(b.due||\"9999\"))\n      .forEach(b=>{\n        const btn = document.createElement(\"button\");\n        btn.className = \"sheet-action\";\n        btn.innerHTML = `${b.paid ? \"✓\" : \"○\"} ${b.name} <span style=\"float:right\">${peso(b.amount)}</span><br><span style=\"font-size:10px;color:var(--muted2)\">${formatDueLong(b.due)}${b.paid ? \" · Paid\" : \"\"}</span>`;\n        btn.onclick = ()=>{\n          document.getElementById(\"allBillsOverlay\").classList.remove(\"show\");\n          setTimeout(()=>openBillDetail(b.id),100);\n        };\n        list.appendChild(btn);\n      });\n  }\n\n  function getActiveBill(){\n    return bills.find(b=>b.id===activeBillId);\n  }\n\n  function openBillDetail(id){\n    activeBillId = id;\n    const b = getActiveBill();\n    if(!b) return;\n\n    document.getElementById(\"billDetailTitle\").textContent = b.name;\n    document.getElementById(\"billDetailMeta\").textContent =\n      `${peso(b.amount)} · ${formatDueLong(b.due)}${b.reminder ? \" · Reminder: \" + b.reminder : \"\"}`;\n    document.getElementById(\"markPaid\").textContent = b.paid ? \"Mark as unpaid\" : \"Mark as paid\";\n    open(\"billDetailOverlay\");\n  }\n\n  document.querySelectorAll(\".month-btn\").forEach(btn=>{\n    btn.onclick=()=>{\n      document.querySelectorAll(\".month-btn\").forEach(b=>b.classList.remove(\"active\"));\n      btn.classList.add(\"active\");\n      if(btn.dataset.month===\"aug\") showToast(\"Reviewing the evidence, I see. 👀\");\n      if(btn.dataset.month===\"oct\") showToast(\"Advance mag-isip. I respect it.\");\n    };\n  });\n\n  // Hero detail/edit\n  document.getElementById(\"moneyHero\").onclick=e=>{\n    if(e.target.closest(\"#quickAddBtn\") || e.target.closest(\"#editBudgetBtn\")) return;\n    open(\"moneyOverlay\");\n  };\n\n  document.getElementById(\"editBudgetBtn\").onclick=()=>{\n    document.getElementById(\"editIncome\").value = income;\n    document.getElementById(\"editBills\").value = totalUnpaidBills();\n    open(\"editBudgetOverlay\");\n  };\n\n  document.getElementById(\"editFromBreakdown\").onclick=()=>{\n    closeAll();\n    document.getElementById(\"editIncome\").value = income;\n    document.getElementById(\"editBills\").value = totalUnpaidBills();\n    setTimeout(()=>open(\"editBudgetOverlay\"),100);\n  };\n\n  document.getElementById(\"closeBudgetEdit\").onclick=closeAll;\n  document.getElementById(\"saveBudgetEdit\").onclick=()=>{\n    income = Number(document.getElementById(\"editIncome\").value) || 0;\n    const desiredBillsTotal = Number(document.getElementById(\"editBills\").value) || 0;\n    const actualBillSum = bills.filter(b=>!b.paid).reduce((s,b)=>s+b.amount,0);\n    extraReservedBills = Math.max(0, desiredBillsTotal - actualBillSum);\n    saveState();\n    updateAll();\n    closeAll();\n    showToast(\"Updated. The math fixed itself. ✨\");\n  };\n  document.getElementById(\"closeMoney\").onclick=closeAll;\n\n  // Quick add\n  document.getElementById(\"quickAddBtn\").onclick=()=>open(\"quickOverlay\");\n  document.getElementById(\"quickAddBottom\").onclick=()=>open(\"quickOverlay\");\n  document.getElementById(\"closeQuick\").onclick=closeAll;\n\n  document.querySelectorAll(\"[data-add]\").forEach(btn=>{\n    btn.onclick=()=>{\n      closeAll();\n      setTimeout(()=>{\n        if(btn.dataset.add===\"spent\") open(\"expenseOverlay\");\n        if(btn.dataset.add===\"income\") open(\"incomeOverlay\");\n        if(btn.dataset.add===\"bill\") open(\"billOverlay\");\n      },100);\n    };\n  });\n\n  document.querySelectorAll(\".chips\").forEach(group=>{\n    group.querySelectorAll(\".chip\").forEach(chip=>{\n      chip.onclick=()=>{\n        group.querySelectorAll(\".chip\").forEach(c=>c.classList.remove(\"active\"));\n        chip.classList.add(\"active\");\n      };\n    });\n  });\n  document.querySelectorAll(\".close-detail\").forEach(btn=>btn.onclick=closeAll);\n\n  document.getElementById(\"saveExpense\").onclick=()=>{\n    const amount = Number(document.getElementById(\"expenseAmount\").value);\n    if(!amount){ showToast(\"Lagyan muna natin ng amount. 👀\"); return; }\n\n    const activeCat = document.querySelector(\"#expenseCats .chip.active\")?.dataset.cat || \"Other\";\n    spent += amount;\n    if(catSpent[activeCat] !== undefined) catSpent[activeCat] += amount;\n\n    saveState();\n    updateAll();\n    closeAll();\n    document.getElementById(\"expenseAmount\").value=\"\";\n    document.getElementById(\"expenseNote\").value=\"\";\n    showToast(amount >= 5000 ? `${peso(amount)}?? Okay, noted. 😭` : `${peso(amount)} logged. Auto-adjusted.`);\n  };\n\n  document.getElementById(\"saveIncome\").onclick=()=>{\n    const amount = Number(document.getElementById(\"incomeAmount\").value);\n    if(!amount){ showToast(\"How much came in?\"); return; }\n    income += amount;\n    saveState();\n    updateAll();\n    closeAll();\n    document.getElementById(\"incomeAmount\").value=\"\";\n    showToast(\"Money came in. Everything adjusted. 😌\");\n  };\n\n  // Add a real editable bill\n  document.getElementById(\"saveBill\").onclick=()=>{\n    const name = document.getElementById(\"billName\").value.trim();\n    const amount = Number(document.getElementById(\"billAmount\").value);\n    const due = document.getElementById(\"billDueDate\").value;\n    const reminder = document.getElementById(\"billReminder\").value.trim();\n\n    if(!name || !amount){\n      showToast(\"Bill name + amount muna.\");\n      return;\n    }\n\n    bills.push({\n      id:\"b\"+Date.now(),\n      name,\n      amount,\n      due,\n      reminder,\n      paid:false\n    });\n\n    saveState();\n    updateAll();\n    closeAll();\n\n    document.getElementById(\"billName\").value=\"\";\n    document.getElementById(\"billAmount\").value=\"\";\n    document.getElementById(\"billDueDate\").value=\"\";\n    document.getElementById(\"billReminder\").value=\"\";\n    showToast(\"Added. Future Johann has been informed.\");\n  };\n\n  // Bill management\n  document.getElementById(\"seeBills\").onclick=()=>open(\"allBillsOverlay\");\n  document.getElementById(\"closeAllBills\").onclick=closeAll;\n  document.getElementById(\"addBillFromList\").onclick=()=>{\n    closeAll();\n    setTimeout(()=>open(\"billOverlay\"),100);\n  };\n  document.getElementById(\"closeBillDetail\").onclick=closeAll;\n\n  document.getElementById(\"markPaid\").onclick=()=>{\n    const b = getActiveBill();\n    if(!b) return;\n\n    if(!b.paid){\n      b.paid = true;\n      spent += b.amount;\n      showToast(\"Paid. One less thing nakaabang sa dilim. 😌\");\n    }else{\n      b.paid = false;\n      spent = Math.max(0, spent - b.amount);\n      showToast(\"Marked unpaid. Back on the radar. 👀\");\n    }\n    saveState();\n    updateAll();\n    closeAll();\n  };\n\n  document.getElementById(\"editBillAction\").onclick=()=>{\n    const b = getActiveBill();\n    if(!b) return;\n\n    document.getElementById(\"editBillName\").value = b.name;\n    document.getElementById(\"editBillAmount\").value = b.amount;\n    document.getElementById(\"editBillDueDate\").value = b.due || \"\";\n    document.getElementById(\"editBillReminder\").value = b.reminder || \"\";\n\n    document.getElementById(\"billDetailOverlay\").classList.remove(\"show\");\n    setTimeout(()=>open(\"editBillOverlay\"),100);\n  };\n\n  document.getElementById(\"saveBillEdit\").onclick=()=>{\n    const b = getActiveBill();\n    if(!b) return;\n\n    const newName = document.getElementById(\"editBillName\").value.trim();\n    const newAmount = Number(document.getElementById(\"editBillAmount\").value);\n    const newDue = document.getElementById(\"editBillDueDate\").value;\n    const newReminder = document.getElementById(\"editBillReminder\").value.trim();\n\n    if(!newName || !newAmount){\n      showToast(\"Name + amount muna.\");\n      return;\n    }\n\n    // If a paid bill amount changes, keep spending consistent.\n    if(b.paid){\n      spent = Math.max(0, spent - b.amount) + newAmount;\n    }\n\n    b.name = newName;\n    b.amount = newAmount;\n    b.due = newDue;\n    b.reminder = newReminder;\n\n    saveState();\n    updateAll();\n    closeAll();\n    showToast(\"Saved. Yes, you can rename things now. ✨\");\n  };\n\n  document.getElementById(\"cancelBillEdit\").onclick=closeAll;\n\n  document.getElementById(\"deleteBillAction\").onclick=()=>{\n    const b = getActiveBill();\n    if(!b) return;\n\n    if(b.paid){\n      spent = Math.max(0, spent - b.amount);\n    }\n\n    bills = bills.filter(x=>x.id!==activeBillId);\n    activeBillId = null;\n    saveState();\n    updateAll();\n    closeAll();\n    showToast(\"Deleted. Gone from the budget.\");\n  };\n\n  // Spending / transactions\n  document.getElementById(\"spendingCard\").onclick=e=>{\n    if(e.target.id!==\"spendingDetails\") open(\"transactionsOverlay\");\n  };\n  document.getElementById(\"spendingDetails\").onclick=()=>open(\"transactionsOverlay\");\n  document.getElementById(\"viewTransactions\").onclick=()=>open(\"transactionsOverlay\");\n  document.getElementById(\"closeTransactions\").onclick=closeAll;\n\n  // Categories\n  const catCopy = {\n    Food:[\"🍜 Food\",\"Apparently, pagkain is a personality trait.\"],\n    Transport:[\"🚗 Transport\",\"Going places. Literally.\"],\n    Wants:[\"🛍️ Wants\",\"Needs? Debatable.\"]\n  };\n\n  document.querySelectorAll(\"[data-category]\").forEach(btn=>{\n    btn.onclick=()=>{\n      const key=btn.dataset.category;\n      document.getElementById(\"catTitle\").textContent=catCopy[key][0];\n      document.getElementById(\"catCopy\").textContent=catCopy[key][1];\n      document.getElementById(\"catSpendDetail\").textContent=peso(catSpent[key]);\n      document.getElementById(\"catBudgetDetail\").textContent=peso(catBudgets[key]);\n      document.getElementById(\"catLeftDetail\").textContent=peso(catBudgets[key]-catSpent[key]);\n      open(\"categoryOverlay\");\n    };\n  });\n\n  document.getElementById(\"closeCategory\").onclick=closeAll;\n  document.getElementById(\"allCategories\").onclick=()=>showToast(\"All categories opens here.\");\n\n  // Nav — real cross-file navigation\n  const NAV_TARGETS = {\n    Home: \"johanns_home_ux_first_v3.html\",\n    Tasks: \"johanns_tasks_soft_minimal_v2.html\",\n    Health: \"johanns_fitness_editorial_concept_v4_buttons.html\",\n    Journal: \"johanns_journal_v1.html\"\n  };\n  document.querySelectorAll(\".nav-item\").forEach(btn=>{\n    btn.onclick=()=>{\n      if(btn.dataset.nav===\"Budget\") return;\n      if(NAV_TARGETS[btn.dataset.nav]) window.location.href = NAV_TARGETS[btn.dataset.nav];\n      else showToast(\"Profile — coming soon\");\n    };\n  });\n\n  // Shared profile avatar\n  const avatarEl = document.querySelector(\".avatar\");\n  if(avatarEl){\n    const savedAvatar = await JDB.get(\"profile\",\"avatar\");\n    if(savedAvatar){\n      avatarEl.style.backgroundImage = `url(${savedAvatar})`;\n      avatarEl.style.backgroundSize = \"cover\";\n      avatarEl.style.backgroundPosition = \"center\";\n      avatarEl.textContent = \"\";\n    }\n  }\n\n  updateAll();\n})();\n</script>\n<script src=\"./pwa-core.js\"></script></body>\n</html>\n", "journal": "<!DOCTYPE html>\n<html lang=\"en\">\n<head><script>document.documentElement.classList.toggle(\"embedded\", window.self !== window.top);</script><base href=\"./\">\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n<title>Johann's Personal Space — Journal</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F9F6F8;\n  --section-bg:#F2EDF1;\n  --card:#FFFFFF;\n  --border:#ECE3EA;\n  --pink:#E31C79;\n  --pink-deep:#B81463;\n  --pink-soft:#FCEAF3;\n  --plum:#3B2354;\n  --plum-dark:#2A1740;\n  --text:#1E1B22;\n  --muted:#746D78;\n  --muted2:#A39AA7;\n  --mint:#1F9E77;\n  --mint-soft:#EEF8F3;\n  --font-display:'Baloo 2','Segoe UI Rounded',sans-serif;\n  --font-body:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;padding:0}\nbody{\n  min-height:100vh;\n  background:var(--bg);\n  color:var(--text);\n  font-family:var(--font-body);\n  display:flex;\n  justify-content:center;\n  align-items:flex-start;\n  padding:24px 14px;\n}\nbutton,input{font:inherit}\n.device{\n  width:390px;\n  max-width:100%;\n  background:#0F0B12;\n  border-radius:48px;\n  padding:12px;\n  box-shadow:0 40px 80px -30px rgba(30,10,40,.48);\n}\n.screen{\n  height:844px;\n  background:var(--bg);\n  border-radius:36px;\n  overflow:hidden;\n  position:relative;\n  display:flex;\n  flex-direction:column;\n}\n.statusbar{\n  height:34px;\n  flex:0 0 34px;\n  display:flex;\n  align-items:flex-end;\n  justify-content:space-between;\n  padding:0 26px 4px;\n  font-size:13px;\n  font-weight:600;\n  position:relative;\n}\n.dynamic-island{\n  position:absolute;\n  top:8px;\n  left:50%;\n  transform:translateX(-50%);\n  width:110px;\n  height:24px;\n  background:#0F0B12;\n  border-radius:16px;\n}\n\n/* fixed home board */\n.main{\n  flex:1;\n  min-height:0;\n  padding:10px 18px 14px;\n  display:flex;\n  flex-direction:column;\n  gap:14px;\n  overflow:hidden;\n}\n.header-row{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n}\n.app-title{\n  font-family:var(--font-display);\n  font-size:19px;\n  font-weight:700;\n  color:var(--plum);\n  margin:0;\n}\n.app-date{\n  margin:3px 0 0;\n  color:var(--muted);\n  font-size:12.5px;\n  font-weight:500;\n}\n.avatar-upload{\n  position:relative;\n  width:42px;\n  height:42px;\n  cursor:pointer;\n  flex-shrink:0;\n}\n.avatar-circle{\n  width:42px;\n  height:42px;\n  border-radius:50%;\n  background:var(--plum);\n  color:#fff;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  font-family:var(--font-display);\n  font-weight:700;\n  font-size:16px;\n  background-size:cover;\n  background-position:center;\n  border:2px solid #fff;\n  box-shadow:0 8px 18px -12px rgba(59,35,84,.46);\n}\n.avatar-cam{\n  position:absolute;\n  bottom:-2px;\n  right:-2px;\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  background:var(--pink);\n  border:2px solid var(--bg);\n  display:flex;\n  align-items:center;\n  justify-content:center;\n}\n.avatar-cam svg{width:10px;height:10px}\n\n/* greeting */\n.greeting{\n  font-family:var(--font-display);\n  font-size:25px;\n  line-height:1.08;\n  font-weight:700;\n  margin:0;\n}\n.greeting-sub{\n  margin:4px 0 0;\n  color:var(--muted);\n  font-size:13.5px;\n}\n\n/* motivation */\n.motivation{\n  border:1px solid #F0DCE7;\n  border-radius:22px;\n  background:\n    linear-gradient(180deg, rgba(252,234,243,.72), rgba(255,255,255,0) 62%),\n    #FFFFFF;\n  padding:15px 16px;\n  box-shadow:0 12px 28px -23px rgba(59,35,84,.32);\n}\n.motivation-head{\n  display:flex;\n  align-items:flex-start;\n  justify-content:space-between;\n  gap:12px;\n}\n.motivation-label{\n  color:var(--pink-deep);\n  font-size:10px;\n  font-weight:800;\n  letter-spacing:.09em;\n  margin-bottom:6px;\n}\n.motivation-text{\n  font-family:var(--font-display);\n  color:var(--plum-dark);\n  font-size:14px;\n  line-height:1.35;\n  font-weight:600;\n  max-width:265px;\n}\n.again-btn{\n  flex-shrink:0;\n  border:none;\n  background:#F8EEF4;\n  color:var(--pink-deep);\n  border-radius:999px;\n  width:34px;\n  height:34px;\n  cursor:pointer;\n  font-size:16px;\n  font-weight:700;\n}\n\n/* sections */\n.section-title{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  margin-bottom:8px;\n  color:var(--muted2);\n  font-size:10.5px;\n  font-weight:800;\n  letter-spacing:.08em;\n}\n.card{\n  background:var(--card);\n  border:1px solid var(--border);\n  border-radius:22px;\n  box-shadow:0 10px 24px -22px rgba(59,35,84,.28);\n}\n\n/* today */\n.today-card{\n  padding:14px 14px 12px;\n}\n.add-icon-btn{\n  width:28px;\n  height:28px;\n  border:none;\n  border-radius:50%;\n  background:var(--pink);\n  color:#fff;\n  font-size:17px;\n  font-weight:800;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  cursor:pointer;\n  box-shadow:0 8px 18px -10px rgba(227,28,121,.55);\n}\n.date-strip{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:5px;\n  background:var(--section-bg);\n  border-radius:999px;\n  padding:5px;\n  margin-bottom:10px;\n}\n.date-strip button{\n  border:none;\n  background:transparent;\n  color:var(--muted);\n  border-radius:999px;\n  padding:7px 4px;\n  font-size:11px;\n  font-weight:700;\n  cursor:pointer;\n}\n.date-strip button.active{\n  background:#fff;\n  color:var(--pink);\n  box-shadow:0 5px 14px -9px rgba(59,35,84,.28);\n}\n.task-row{\n  display:grid;\n  grid-template-columns:20px 58px 1fr 18px;\n  gap:8px;\n  align-items:center;\n  min-height:38px;\n  border-bottom:1px solid var(--border);\n}\n.task-row:last-child{border-bottom:none}\n.checkbox{\n  width:18px;\n  height:18px;\n  border-radius:50%;\n  border:2px solid #E5DAE3;\n  display:flex;\n  align-items:center;\n  justify-content:center;\n  color:transparent;\n  font-size:9px;\n  font-weight:800;\n  cursor:pointer;\n}\n.checkbox.done{\n  background:var(--pink);\n  border-color:var(--pink);\n  color:#fff;\n}\n.task-time{\n  color:var(--muted);\n  font-size:10.8px;\n  font-weight:600;\n  font-variant-numeric:tabular-nums;\n}\n.task-title{\n  color:var(--text);\n  font-size:12.4px;\n  font-weight:650;\n  cursor:pointer;\n}\n.task-row.is-done .task-time,\n.task-row.is-done .task-title{\n  color:var(--muted2);\n  text-decoration:line-through;\n}\n.more-btn{\n  border:none;\n  background:none;\n  color:var(--muted2);\n  padding:0;\n  font-size:16px;\n  cursor:pointer;\n}\n.today-footer{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:10px;\n  margin-top:10px;\n  padding-top:10px;\n  border-top:1px solid var(--border);\n}\n.today-note{\n  color:var(--muted);\n  font-size:10.8px;\n  line-height:1.35;\n}\n.see-all{\n  border:none;\n  background:#F9EEF4;\n  color:var(--pink-deep);\n  border-radius:999px;\n  padding:7px 10px;\n  font-size:10px;\n  font-weight:800;\n  cursor:pointer;\n}\n\n/* health */\n.health-card{\n  padding:15px 14px 13px;\n  background:\n    linear-gradient(180deg, rgba(252,234,243,.45), rgba(255,255,255,0) 58%),\n    #FFFFFF;\n}\n.health-head{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  margin-bottom:12px;\n}\n.health-weight{\n  display:flex;\n  align-items:baseline;\n  gap:8px;\n}\n.health-weight .num{\n  font-family:var(--font-display);\n  font-size:24px;\n  line-height:1;\n  font-weight:800;\n  color:var(--plum);\n}\n.health-weight .delta{\n  color:var(--mint);\n  background:var(--mint-soft);\n  border-radius:999px;\n  padding:4px 7px;\n  font-size:9.5px;\n  font-weight:800;\n}\n.health-link{\n  border:none;\n  background:none;\n  color:var(--pink);\n  font-size:10px;\n  font-weight:800;\n  cursor:pointer;\n}\n.health-grid{\n  display:grid;\n  grid-template-columns:repeat(4,1fr);\n  gap:8px;\n  text-align:center;\n}\n.health-metric{\n  padding:9px 3px 7px;\n  border:1px solid #F1E8EE;\n  background:#FCFAFB;\n  border-radius:15px;\n}\n.health-icon{\n  width:22px;\n  height:22px;\n  margin:0 auto 5px;\n  color:var(--pink);\n}\n.health-value{\n  font-family:var(--font-display);\n  font-size:12.5px;\n  font-weight:700;\n  color:var(--text);\n}\n.health-value .unit{\n  font-size:8.5px;\n  color:var(--muted);\n  font-weight:600;\n}\n.health-sub{\n  margin-top:2px;\n  color:var(--muted);\n  font-size:8.8px;\n  font-weight:500;\n}\n.health-comment{\n  margin-top:10px;\n  padding-top:9px;\n  border-top:1px solid var(--border);\n  color:var(--muted);\n  font-size:10.8px;\n}\n\n/* bottom nav */\n.bottom-nav{\n  flex:0 0 62px;\n  height:62px;\n  background:#fff;\n  border-top:1px solid var(--border);\n  display:flex;\n  padding:7px 4px 9px;\n  box-shadow:0 -8px 22px -22px rgba(59,35,84,.35);\n}\n.nav-item{\n  flex:1;\n  border:none;\n  background:none;\n  color:var(--muted2);\n  display:flex;\n  flex-direction:column;\n  align-items:center;\n  gap:3px;\n  padding:3px 0;\n  cursor:pointer;\n}\n.nav-item svg{width:19px;height:19px}\n.nav-item span{font-size:9px;font-weight:600}\n.nav-item.active{color:var(--pink)}\n\n/* overlays */\n.overlay{\n  position:absolute;\n  inset:0;\n  background:rgba(30,20,35,.42);\n  display:flex;\n  align-items:flex-end;\n  opacity:0;\n  pointer-events:none;\n  transition:opacity .2s ease;\n  z-index:40;\n}\n.overlay.show{opacity:1;pointer-events:auto}\n.sheet{\n  width:100%;\n  max-height:75%;\n  overflow:auto;\n  background:#fff;\n  border-radius:24px 24px 0 0;\n  padding:12px 20px 25px;\n  transform:translateY(100%);\n  transition:transform .26s ease;\n  box-shadow:0 -18px 40px -30px rgba(59,35,84,.45);\n}\n.overlay.show .sheet{transform:translateY(0)}\n.sheet-handle{\n  width:36px;\n  height:4px;\n  background:var(--border);\n  border-radius:999px;\n  margin:0 auto 15px;\n}\n.sheet-title{\n  font-family:var(--font-display);\n  color:var(--plum);\n  font-size:20px;\n  font-weight:800;\n}\n.sheet-sub{\n  color:var(--muted);\n  font-size:11.5px;\n  margin:3px 0 12px;\n}\n.close-x{\n  position:absolute;\n  top:13px;\n  right:16px;\n  width:26px;\n  height:26px;\n  border:none;\n  border-radius:50%;\n  background:var(--section-bg);\n  color:var(--muted);\n  cursor:pointer;\n}\n.sheet-action{\n  width:100%;\n  text-align:left;\n  border:none;\n  background:none;\n  border-top:1px solid var(--border);\n  padding:12px 1px;\n  font-size:13px;\n  font-weight:650;\n  color:var(--text);\n  cursor:pointer;\n}\n.sheet-action:first-of-type{border-top:none}\n.sheet-action.danger{color:#D6413F}\n.field-label{\n  margin:12px 0 5px;\n  color:var(--muted);\n  font-size:10px;\n  font-weight:800;\n}\n.field-input{\n  width:100%;\n  border:1.5px solid var(--border);\n  background:#FBF8FA;\n  border-radius:12px;\n  padding:10px 11px;\n  outline:none;\n}\n.field-input:focus{border-color:var(--pink)}\n.submit-btn{\n  width:100%;\n  border:none;\n  background:var(--pink);\n  color:#fff;\n  border-radius:13px;\n  padding:11px;\n  font-size:11.5px;\n  font-weight:800;\n  margin-top:14px;\n  cursor:pointer;\n}\n.toast{\n  position:absolute;\n  left:50%;\n  bottom:72px;\n  transform:translate(-50%,10px);\n  background:var(--plum);\n  color:#fff;\n  border-radius:999px;\n  padding:8px 13px;\n  font-size:11px;\n  font-weight:700;\n  opacity:0;\n  transition:.2s;\n  z-index:60;\n  white-space:nowrap;\n  pointer-events:none;\n}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n.completion-pop{\n  position:absolute;\n  left:50%;\n  top:50%;\n  transform:translate(-50%,-42%) scale(.96);\n  width:78%;\n  background:#fff;\n  border:1px solid #F0DCE7;\n  border-radius:20px;\n  padding:18px 16px;\n  text-align:center;\n  box-shadow:0 18px 42px -18px rgba(59,35,84,.36);\n  opacity:0;\n  pointer-events:none;\n  z-index:55;\n  transition:.22s;\n}\n.completion-pop.show{\n  opacity:1;\n  transform:translate(-50%,-50%) scale(1);\n}\n.completion-pop .emoji{font-size:28px;line-height:1;margin-bottom:7px}\n.completion-pop .title{\n  font-family:var(--font-display);\n  font-size:16px;\n  font-weight:800;\n  color:var(--plum);\n}\n.completion-pop .copy{\n  margin-top:4px;\n  color:var(--muted);\n  font-size:11px;\n  line-height:1.4;\n}\n\n@media(max-width:430px){\n  body{padding:0}\n  .device{width:100%;padding:0;border-radius:0}\n  .screen{height:100vh;border-radius:0}\n}\n</style>\n<style id=\"app-shell-embedded-overrides\">\nhtml.embedded, html.embedded body{ height:100%; padding:0 !important; margin:0 !important; align-items:stretch !important; justify-content:stretch !important; }\nhtml.embedded .device{ width:100% !important; max-width:100% !important; height:100dvh !important; background:transparent !important; padding:0 !important; border-radius:0 !important; box-shadow:none !important; }\nhtml.embedded .screen{ height:100dvh !important; border-radius:0 !important; padding-top:max(14px, env(safe-area-inset-top)) !important; }\nhtml.embedded .statusbar, html.embedded .status, html.embedded .dynamic-island, html.embedded .island{ display:none !important; }\nhtml.embedded .bottom-nav, html.embedded .bottom{ padding-bottom:max(9px, env(safe-area-inset-bottom)) !important; }\n</style></head>\n<body>\n<div class=\"device\">\n  <div class=\"screen\">\n    <div class=\"statusbar\">\n      <div class=\"dynamic-island\"></div>\n      <span>9:41</span>\n      <span>● ● ▰</span>\n    </div>\n\n    <main class=\"main\">\n      <div class=\"header-row\">\n        <div>\n          <p class=\"app-title\">Johann's Personal Space</p>\n          <p class=\"app-date\" id=\"fullDate\">Friday, September 4</p>\n        </div>\n        <div class=\"avatar-upload\" id=\"avatarUpload\">\n          <div class=\"avatar-circle\" id=\"avatarCircle\">J</div>\n          <div class=\"avatar-cam\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 8h3l1.5-2h7L17 8h3v11H4V8Z\" stroke=\"#fff\" stroke-width=\"2\" stroke-linejoin=\"round\"/><circle cx=\"12\" cy=\"13.5\" r=\"3\" stroke=\"#fff\" stroke-width=\"2\"/></svg>\n          </div>\n          <input type=\"file\" accept=\"image/*\" id=\"avatarInput\" style=\"display:none\">\n        </div>\n      </div>\n\n      <div>\n        <div class=\"greeting\">Ay, gising na. 😭</div>\n        <div class=\"greeting-sub\">Anong motivation mo today?</div>\n      </div>\n\n      <section class=\"motivation\">\n        <div class=\"motivation-head\">\n          <div>\n            <div class=\"motivation-label\">TODAY'S MOTIVATION</div>\n            <div class=\"motivation-text\" id=\"motivationText\"></div>\n          </div>\n          <button class=\"again-btn\" id=\"againBtn\">↻</button>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"section-title\">\n          <span>TODAY OVERVIEW</span>\n          <button class=\"add-icon-btn\" id=\"addIconBtn\">+</button>\n        </div>\n        <div class=\"card today-card\">\n          <div class=\"date-strip\" id=\"dateStrip\"></div>\n          <div id=\"taskList\"></div>\n          <div class=\"today-footer\">\n            <div class=\"today-note\" id=\"todayNote\"></div>\n            <button class=\"see-all\" id=\"seeAllTasks\">See all</button>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"section-title\">\n          <span>HEALTH CHECK</span>\n          <button class=\"health-link\" id=\"seeAllHealth\">See all →</button>\n        </div>\n        <div class=\"card health-card\">\n          <div class=\"health-head\">\n            <div class=\"health-weight\">\n              <span class=\"num\">70.4 kg</span>\n              <span class=\"delta\">↓ 0.6 kg this week</span>\n            </div>\n          </div>\n\n          <div class=\"health-grid\">\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"4\" y=\"7\" width=\"16\" height=\"13\" rx=\"2.5\" stroke=\"currentColor\" stroke-width=\"1.7\"/><path d=\"M9 7V5.5C9 4.1 10.3 3 12 3s3 1.1 3 2.5V7\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/><circle cx=\"12\" cy=\"13\" r=\"1.4\" fill=\"currentColor\"/></svg>\n              <div class=\"health-value\">70.4<span class=\"unit\"> kg</span></div>\n              <div class=\"health-sub\">Weight</div>\n            </div>\n\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 3c1 3-2 4-2 7a4 4 0 0 0 8 0c0-2-1-3-1.5-4 .3 2-1 3-1.5 2C15.5 6 14 4 12 3Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/><path d=\"M8 15a4 4 0 0 0 8 0\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg>\n              <div class=\"health-value\">820<span class=\"unit\"> /1450</span></div>\n              <div class=\"health-sub\">kcal</div>\n            </div>\n\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 3s6 6.5 6 11a6 6 0 0 1-12 0c0-4.5 6-11 6-11Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n              <div class=\"health-value\">4<span class=\"unit\"> / 8</span></div>\n              <div class=\"health-sub\">water</div>\n            </div>\n\n            <div class=\"health-metric\">\n              <svg class=\"health-icon\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M3 17c1-3 3-3 5-4.5S12 8 13 5c.7 1.5 2.5 2 4 2 2 0 3.5 1.3 3.5 3S19.5 13 17 13H8c-2 0-4 1-5 4Z\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/></svg>\n              <div class=\"health-value\">5,420</div>\n              <div class=\"health-sub\">steps</div>\n            </div>\n          </div>\n\n          <div class=\"health-comment\">Okayyy, may movement. 👀</div>\n        </div>\n      </section>\n    </main>\n\n    <nav class=\"bottom-nav\">\n      <button class=\"nav-item active\" data-nav=\"home\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 11.5 12 4l8 7.5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M6 10v9h12v-9\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/></svg>\n        <span>Home</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"today\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"4\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M8.5 12.5 11 15l4.5-5.5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n        <span>Tasks</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"health\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 20s-7-4.4-9.5-9C.7 7.4 3 4 6.5 4 9 4 11 6 12 7.3 13 6 15 4 17.5 4 21 4 23.3 7.4 21.5 11 19 15.6 12 20 12 20Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n        <span>Health</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"budget\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"13\" rx=\"2.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M3 10h18\" stroke=\"currentColor\" stroke-width=\"1.8\"/><circle cx=\"16.5\" cy=\"14.2\" r=\"1.1\" fill=\"currentColor\"/></svg>\n        <span>Budget</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"journal\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M5 4.5h9a2 2 0 0 1 2 2V20l-6.5-3L5 20V4.5Z\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/></svg>\n        <span>Journal</span>\n      </button>\n      <button class=\"nav-item\" data-nav=\"profile\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"8\" r=\"3.2\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M5 20c0-3.9 3.1-6 7-6s7 2.1 7 6\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/></svg>\n        <span>Profile</span>\n      </button>\n    </nav>\n\n    <!-- task detail -->\n    <div class=\"overlay\" id=\"taskOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeTaskSheet\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\" id=\"sheetTaskTitle\">Task</div>\n        <div class=\"sheet-sub\" id=\"sheetTaskTime\">Time · Today</div>\n        <button class=\"sheet-action\" id=\"actEdit\">Edit</button>\n        <button class=\"sheet-action\" id=\"actDuplicate\">Duplicate</button>\n        <button class=\"sheet-action danger\" id=\"actDelete\">Delete</button>\n      </div>\n    </div>\n\n    <!-- add task -->\n    <div class=\"overlay\" id=\"addOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeAddSheet\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\">Add to today</div>\n        <div class=\"sheet-sub\">Ano'ng kailangan natin gawin?</div>\n        <div class=\"field-label\">TASK</div>\n        <input class=\"field-input\" id=\"newTaskTitle\" placeholder=\"Pay electricity bill\">\n        <div class=\"field-label\">TIME · OPTIONAL</div>\n        <input class=\"field-input\" id=\"newTaskTime\" placeholder=\"7:00 PM\">\n        <button class=\"submit-btn\" id=\"submitAdd\">Add</button>\n      </div>\n    </div>\n\n    <!-- edit task -->\n    <div class=\"overlay\" id=\"editOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeEditSheet\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\">Edit task</div>\n        <div class=\"field-label\">TITLE</div>\n        <input class=\"field-input\" id=\"editTaskTitle\">\n        <div class=\"field-label\">TIME</div>\n        <input class=\"field-input\" id=\"editTaskTime\">\n        <button class=\"submit-btn\" id=\"saveEdit\">Save changes</button>\n      </div>\n    </div>\n\n    <!-- all tasks -->\n    <div class=\"overlay\" id=\"allTasksOverlay\">\n      <div class=\"sheet\">\n        <button class=\"close-x\" id=\"closeAllTasks\">✕</button>\n        <div class=\"sheet-handle\"></div>\n        <div class=\"sheet-title\">Today overview</div>\n        <div class=\"sheet-sub\">Everything for this day.</div>\n        <div id=\"allTasksList\"></div>\n        <button class=\"submit-btn\" id=\"addFromAll\">+ Add to today</button>\n      </div>\n    </div>\n\n    <div class=\"completion-pop\" id=\"completionPop\">\n      <div class=\"emoji\">✨</div>\n      <div class=\"title\">Ay wow. Tapos lahat?</div>\n      <div class=\"copy\">Productive legend yarn? You may now disappear peacefully. 😌</div>\n    </div>\n\n    <div class=\"toast\" id=\"toast\"></div>\n  </div>\n</div>\n\n<script src=\"./johanns-db.js\"></script><script>\n(function(){\n  const days = {\n    thu:{label:'Thu 3',tasks:[\n      {id:'t1',time:'8:30 AM',title:'Morning run',done:true},\n      {id:'t2',time:'1:00 PM',title:'Client call',done:true},\n      {id:'t3',time:'5:00 PM',title:'Buy groceries',done:false},\n      {id:'t4',time:'9:00 PM',title:'Renew insurance',done:false}\n    ]},\n    fri:{label:'FRI 4',tasks:[\n      {id:'f1',time:'9:00 AM',title:'Team check-in',done:false},\n      {id:'f2',time:'11:30 AM',title:'Lunch',done:true},\n      {id:'f3',time:'2:30 PM',title:'Dentist',done:false},\n      {id:'f4',time:'6:00 PM',title:'30-minute walk',done:false}\n    ]},\n    sat:{label:'Sat 5',tasks:[\n      {id:'s1',time:'10:00 AM',title:'Laundry',done:false}\n    ]}\n  };\n\n  const motivations = [\n    \"Hindi mo kailangan i-fix ang buong buhay today. Small wins muna. Main character ka pa rin kahit loading. ✨\",\n    \"Okay lang kung slow. Progress pa rin 'yan kahit hindi dramatic.\",\n    \"Isang bagay lang sa isang pagkakataon. Hindi tayo nagse-speedrun ng life today. 🌱\",\n    \"Not everything has to be productive. Minsan ang pahinga ay part ng plot. 🫶\"\n  ];\n\n  const visibleLimit = 3;\n  const celebratedDays = new Set();\n  let currentDay = 'fri';\n  let activeTask = null;\n  let motivationIndex = 0;\n\n  const dateStrip = document.getElementById('dateStrip');\n  const taskList = document.getElementById('taskList');\n  const todayNote = document.getElementById('todayNote');\n  const motivationText = document.getElementById('motivationText');\n  const allTasksList = document.getElementById('allTasksList');\n  const toast = document.getElementById('toast');\n  const completionPop = document.getElementById('completionPop');\n\n  function showToast(msg){\n    toast.textContent = msg;\n    toast.classList.add('show');\n    clearTimeout(window.__toast);\n    window.__toast = setTimeout(()=>toast.classList.remove('show'),1600);\n  }\n\n  function showCompletion(){\n    completionPop.classList.add('show');\n    clearTimeout(window.__complete);\n    window.__complete = setTimeout(()=>completionPop.classList.remove('show'),2200);\n  }\n\n  function open(id){ document.getElementById(id).classList.add('show'); }\n  function close(id){ document.getElementById(id).classList.remove('show'); }\n\n  document.querySelectorAll('.overlay').forEach(o=>{\n    o.onclick = e=>{ if(e.target===o) o.classList.remove('show'); };\n  });\n\n  function tasks(){ return days[currentDay].tasks; }\n\n  function renderDateStrip(){\n    dateStrip.innerHTML = '';\n    ['thu','fri','sat'].forEach(key=>{\n      const btn = document.createElement('button');\n      btn.textContent = days[key].label;\n      if(key===currentDay) btn.classList.add('active');\n      btn.onclick = ()=>{\n        currentDay = key;\n        renderDateStrip();\n        renderTasks();\n      };\n      dateStrip.appendChild(btn);\n    });\n  }\n\n  function renderTasks(){\n    const list = tasks();\n    taskList.innerHTML = '';\n\n    list.slice(0,visibleLimit).forEach(task=>{\n      const row = document.createElement('div');\n      row.className = 'task-row' + (task.done ? ' is-done' : '');\n      row.innerHTML = `\n        <div class=\"checkbox ${task.done ? 'done' : ''}\">${task.done ? '✓' : ''}</div>\n        <div class=\"task-time\">${task.time}</div>\n        <div class=\"task-title\">${task.title}</div>\n        <button class=\"more-btn\">⋯</button>\n      `;\n      row.querySelector('.checkbox').onclick = e=>{\n        e.stopPropagation();\n        task.done = !task.done;\n        renderTasks();\n      };\n      row.querySelector('.task-title').onclick = ()=>openTask(task);\n      row.querySelector('.more-btn').onclick = e=>{ e.stopPropagation(); openTask(task); };\n      taskList.appendChild(row);\n    });\n\n    const done = list.filter(t=>t.done).length;\n    const allDone = list.length>0 && done===list.length;\n    const hidden = Math.max(0,list.length-visibleLimit);\n\n    if(allDone){\n      todayNote.textContent = \"Tapos na lahat. Suspiciously organized. 😌\";\n      if(!celebratedDays.has(currentDay)){\n        celebratedDays.add(currentDay);\n        setTimeout(showCompletion,120);\n      }\n    }else{\n      celebratedDays.delete(currentDay);\n      if(hidden>0) todayNote.textContent = `+ ${hidden} more waiting quietly.`;\n      else todayNote.textContent = \"One glance lang. Details when you need them.\";\n    }\n\n    renderAllTasks();\n  }\n\n  function renderAllTasks(){\n    allTasksList.innerHTML = '';\n    tasks().forEach(task=>{\n      const btn = document.createElement('button');\n      btn.className = 'sheet-action';\n      btn.textContent = `${task.done?'✓':'○'}  ${task.time} · ${task.title}`;\n      btn.onclick = ()=>{\n        close('allTasksOverlay');\n        setTimeout(()=>openTask(task),100);\n      };\n      allTasksList.appendChild(btn);\n    });\n  }\n\n  function openTask(task){\n    activeTask = task;\n    document.getElementById('sheetTaskTitle').textContent = task.title;\n    document.getElementById('sheetTaskTime').textContent = task.time + ' · Today';\n    open('taskOverlay');\n  }\n\n  function renderMotivation(){\n    motivationText.textContent = motivations[motivationIndex];\n  }\n\n  document.getElementById('againBtn').onclick = ()=>{\n    motivationIndex = (motivationIndex+1)%motivations.length;\n    renderMotivation();\n  };\n\n  document.getElementById('addIconBtn').onclick = ()=>{\n    document.getElementById('newTaskTitle').value='';\n    document.getElementById('newTaskTime').value='';\n    open('addOverlay');\n  };\n  document.getElementById('closeAddSheet').onclick = ()=>close('addOverlay');\n  document.getElementById('submitAdd').onclick = ()=>{\n    const title = document.getElementById('newTaskTitle').value.trim();\n    const time = document.getElementById('newTaskTime').value.trim() || '—';\n    if(!title){ showToast('Add a title first'); return; }\n    tasks().push({id:'new-'+Date.now(),time,title,done:false});\n    close('addOverlay');\n    renderTasks();\n    showToast('Added to today');\n  };\n\n  document.getElementById('closeTaskSheet').onclick = ()=>close('taskOverlay');\n  document.getElementById('actDelete').onclick = ()=>{\n    const list = tasks();\n    const i = list.findIndex(t=>t.id===activeTask.id);\n    if(i>-1) list.splice(i,1);\n    close('taskOverlay');\n    renderTasks();\n    showToast('Deleted');\n  };\n  document.getElementById('actDuplicate').onclick = ()=>{\n    tasks().push({id:'dup-'+Date.now(),time:activeTask.time,title:activeTask.title,done:false});\n    close('taskOverlay');\n    renderTasks();\n    showToast('Duplicated');\n  };\n  document.getElementById('actEdit').onclick = ()=>{\n    close('taskOverlay');\n    document.getElementById('editTaskTitle').value = activeTask.title;\n    document.getElementById('editTaskTime').value = activeTask.time;\n    setTimeout(()=>open('editOverlay'),100);\n  };\n  document.getElementById('closeEditSheet').onclick = ()=>close('editOverlay');\n  document.getElementById('saveEdit').onclick = ()=>{\n    activeTask.title = document.getElementById('editTaskTitle').value || activeTask.title;\n    activeTask.time = document.getElementById('editTaskTime').value || activeTask.time;\n    close('editOverlay');\n    renderTasks();\n    showToast('Saved');\n  };\n\n  document.getElementById('seeAllTasks').onclick = ()=>open('allTasksOverlay');\n  document.getElementById('closeAllTasks').onclick = ()=>close('allTasksOverlay');\n  document.getElementById('addFromAll').onclick = ()=>{\n    close('allTasksOverlay');\n    setTimeout(()=>open('addOverlay'),100);\n  };\n\n  document.getElementById('seeAllHealth').onclick = ()=>showToast('Full Health view — coming soon');\n\n  document.querySelectorAll('.nav-item').forEach(item=>{\n    item.onclick = ()=>{\n      document.querySelectorAll('.nav-item').forEach(i=>i.classList.remove('active'));\n      item.classList.add('active');\n      if(item.dataset.nav!=='home') showToast(item.dataset.nav.charAt(0).toUpperCase()+item.dataset.nav.slice(1)+' — coming soon');\n    };\n  });\n\n  const avatarUpload = document.getElementById('avatarUpload');\n  const avatarInput = document.getElementById('avatarInput');\n  const avatarCircle = document.getElementById('avatarCircle');\n  avatarUpload.onclick = ()=>avatarInput.click();\n  avatarInput.onchange = e=>{\n    const file = e.target.files[0];\n    if(!file) return;\n    const url = URL.createObjectURL(file);\n    avatarCircle.style.backgroundImage = `url(${url})`;\n    avatarCircle.textContent = '';\n    showToast('Profile photo updated');\n  };\n\n  document.getElementById('fullDate').textContent = new Date().toLocaleDateString('en-US',{\n    weekday:'long',month:'long',day:'numeric'\n  });\n\n  renderDateStrip();\n  renderTasks();\n  renderMotivation();\n})();\n</script>\n<style>\n  .journal-main{flex:1;min-height:0;padding:10px 18px 14px;display:flex;flex-direction:column;gap:13px;overflow:hidden}\n  .journal-intro h1{font-family:var(--font-display);font-size:25px;line-height:1.08;margin:0;color:var(--text)}\n  .journal-intro p{font-size:13.5px;color:var(--muted);margin:4px 0 0}\n  .journal-actions{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}\n  .journal-kind{border:1px solid var(--border);background:#fff;border-radius:16px;padding:10px 4px 8px;color:var(--plum);font-size:10px;font-weight:700;cursor:pointer}\n  .journal-kind.active{border-color:var(--pink);background:var(--pink-soft);color:var(--pink-deep)}\n  .journal-kind span{display:block;font-size:20px;margin-bottom:4px}\n  .today-word{border:1px solid #F0DCE7;border-radius:22px;background:linear-gradient(180deg,rgba(252,234,243,.72),rgba(255,255,255,0) 62%),#fff;padding:14px 15px;box-shadow:0 12px 28px -23px rgba(59,35,84,.32)}\n  .word-head{display:flex;align-items:center;justify-content:space-between}.word-label{font-size:10px;letter-spacing:.09em;font-weight:800;color:var(--pink-deep)}\n  .word-verse{font-family:var(--font-display);font-size:14px;line-height:1.35;font-weight:600;color:var(--plum-dark);margin-top:7px}\n  .word-ref{font-size:11px;color:var(--muted);margin-top:3px}.word-story{font-size:11.5px;line-height:1.42;color:var(--muted);margin:7px 0 0}\n  .word-links{display:flex;gap:13px;margin-top:8px}.word-links button{border:0;background:transparent;padding:0;color:var(--pink-deep);font-size:10.5px;font-weight:700;cursor:pointer}\n  .journal-section-title{display:flex;justify-content:space-between;align-items:center;color:var(--muted2);font-size:10.5px;font-weight:800;letter-spacing:.08em}\n  .journal-section-title select{border:0;background:transparent;color:var(--pink-deep);font-size:10.5px;font-weight:700;outline:none}\n  .entry-list{display:flex;flex-direction:column;gap:9px;min-height:0;overflow:hidden}\n  .entry-card{border:1px solid var(--border);border-radius:19px;background:#fff;min-height:98px;display:flex;overflow:hidden;cursor:pointer;box-shadow:0 10px 24px -22px rgba(59,35,84,.28)}\n  .entry-copy{padding:11px 8px 10px 12px;display:flex;flex:1;min-width:0;flex-direction:column}\n  .entry-photo-strip{flex:0 0 78px;padding:7px;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:4px;background:#f6eff4}\n  .entry-photo-strip.one{grid-template-columns:1fr;grid-template-rows:1fr}.entry-photo-strip.two{grid-template-columns:1fr;grid-template-rows:1fr 1fr}\n  .entry-thumb{border-radius:7px;background:#e7dce4;display:flex;align-items:center;justify-content:center;font-size:17px;overflow:hidden}.entry-thumb:first-child{grid-row:1 / span 2}.entry-photo-strip.two .entry-thumb:first-child,.entry-photo-strip.one .entry-thumb:first-child{grid-row:auto}\n  .entry-card.photo-entry{background:linear-gradient(0deg,rgba(42,23,64,.78),rgba(42,23,64,.1)),var(--entry-photo) center/cover;color:#fff;border:0}\n  .entry-type{font-size:9px;font-weight:800;letter-spacing:.07em;color:var(--pink-deep)}.photo-entry .entry-type{color:#fff}\n  .entry-card h3{font-family:var(--font-display);font-size:14px;line-height:1.18;margin:6px 0 3px}.entry-card p{font-size:10.5px;line-height:1.35;color:var(--muted);margin:0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.photo-entry p{color:#fff}\n  .entry-date{font-size:9.5px;color:var(--muted2);margin-top:auto;padding-top:7px}.photo-entry .entry-date{color:#fff}\n  .new-entry-fab{position:absolute;right:20px;bottom:74px;width:48px;height:48px;border-radius:50%;border:0;background:var(--pink);color:#fff;font-size:25px;box-shadow:0 12px 24px -10px rgba(227,28,121,.65);z-index:6;cursor:pointer}\n  .journal-sheet .sheet{padding-bottom:22px}.entry-types{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.entry-type-btn{border:1px solid var(--border);background:#fff;border-radius:16px;padding:10px;text-align:left;color:var(--plum);font-size:12px}.entry-type-btn.active{border-color:var(--pink);background:var(--pink-soft)}\n  .journal-sheet textarea{min-height:125px;resize:vertical}.photo-previews{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:8px}.photo-previews img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px}.photo-status{font-size:10.5px;color:var(--muted);margin-top:6px}\n</style>\n<script>\n(function(){\n  const screen=document.querySelector('.screen');\n  screen.innerHTML=`\n    <div class=\"statusbar\"><div class=\"dynamic-island\"></div><span>9:41</span><span>● ● ▰</span></div>\n    <main class=\"journal-main\">\n      <div class=\"header-row\"><div><p class=\"app-title\">Johann's Personal Space</p><p class=\"app-date\">Friday, September 4</p></div><div class=\"avatar-upload\"><div class=\"avatar-circle\">J</div></div></div>\n      <div class=\"journal-intro\"><h1>Sige, ilabas mo ’yan. 😭</h1><p>For legal reasons, between you, this journal, and God lang ’to.</p></div>\n      <div class=\"journal-actions\">\n        <button class=\"journal-kind\" data-type=\"journal\"><span>📖</span>Main character</button><button class=\"journal-kind\" data-type=\"prayer\"><span>🙏</span>Lord, me again</button><button class=\"journal-kind\" data-type=\"rhema\"><span>✨</span>Wait, that’s for me</button><button class=\"journal-kind\" data-type=\"brain\"><span>☁️</span>Unload lahat</button>\n      </div>\n      <section class=\"today-word\"><div class=\"word-head\"><div class=\"word-label\">VERSE CHECK—BAKA PARA SA’YO ’TO</div><button class=\"again-btn\" id=\"anotherVerse\">↻</button></div><div class=\"word-verse\" id=\"jVerse\"></div><div class=\"word-ref\" id=\"jRef\"></div><p class=\"word-story\" id=\"jStory\"></p><div class=\"word-links\"><button id=\"saveRhema\">Okay, tinamaan ako</button><button id=\"turnPrayer\">Lord, pag-usapan natin ’to</button></div></section>\n      <div class=\"journal-section-title\"><span>PREVIOUSLY ON: MY LIFE</span><select id=\"journalFilter\"><option value=\"all\">Lahat ng lore</option><option value=\"journal\">Main character moments</option><option value=\"prayer\">Lord, me again</option><option value=\"rhema\">Tinamaan ako</option><option value=\"brain\">Mental tabs</option></select></div>\n      <div class=\"entry-list\" id=\"entryList\"></div>\n    </main>\n    <button class=\"new-entry-fab\" id=\"newEntry\" aria-label=\"Create journal entry\">+</button>\n    <nav class=\"bottom-nav\">\n      <button class=\"nav-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M4 11.5 12 4l8 7.5M6 10v9h12v-9\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg><span>Home</span></button>\n      <button class=\"nav-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"4\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"m8.5 12.5 2.5 2.5 4.5-5.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg><span>Tasks</span></button>\n      <button class=\"nav-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M12 20s-7-4.4-9.5-9C.7 7.4 3 4 6.5 4 9 4 11 6 12 7.3 13 6 15 4 17.5 4 21 4 23.3 7.4 21.5 11 19 15.6 12 20 12 20Z\" stroke=\"currentColor\" stroke-width=\"1.7\"/></svg><span>Health</span></button>\n      <button class=\"nav-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><rect x=\"3\" y=\"6\" width=\"18\" height=\"13\" rx=\"2.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M3 10h18\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg><span>Budget</span></button>\n      <button class=\"nav-item active\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M5 4.5h9a2 2 0 0 1 2 2V20l-6.5-3L5 20V4.5Z\" stroke=\"currentColor\" stroke-width=\"1.7\"/></svg><span>Journal</span></button>\n      <button class=\"nav-item\"><svg viewBox=\"0 0 24 24\" fill=\"none\"><circle cx=\"12\" cy=\"8\" r=\"3.2\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M5 20c0-3.9 3.1-6 7-6s7 2.1 7 6\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg><span>Profile</span></button>\n    </nav>\n    <div class=\"overlay journal-sheet\" id=\"journalOverlay\"><div class=\"sheet\"><div class=\"handle\"></div><div class=\"sheet-head\"><div><h3 id=\"entryHeading\">New entry, new lore</h3><p>Hindi ito essay. Walang grammar police dito.</p></div><button class=\"close-x\" id=\"closeJournal\">✕</button></div><div class=\"entry-types\"><button class=\"entry-type-btn active\" data-type=\"journal\">📖 Main character</button><button class=\"entry-type-btn\" data-type=\"prayer\">🙏 Lord, me again</button><button class=\"entry-type-btn\" data-type=\"rhema\">✨ Tinamaan ako</button><button class=\"entry-type-btn\" data-type=\"brain\">☁️ Mental tabs</button></div><label>Anong episode ’to? (optional)</label><input id=\"journalTitle\" placeholder=\"Name this episode—or huwag, okay lang\"><div id=\"rhemaField\" style=\"display:none\"><label>Anong verse ang nanampal?</label><input id=\"journalRhema\" placeholder=\"e.g. Psalm 46:10\"></div><label>Okay, anong nangyari?</label><textarea id=\"journalBody\" placeholder=\"Type mo lang. Kahit magulo. Gets natin ’yan.\"></textarea><label>May resibo? (optional)</label><input id=\"journalPhotos\" type=\"file\" accept=\"image/*\" multiple><div class=\"photo-status\" id=\"photoStatus\">Dito lang ’to sa device mo. Auto-compressed para hindi OA sa storage.</div><div class=\"photo-previews\" id=\"photoPreviews\"></div><button class=\"submit-btn\" id=\"saveJournal\">Okay, keep this</button></div></div>\n    <div class=\"toast\" id=\"toast\">Filed under: character development ✨</div>`;\n\n  const verses=[\n    {v:'“Be still, and know that I am God.”',r:'Psalm 46:10',s:'Ate ko, baka hindi lahat kailangan i-overthink tonight. Anong pwede mong ibaba muna?'},\n    {v:'“His mercies are new every morning.”',r:'Lamentations 3:23',s:'Good news: hindi final version ng buhay mo ang kahapon. May fresh mercy ulit today.'},\n    {v:'“Let all that you do be done in love.”',r:'1 Corinthians 16:14',s:'Before tayo mag-reply nang may kasamang screenshot sa group chat—love muna. Kahit konti.'}\n  ];\n  let verseIndex=Math.floor(Math.random()*verses.length),activeType='journal',photos=[];\n  let entries=[\n    {type:'journal',title:'Sunday plot twist',body:'Akala ko bad day. Kailangan ko lang pala kumain at makipag-chismisan sa family.',date:'Sep 1',photos:['🌇','🍜','🫶']},\n    {type:'prayer',title:'Lord, patience please',body:'Preferably before ako mag-reply. Amen.',date:'Aug 30',photos:['🌤️']},\n    {type:'rhema',title:'Okay, tinamaan ako',body:'Hindi ko pala kailangang buhatin lahat sabay-sabay. Noted po.',date:'Aug 28',photos:[]},\n    {type:'brain',title:'47 tabs open',body:'Meeting. Groceries. Call Mama. Tubig. Huminga. Bakit may meeting ulit?',date:'Aug 27',photos:['🗒️','☕']}\n  ];\n  function showVerse(){const x=verses[verseIndex];document.getElementById('jVerse').textContent=x.v;document.getElementById('jRef').textContent=x.r;document.getElementById('jStory').textContent=x.s}\n  function render(){const f=document.getElementById('journalFilter').value,list=document.getElementById('entryList');list.innerHTML='';entries.filter(e=>f==='all'||e.type===f).slice(0,4).forEach(e=>{const card=document.createElement('article');card.className='entry-card';const pics=e.photos||[];const strip=pics.length?`<div class=\"entry-photo-strip ${pics.length===1?'one':pics.length===2?'two':''}\">${pics.slice(0,3).map(p=>`<div class=\"entry-thumb\">${String(p).startsWith('blob:')?`<img src=\"${p}\" alt=\"Journal photo\" style=\"width:100%;height:100%;object-fit:cover\">`:p}</div>`).join('')}</div>`:'';card.innerHTML=`<div class=\"entry-copy\"><div class=\"entry-type\">${({journal:'MAIN CHARACTER MOMENT',prayer:'LORD, ME AGAIN',rhema:'TINAMAAN AKO',brain:'MENTAL TABS'})[e.type]}</div><h3>${e.title}</h3><p>${e.body}</p><div class=\"entry-date\">${e.date}</div></div>${strip}`;list.appendChild(card)})}\n  function open(type='journal'){activeType=type;document.querySelectorAll('.entry-type-btn').forEach(b=>b.classList.toggle('active',b.dataset.type===type));document.getElementById('rhemaField').style.display=type==='rhema'?'block':'none';document.getElementById('entryHeading').textContent=({journal:'New entry, new lore',prayer:'Lord, it’s me again',rhema:'Okay, this one’s for me',brain:'Close some mental tabs'})[type];document.getElementById('journalOverlay').classList.add('show')}\n  function close(){document.getElementById('journalOverlay').classList.remove('show')}\n  async function compress(file){const bmp=await createImageBitmap(file,{imageOrientation:'from-image'}),scale=Math.min(1,1400/Math.max(bmp.width,bmp.height)),c=document.createElement('canvas');c.width=Math.round(bmp.width*scale);c.height=Math.round(bmp.height*scale);c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);bmp.close();return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(),'image/webp',.78))}\n  document.getElementById('anotherVerse').onclick=()=>{verseIndex=(verseIndex+1)%verses.length;showVerse()};document.getElementById('newEntry').onclick=()=>open();document.querySelectorAll('.journal-kind').forEach(b=>b.onclick=()=>{const f=document.getElementById('journalFilter'),same=f.value===b.dataset.type;f.value=same?'all':b.dataset.type;document.querySelectorAll('.journal-kind').forEach(x=>x.classList.toggle('active',!same&&x===b));render()});document.querySelectorAll('.entry-type-btn').forEach(b=>b.onclick=()=>open(b.dataset.type));document.getElementById('closeJournal').onclick=close;document.getElementById('saveRhema').onclick=()=>{open('rhema');document.getElementById('journalRhema').value=verses[verseIndex].r};document.getElementById('turnPrayer').onclick=()=>open('prayer');document.getElementById('journalFilter').onchange=()=>{document.querySelectorAll('.journal-kind').forEach(b=>b.classList.toggle('active',b.dataset.type===document.getElementById('journalFilter').value));render()};\n  document.getElementById('journalPhotos').onchange=async e=>{const status=document.getElementById('photoStatus'),preview=document.getElementById('photoPreviews');status.textContent='Wait lang, pinapaliit natin ang file—hindi ang memory. 😭';try{for(const f of e.target.files){const blob=await compress(f);photos.push(blob);const img=document.createElement('img');img.src=URL.createObjectURL(blob);preview.appendChild(img)}status.textContent=`${photos.length} photo${photos.length===1?'':'s'} ready. Storage-friendly na, slay.`}catch(err){status.textContent='Ayaw makisama ng isang photo. Safe pa rin ang sinulat mo.'}};\n  document.getElementById('saveJournal').onclick=async()=>{const body=document.getElementById('journalBody').value.trim();if(!body&&!photos.length)return;const key='pwa-entry:'+Date.now()+'-'+Math.random().toString(16).slice(2),ids=[];for(const blob of photos){const id='image:'+Date.now()+'-'+Math.random().toString(16).slice(2);await JDB.put('images',id,blob);ids.push(id)}const entry={type:activeType,title:document.getElementById('journalTitle').value.trim()||'Untitled',body:body||'Photo memory',date:'Today',createdAt:Date.now(),photoIds:ids,photos:photos.map(b=>URL.createObjectURL(b))};await JDB.put('journalEntries',key,{...entry,photos:[]});entries.unshift(entry);document.getElementById('journalTitle').value=document.getElementById('journalBody').value=document.getElementById('journalRhema').value='';document.getElementById('photoPreviews').innerHTML='';photos=[];close();render();const t=document.getElementById('toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)};\n  async function loadSaved(){const rows=(await JDB.getAll('journalEntries')).filter(x=>String(x.key).startsWith('pwa-entry:')).sort((a,b)=>(b.value.createdAt||0)-(a.value.createdAt||0)),saved=[];for(const row of rows){const e=row.value;e.photos=[];for(const id of e.photoIds||[]){const blob=await JDB.get('images',id);if(blob)e.photos.push(URL.createObjectURL(blob))}saved.push(e)}entries=[...saved,...entries];render()}\n  showVerse();render();loadSaved();\n})();\n</script>\n<script src=\"./pwa-core.js\"></script></body>\n</html>\n"};
